import type { BankQuestion } from "@/lib/bank";

/** Financial & Cost Accounting (Management & Commerce): 715 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-accounting-1","question":"A trader starts business with cash ₹5,00,000, buys goods for ₹1,20,000 on credit and sells goods costing ₹40,000 for ₹55,000 in cash. What are the total assets after these transactions?","options":["₹6,20,000","₹6,35,000","₹6,75,000","₹5,15,000"],"answer":1,"explanation":"Cash = 5,00,000 + 55,000 = ₹5,55,000; stock = 1,20,000 − 40,000 = ₹80,000. Total assets = ₹6,35,000 (= creditors 1,20,000 + capital 5,15,000, the capital including the ₹15,000 profit). ₹6,20,000 ignores the profit and ₹6,75,000 forgets to reduce the stock sold.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-2","question":"Which of these errors will NOT cause the trial balance to disagree?","options":["The sales book is overcast by ₹2,000","A debit of ₹500 is posted to the credit side of a supplier's account","Machinery bought for ₹50,000 is debited to the Purchases account","A sales invoice of ₹3,000 is posted to the Sales account but not to the customer's account"],"answer":2,"explanation":"Debiting machinery to Purchases is an error of principle: the debit is still a debit of the right amount, so the totals agree. The other three are one-sided errors that change only one side of the trial balance.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-3","question":"After a suspense account has been opened, it is found that the sales book was undercast by ₹2,000. What is the rectifying entry?","options":["Sales A/c Dr ₹2,000 To Suspense A/c ₹2,000","Debtors A/c Dr ₹2,000 To Sales A/c ₹2,000","Suspense A/c Dr ₹2,000 To Sales A/c ₹2,000","No entry is needed because the debtors were posted correctly"],"answer":2,"explanation":"Undercasting the sales book means the Sales account was credited ₹2,000 too little, while the individual debtors were debited correctly. Only the Sales account needs a further credit, and the other side goes to Suspense: Suspense Dr, Sales Cr.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-4","question":"A trial balance does not agree and the difference is put in a suspense account. The only errors are: (a) the purchase returns book was overcast by ₹1,000; (b) salary of ₹2,500 was posted to the Salary account as ₹5,200; (c) discount allowed of ₹400 was not posted to the Discount account. What was the suspense account balance?","options":["₹1,300 debit","₹4,100 credit","₹3,300 debit","₹1,300 credit"],"answer":3,"explanation":"(a) Credit side too high by ₹1,000. (b) Debit side too high by ₹2,700. (c) Debit side too low by ₹400. Net: debits exceed credits by 2,700 − 400 − 1,000 = ₹1,300, so the suspense account needed a credit of ₹1,300 to make the totals agree.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-5","question":"A machine is bought on 1 July 2022 for ₹4,80,000 and ₹20,000 is spent on installing it. Residual value is ₹50,000 and useful life 9 years. With the financial year ending 31 March and straight-line depreciation, what is the charge for 2022-23?","options":["₹37,500","₹50,000","₹41,667","₹35,833"],"answer":0,"explanation":"Cost = 4,80,000 + 20,000 = ₹5,00,000 (installation is capitalised). Annual charge = (5,00,000 − 50,000) ÷ 9 = ₹50,000. For 9 months (July to March): 50,000 × 9/12 = ₹37,500. ₹35,833 leaves out installation; ₹50,000 ignores time.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-6","question":"An asset bought on 1 April 2021 for ₹8,00,000 is depreciated at 20% a year on the written-down value. It is sold on 30 September 2023 for ₹4,50,000. What is the profit or loss on sale (year ends 31 March)?","options":["Loss ₹62,000","Profit ₹40,400","Loss ₹10,800","Profit ₹10,800"],"answer":2,"explanation":"Book value on 31 Mar 2022 = 6,40,000; on 31 Mar 2023 = 5,12,000. Depreciation for April–September 2023 = 5,12,000 × 20% × 6/12 = 51,200, so book value at sale = ₹4,60,800. Loss = 4,60,800 − 4,50,000 = ₹10,800. Skipping the half-year charge gives a ₹62,000 loss; charging a full year gives a ₹40,400 profit.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-7","question":"An asset costs ₹2,00,000. What is the difference between total depreciation over the first three years at 10% straight-line on cost and at 10% on the written-down value?","options":["₹6,000","₹5,800","₹4,200","₹5,420"],"answer":1,"explanation":"SLM: 20,000 × 3 = ₹60,000. WDV: 20,000 + 18,000 + 16,200 = ₹54,200. Difference = ₹5,800.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-8","question":"A machine costing ₹6,40,000 is expected to be worth ₹2,70,000 after 3 years. What written-down-value rate writes it down to exactly that amount?","options":["19.27%","20%","30%","25%"],"answer":3,"explanation":"(1 − r)³ = 2,70,000 ÷ 6,40,000 = 27/64, so 1 − r = 3/4 and r = 25%. Check: 6,40,000 → 4,80,000 → 3,60,000 → 2,70,000. 19.27% is the straight-line rate on cost, (6,40,000 − 2,70,000) ÷ 3 ÷ 6,40,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-9","question":"Machinery costing ₹6,00,000 was bought on 1 April 2021. A new machine costing ₹2,00,000 is bought on 1 October 2023, and on 1 January 2024 one of the original machines (cost ₹1,00,000) is sold. Depreciation is 10% straight-line on cost. What is the total depreciation for 2023-24 (year ending 31 March)?","options":["₹70,000","₹60,000","₹67,500","₹77,500"],"answer":2,"explanation":"Remaining old machines: 5,00,000 × 10% = ₹50,000. Machine sold: 1,00,000 × 10% × 9/12 = ₹7,500. New machine: 2,00,000 × 10% × 6/12 = ₹10,000. Total = ₹67,500. ₹77,500 charges the full ₹60,000 on the old block and then adds the sold machine again.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-10","question":"A machine costing ₹1,00,000 was bought on 1 April 2021 and is depreciated at 10% straight-line on cost (year ends 31 March). It is sold on 1 January 2024 for ₹70,000. What is the result of the sale?","options":["Loss ₹10,000","Loss ₹2,500","Neither profit nor loss","Profit ₹2,500"],"answer":1,"explanation":"Depreciation: 2021-22 ₹10,000, 2022-23 ₹10,000, 1 Apr–31 Dec 2023 ₹7,500 → accumulated ₹27,500, book value ₹72,500. Sale at ₹70,000 gives a loss of ₹2,500. Ignoring the current-year charge gives a ₹10,000 loss; charging a full year gives no profit or loss.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-11","question":"Which of these are capital expenditure? (i) Wages paid to the firm's own workers for installing a new machine (ii) Replacing the worn-out tyres of a delivery van (iii) Overhauling a second-hand truck immediately after buying it, before first use (iv) Extending the factory building to raise capacity (v) Annual maintenance contract fee","options":["(i) and (iv) only","(i), (iii) and (iv) only","(i), (ii), (iii) and (iv)","(iii) and (iv) only"],"answer":1,"explanation":"Installation wages and overhaul needed to bring a newly bought asset into use are part of its cost; an extension raises capacity. Replacing worn tyres and AMC fees only maintain the asset, so they are revenue expenditure.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-12","question":"Valuing closing stock at the lower of cost and net realisable value follows which accounting concept?","options":["Prudence (conservatism)","Matching","Going concern","Money measurement"],"answer":0,"explanation":"Prudence: provide for expected losses but do not anticipate gains, so stock is written down when its NRV falls below cost.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-13","question":"Closing stock consists of Item A (cost ₹50,000, NRV ₹60,000) and Item B (cost ₹70,000, NRV ₹45,000). At what amount should it appear in the balance sheet under Ind AS 2?","options":["₹1,05,000","₹1,20,000","₹95,000","₹1,10,000"],"answer":2,"explanation":"Ind AS 2 applies the lower of cost and NRV item by item: A at ₹50,000 (cost), B at ₹45,000 (NRV) = ₹95,000. Comparing the totals (₹1,20,000 vs ₹1,05,000) lets A's unrealised gain offset B's loss, which the standard does not allow.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-14","question":"A credit sale of ₹7,500 to Ravi was entered in the purchases book and posted from there. What is the effect on gross profit?","options":["Understated by ₹7,500","Overstated by ₹7,500","No effect","Understated by ₹15,000"],"answer":3,"explanation":"Sales are understated by ₹7,500 and purchases overstated by ₹7,500; both reduce gross profit, so it is understated by ₹15,000. (Ravi's account is also credited instead of debited, a ₹15,000 swing on his balance.)","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-15","question":"Goods of ₹6,000 taken by the proprietor for personal use last year were never recorded. The books for last year are closed. What entry rectifies this in the current year?","options":["Drawings A/c Dr To Purchases A/c ₹6,000","Drawings A/c Dr To Profit & Loss Adjustment A/c ₹6,000","Purchases A/c Dr To Drawings A/c ₹6,000","Capital A/c Dr To Suspense A/c ₹6,000"],"answer":1,"explanation":"Last year's purchases were overstated (profit understated). The Purchases account is closed, so the nominal-account side goes to a Profit & Loss Adjustment account: Drawings Dr, P&L Adjustment Cr ₹6,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-16","question":"Net profit before finding these errors is ₹1,50,000: (a) furniture of ₹12,000 bought at the start of the year was debited to Purchases (depreciation on furniture is 10%); (b) the sales returns book was overcast by ₹1,500; (c) rent of ₹4,000 paid was debited to the landlord's personal account. What is the corrected net profit?","options":["₹1,59,500","₹1,58,300","₹1,66,300","₹1,55,300"],"answer":1,"explanation":"(a) +12,000 for the wrong expense, −1,200 depreciation. (b) Returns were overstated, so sales were cut too much: +1,500. (c) Rent expense was missing: −4,000. 1,50,000 + 12,000 − 1,200 + 1,500 − 4,000 = ₹1,58,300.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-17","question":"Which of these normally has a credit balance in a trial balance?","options":["Drawings","Provision for doubtful debts","Discount allowed","Prepaid insurance"],"answer":1,"explanation":"A provision for doubtful debts is a credit balance deducted from debtors. Drawings, discount allowed (an expense) and prepaid insurance (an asset) are debit balances.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-18","question":"Under Ind AS 16 and Ind AS 8, how is a change from the written-down-value method to the straight-line method of depreciation treated?","options":["As a change in accounting policy, applied retrospectively","As a prior-period error, restated in comparatives","As a change in accounting estimate, applied prospectively","It is not allowed once a method has been chosen"],"answer":2,"explanation":"The depreciation method reflects the expected pattern of using up the asset's benefits, so a change in method is a change in accounting estimate and is applied prospectively from the date of change.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-19","question":"A machine bought on 1 April 2021 for ₹10,00,000 is depreciated straight-line over 10 years with nil residual value. On 1 April 2024 the remaining life is revised to 5 years and the residual value to ₹50,000. What is the depreciation for 2024-25?","options":["₹1,30,000","₹1,00,000","₹1,40,000","₹1,90,000"],"answer":0,"explanation":"Book value on 1 April 2024 = 10,00,000 − 3 × 1,00,000 = ₹7,00,000. Revised charge = (7,00,000 − 50,000) ÷ 5 = ₹1,30,000, applied prospectively. ₹1,40,000 ignores the residual value; ₹1,90,000 restarts from cost.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-20","question":"Goods costing ₹10,000 are given away as charity. What is the journal entry?","options":["Charity A/c Dr To Sales A/c","Charity A/c Dr To Purchases A/c","Purchases A/c Dr To Charity A/c","Charity A/c Dr To Cash A/c"],"answer":1,"explanation":"The goods leave at cost and were never sold, so Purchases is credited (reduced) and Charity, an expense, is debited.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-21","question":"₹19,600 is paid to a creditor in full settlement of ₹20,000. What is the correct entry?","options":["Creditor Dr ₹19,600 To Cash ₹19,600","Creditor Dr ₹20,000 To Cash ₹19,600, To Discount Allowed ₹400","Creditor Dr ₹20,000 To Cash ₹19,600, To Discount Received ₹400","Creditor Dr ₹19,600, Discount Received Dr ₹400 To Cash ₹20,000"],"answer":2,"explanation":"The whole ₹20,000 liability is cleared, ₹19,600 in cash; the ₹400 saved is a gain, credited to Discount Received.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-22","question":"Old furniture with a book value of ₹8,000 was sold for ₹6,000 and the proceeds were credited to the Sales account. By how much is the net profit overstated?","options":["₹6,000","₹2,000","₹8,000","It is understated by ₹2,000"],"answer":2,"explanation":"Reported profit includes ₹6,000 as sales. Correctly, the sale should show a loss of ₹2,000 (6,000 − 8,000). The gap is 6,000 − (−2,000) = ₹8,000 overstated; the furniture also stays in the books at ₹8,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-23","question":"A proprietor keeps incomplete records. Capital was ₹4,00,000 at the start of the year and ₹5,10,000 at the end. He withdrew ₹9,000 a month in cash and took goods worth ₹12,000 for personal use; he also introduced fresh capital of ₹50,000. What is the profit for the year?","options":["₹1,68,000","₹2,80,000","₹1,80,000","₹60,000"],"answer":2,"explanation":"Profit = closing capital − opening capital + drawings − fresh capital = 5,10,000 − 4,00,000 + (1,08,000 + 12,000) − 50,000 = ₹1,80,000. Forgetting the goods gives ₹1,68,000; adding the fresh capital gives ₹2,80,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-24","question":"An asset costing ₹2,00,000 with a residual value of ₹20,000 is depreciated straight-line at ₹36,000 a year. What useful life has been assumed?","options":["5.56 years","4.5 years","5 years","6 years"],"answer":2,"explanation":"Life = (cost − residual) ÷ annual charge = 1,80,000 ÷ 36,000 = 5 years. 5.56 years wrongly divides the full cost.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-25","question":"A machine costing ₹12,00,000 (residual value ₹2,00,000) is expected to run 50,000 hours. It runs 8,000 hours in year 1 and 12,000 hours in year 2. What is the year-2 charge under the units-of-production method?","options":["₹2,88,000","₹2,40,000","₹1,60,000","₹2,00,000"],"answer":1,"explanation":"Rate = (12,00,000 − 2,00,000) ÷ 50,000 = ₹20 per hour. Year 2 = 12,000 × 20 = ₹2,40,000. ₹2,88,000 ignores the residual value.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-26","question":"A firm charges 10% depreciation on the written-down value, crediting it directly to the asset account. It bought a machine for ₹5,00,000 on 1 April 2022 and another for ₹2,00,000 on 1 October 2022. What is the machinery account balance on 31 March 2024?","options":["₹5,67,000","₹5,70,000","₹5,60,000","₹5,76,000"],"answer":3,"explanation":"Machine 1: 5,00,000 × 0.9 × 0.9 = ₹4,05,000. Machine 2: half-year in 2022-23, 2,00,000 − 10,000 = 1,90,000; then 1,90,000 − 19,000 = ₹1,71,000. Total ₹5,76,000. Charging machine 2 a full first year gives ₹5,67,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-27","question":"Assertion (A): A company cannot capitalise a large advertising campaign even if it expects the campaign to bring sales for three years. Reason (R): Ind AS 38 requires spending on advertising and promotional activities to be recognised as an expense when incurred.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Ind AS 38 specifically lists advertising and promotional spending as an expense when incurred, because it does not create an identifiable intangible asset the entity controls. That is exactly why A holds.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-28","question":"Which of these costs is included in the cost of inventory under Ind AS 2?","options":["Abnormal wastage of materials","Selling and distribution costs","Freight inward on raw materials","Storage of finished goods awaiting sale"],"answer":2,"explanation":"Costs of purchase, including freight inward, are part of inventory cost. Abnormal wastage, selling costs and storage costs (unless storage is necessary in the production process) are expensed.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-29","question":"Assertion (A): A revaluation decrease on an asset that carries an earlier revaluation surplus is first set off against that surplus. Reason (R): Under Ind AS 16, every revaluation decrease is recognised in profit or loss.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":3,"explanation":"A decrease is first debited to OCI to the extent of any surplus held for that same asset; only the excess goes to profit or loss. So A is true and R, which says 'every decrease goes to P&L', is false.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-30","question":"Which of these is a nominal account?","options":["Capital","Commission received","Debtors","Machinery"],"answer":1,"explanation":"Nominal accounts record incomes, expenses, gains and losses; commission received is an income. Capital and debtors are personal accounts and machinery is a real account.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-31","question":"The cash book shows a debit balance of ₹25,000. Cheques of ₹4,000 issued to suppliers have not yet been presented. If there is no other difference, what does the pass book show?","options":["₹29,000","₹21,000","₹25,000","₹33,000"],"answer":0,"explanation":"The cash book has already deducted the ₹4,000, but the bank has not paid it yet, so the bank balance is higher: 25,000 + 4,000 = ₹29,000.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-32","question":"The cash book shows a debit balance of ₹48,000. Cheques deposited ₹12,000 are not yet cleared; cheques issued ₹7,500 are not yet presented; bank charges ₹300 and interest credited ₹1,200 are not in the cash book; a customer paid ₹5,000 directly into the bank. What is the pass-book balance?","options":["₹58,400","₹44,400","₹46,600","₹49,400"],"answer":3,"explanation":"48,000 − 12,000 (deposits not cleared) + 7,500 (cheques not presented) − 300 + 1,200 + 5,000 = ₹49,400. Swapping the treatment of the two cheque items gives ₹58,400; missing the direct deposit gives ₹44,400.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-33","question":"The pass book shows an overdraft of ₹30,000. Cheques issued ₹8,000 are not yet presented, cheques deposited ₹5,000 are not yet credited, and bank charges of ₹600 appear only in the pass book. What is the cash-book balance?","options":["Overdraft ₹32,400","Overdraft ₹27,600","Overdraft ₹23,400","Overdraft ₹36,600"],"answer":0,"explanation":"Work from −30,000: the cash book has already paid the ₹8,000 (−8,000), already received the ₹5,000 (+5,000) and not yet deducted the ₹600 charges (+600): −30,000 − 8,000 + 5,000 + 600 = −32,400, an overdraft of ₹32,400.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-34","question":"The trial balance shows debtors ₹2,10,000, bad debts ₹4,000 and a provision for doubtful debts of ₹8,000. Adjustments: write off further bad debts of ₹10,000 and keep the provision at 5% of debtors. What is the total charge to the profit and loss account for bad and doubtful debts?","options":["₹6,000","₹12,500","₹24,000","₹16,000"],"answer":3,"explanation":"Bad debts = 4,000 + 10,000 = 14,000. New provision = 5% × (2,10,000 − 10,000) = 10,000; increase over the old ₹8,000 = 2,000. Charge = 14,000 + 2,000 = ₹16,000. ₹12,500 takes 5% on debtors before the write-off.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-35","question":"Debtors stand at ₹2,10,000. Further bad debts of ₹10,000 are written off, a 5% provision for doubtful debts is made and then a 2% provision for discount on debtors. At what net amount are debtors shown in the balance sheet?","options":["₹1,86,200","₹1,86,000","₹1,90,000","₹1,95,310"],"answer":0,"explanation":"2,10,000 − 10,000 = 2,00,000; doubtful-debt provision 10,000 → 1,90,000; discount provision 2% of the good debts 1,90,000 = 3,800 → ₹1,86,200. Taking 2% of ₹2,00,000 gives ₹1,86,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-36","question":"Wages paid during the year are ₹84,000, which includes ₹6,000 outstanding from the previous year. Wages of ₹9,000 are outstanding at the year end. What amount is charged for wages this year?","options":["₹93,000","₹81,000","₹99,000","₹87,000"],"answer":3,"explanation":"84,000 − 6,000 (belongs to last year) + 9,000 (this year's unpaid) = ₹87,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-37","question":"An annual insurance premium of ₹36,000 is paid on 1 August 2023. The accounts close on 31 March 2024. What is the prepaid insurance in the balance sheet?","options":["₹12,000","₹24,000","₹9,000","₹15,000"],"answer":0,"explanation":"The premium covers August 2023 to July 2024; April–July 2024 (4 months) lies in the next year: 36,000 × 4/12 = ₹12,000. ₹24,000 is this year's expense.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-38","question":"Net profit before the manager's commission is ₹2,20,000. The manager gets 10% of the net profit after charging his commission. What is his commission?","options":["₹20,000","₹22,000","₹24,200","₹18,000"],"answer":0,"explanation":"If commission = C, C = 10% × (2,20,000 − C), so 1.1C = 22,000 and C = ₹20,000 (= 2,20,000 × 10/110). ₹22,000 is 10% before commission.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-39","question":"Goods costing ₹50,000 are destroyed by fire and the insurer admits a claim of ₹35,000, still unpaid at the year end. Which treatment is correct?","options":["Debit P&L ₹50,000 and credit Trading ₹50,000; record the claim only when cash is received","Debit Trading ₹15,000 and make no other entry","Reduce closing stock by ₹50,000 and make no other entry","Credit Trading ₹50,000; debit Insurance Claim Receivable ₹35,000 and P&L ₹15,000"],"answer":3,"explanation":"The goods are taken out of Trading at cost (credit ₹50,000). The admitted claim is an asset (receivable ₹35,000) even though unpaid, and only the uncovered ₹15,000 is a loss in the P&L. Waiting for cash breaks the accrual concept.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-40","question":"Opening stock ₹60,000, purchases ₹3,40,000, purchase returns ₹10,000, carriage inward ₹15,000, wages ₹25,000, sales ₹5,00,000, sales returns ₹20,000, closing stock ₹80,000. What is the gross profit?","options":["₹1,50,000","₹1,70,000","₹1,20,000","₹1,30,000"],"answer":3,"explanation":"Net sales 4,80,000. Cost of goods sold = 60,000 + 3,30,000 + 15,000 + 25,000 − 80,000 = 3,50,000. Gross profit = ₹1,30,000. Forgetting sales returns gives ₹1,50,000; forgetting purchase returns gives ₹1,20,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-41","question":"Closing stock of ₹80,000 appears inside the trial balance (purchases have already been adjusted for it). Where is it shown in the final accounts?","options":["Only in the balance sheet, as a current asset","On the credit side of the Trading account and in the balance sheet","Only on the credit side of the Trading account","On the debit side of the Trading account"],"answer":0,"explanation":"When closing stock is inside the trial balance, it has already been deducted from purchases (adjusted purchases). Crediting Trading again would count it twice, so it goes only to the balance sheet.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-42","question":"Goods worth ₹12,000 received on the last day of the year are included in closing stock, but the supplier's invoice has not been recorded. What is the effect?","options":["Profit overstated by ₹12,000 and creditors understated by ₹12,000","No effect on profit, because the goods are in stock","Profit understated by ₹12,000","Profit overstated by ₹24,000"],"answer":0,"explanation":"The goods raise closing stock (and profit) by ₹12,000, but the matching purchase is missing. Recording the purchase raises cost of goods sold by ₹12,000 and creates the creditor, so profit was overstated by ₹12,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-43","question":"A trader prices goods at cost plus 20%. Goods sent on approval at ₹24,000 (selling price) were recorded as sales, but the customer has not yet approved them at the year end. What adjustment to profit is needed?","options":["Reduce profit by ₹24,000","Reduce profit by ₹4,800","Increase profit by ₹20,000","Reduce profit by ₹4,000"],"answer":3,"explanation":"Cancel the sale (−24,000) and bring the goods back into closing stock at cost, 24,000 ÷ 1.2 = 20,000 (+20,000). Net reduction = ₹4,000, the profit loaded in the price. 20% of 24,000 (₹4,800) confuses mark-up on cost with margin on sales.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-44","question":"The cash book shows an overdraft of ₹15,000. A cheque of ₹2,000 issued to a supplier was entered twice on the payments side, cheques deposited ₹6,000 are not yet credited, and interest on overdraft ₹900 has been charged only by the bank. What is the pass-book balance?","options":["Overdraft ₹23,900","Overdraft ₹21,900","Overdraft ₹8,100","Overdraft ₹19,900"],"answer":3,"explanation":"Start at −15,000. The duplicate entry overstated payments, so the true position is better: +2,000 → −13,000. Deposits not credited: −6,000 → −19,000. Interest: −900 → −19,900, an overdraft of ₹19,900.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-45","question":"₹1,00,000 is invested in 12% debentures. Interest for only 9 months has been received during the year. What accrued interest is shown at the year end?","options":["₹3,000","₹9,000","₹12,000","₹4,000"],"answer":0,"explanation":"Annual interest = ₹12,000; 9 months (₹9,000) received, so 3 months = ₹3,000 has accrued.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-46","question":"Which item appears on the credit side of the Trading account?","options":["Closing stock","Carriage inward","Wages","Opening stock"],"answer":0,"explanation":"Closing stock (when it is outside the trial balance) is credited to Trading; carriage inward, wages and opening stock are debits.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-47","question":"Opening debtors ₹40,000, closing debtors ₹55,000, cash received from debtors ₹2,60,000, discount allowed ₹5,000, bad debts ₹3,000 and sales returns ₹7,000. What were the credit sales?","options":["₹2,75,000","₹2,80,000","₹2,60,000","₹2,90,000"],"answer":3,"explanation":"Debtors account: credit sales = closing 55,000 + cash 2,60,000 + discount 5,000 + bad debts 3,000 + returns 7,000 − opening 40,000 = ₹2,90,000. Ignoring the three non-cash credits gives ₹2,75,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-48","question":"Opening creditors ₹30,000, closing creditors ₹45,000, cash paid to creditors ₹1,80,000, discount received ₹4,000, purchase returns ₹6,000 and cash purchases ₹20,000. What are the total purchases before deducting returns?","options":["₹2,25,000","₹2,05,000","₹2,19,000","₹2,15,000"],"answer":0,"explanation":"Credit purchases = 45,000 + 1,80,000 + 4,000 + 6,000 − 30,000 = 2,05,000. Total purchases = 2,05,000 + 20,000 cash = ₹2,25,000. ₹2,19,000 is net of returns; ₹2,05,000 forgets the cash purchases.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-49","question":"Sales are ₹6,00,000, opening stock ₹70,000 and purchases ₹4,80,000. Gross profit is 25% of cost. What is the closing stock?","options":["₹1,00,000","₹1,20,000","₹50,000","₹70,000"],"answer":3,"explanation":"Profit is 25% of cost, so cost of goods sold = 6,00,000 ÷ 1.25 = 4,80,000. Closing stock = 70,000 + 4,80,000 − 4,80,000 = ₹70,000. Treating 25% as a margin on sales gives ₹1,00,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-50","question":"A fire destroys stock. Stock on 1 April was ₹80,000; purchases to the date of the fire ₹3,20,000; sales ₹4,50,000; gross profit is 20% of sales. Goods worth ₹10,000 were saved. The stock was insured for ₹24,000 under a policy with an average clause. What is the claim?","options":["₹18,000","₹24,000","₹30,000","₹14,400"],"answer":0,"explanation":"Stock at fire = 80,000 + 3,20,000 − (4,50,000 × 80%) = ₹40,000. Loss = 40,000 − 10,000 = ₹30,000. Under-insured, so claim = 30,000 × 24,000/40,000 = ₹18,000. Using 20% on cost gives ₹14,400.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-51","question":"Which year-end transaction affects only the balance sheet, not the profit for the year?","options":["Salaries outstanding","Depreciation on machinery","Commission accrued but not received","Machinery bought for cash on the last day of the year"],"answer":3,"explanation":"Buying an asset for cash swaps one asset for another; no expense arises in this year. The other three are adjustments that change the P&L as well.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-52","question":"The trial balance shows Rent ₹22,000 and, separately, Outstanding Rent ₹2,000 (credit). Among the adjustments it is also noted that rent of ₹2,000 is outstanding. What amount of rent goes to the profit and loss account?","options":["₹22,000","₹24,000","₹20,000","₹26,000"],"answer":0,"explanation":"An item that already appears in the trial balance has been recorded; the note simply describes it. The ₹22,000 already includes the outstanding ₹2,000, so adding it again (₹24,000) double-counts.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-53","question":"Profit before adjustments is ₹3,00,000. Adjustments: closing stock ₹50,000 not yet recorded; salary outstanding ₹8,000; rent prepaid ₹3,000; depreciation 10% on machinery of ₹2,00,000; commission accrued ₹2,500; further bad debts ₹1,500. What is the adjusted profit?","options":["₹3,36,000","₹2,76,000","₹3,46,000","₹3,26,000"],"answer":3,"explanation":"3,00,000 + 50,000 − 8,000 + 3,000 − 20,000 + 2,500 − 1,500 = ₹3,26,000. Reversing outstanding and prepaid gives ₹3,36,000; forgetting depreciation gives ₹3,46,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-54","question":"With the cash book and pass book both showing favourable balances, which item makes the pass-book balance higher than the cash-book balance?","options":["Cheques issued but not yet presented for payment","Cheques deposited but not yet cleared","Bank charges debited only in the pass book","A customer's cheque dishonoured, not yet recorded in the cash book"],"answer":0,"explanation":"The cash book has deducted the cheques issued, but the bank has not paid them yet, so the bank's figure is higher. The other three make the pass book lower.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-55","question":"Assertion (A): An error made by the bank in the pass book needs no entry in the cash book. Reason (R): The cash book is corrected only for items the business itself has not recorded or has recorded wrongly.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A bank error is corrected by the bank; it appears only as a reconciling item in the BRS. The cash book is amended only for the business's own omissions and errors, which is why no entry is needed.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-56","question":"The cash book shows a debit balance of ₹36,000 and the pass book ₹43,250. Cheques issued ₹15,000 are not presented; cheques deposited ₹9,000 are not cleared; bank charges ₹250 and a dividend of ₹3,000 collected by the bank are not in the cash book; a customer's cheque of ₹1,500, deposited and later dishonoured, has not been recorded as dishonoured in the cash book. What is the corrected cash-book balance?","options":["₹43,250","₹38,750","₹40,250","₹37,250"],"answer":3,"explanation":"Correct the cash book only for its own omissions: 36,000 − 250 + 3,000 − 1,500 = ₹37,250. Check: 37,250 − 9,000 + 15,000 = 43,250, the pass-book figure. Treating the dishonour as an addition gives ₹40,250.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-57","question":"A sole trader charges interest on capital at 10% on capital of ₹5,00,000. How many of these statements are true? (1) Net profit falls by ₹50,000. (2) The closing capital is unchanged by the entry. (3) Interest on drawings, if charged, would increase net profit. (4) The entry causes a cash outflow of ₹50,000.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) True: the interest is debited to P&L. (2) True: the same ₹50,000 is credited to capital, offsetting the lower profit. (3) True: interest on drawings is credited to P&L. (4) False: nothing is paid out; it is a book entry. Three are true.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-58","question":"Goods worth ₹5,000 are lost in transit and the carrier accepts a claim of ₹3,000, not yet received. How much is debited to the profit and loss account?","options":["₹5,000","₹3,000","Nil","₹2,000"],"answer":3,"explanation":"The goods are removed from Trading (₹5,000); ₹3,000 is a receivable from the carrier and only the uncovered ₹2,000 is a loss.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-59","question":"Carriage outward (on goods sold) is debited to:","options":["Trading account","Profit and loss account","Balance sheet","Capital account"],"answer":1,"explanation":"Carriage outward is a selling and distribution expense, so it goes to the P&L. Carriage inward is part of the cost of goods and goes to Trading.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-60","question":"Opening stock ₹1,20,000, purchases ₹6,00,000 and sales ₹7,50,000. Goods are sold at cost plus 25%. The owner took goods costing ₹20,000 for personal use, which were not recorded. What should the closing stock be?","options":["₹1,00,000","₹1,20,000","₹1,37,500","₹80,000"],"answer":0,"explanation":"Cost of goods sold = 7,50,000 ÷ 1.25 = 6,00,000. Closing stock = 1,20,000 + 6,00,000 − 20,000 (drawings) − 6,00,000 = ₹1,00,000. Ignoring the goods taken gives ₹1,20,000; using 25% of sales gives ₹1,37,500.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-61","question":"A and B share profits 3 : 2. C is admitted and the new ratio of A, B and C is 5 : 3 : 2. What is the sacrificing ratio of A and B?","options":["3 : 2","1 : 1","5 : 3","2 : 1"],"answer":1,"explanation":"A: 3/5 − 5/10 = 1/10. B: 2/5 − 3/10 = 1/10. Sacrificing ratio 1 : 1, not the old ratio.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-62","question":"A and B share profits 5 : 3. C is admitted for a 1/4 share, which he takes equally from A and B. What is the new ratio of A, B and C?","options":["15 : 9 : 8","5 : 3 : 2","2 : 1 : 1","4 : 3 : 1"],"answer":2,"explanation":"Each gives 1/8. A = 5/8 − 1/8 = 4/8; B = 3/8 − 1/8 = 2/8; C = 2/8 → 2 : 1 : 1. 15 : 9 : 8 is what you get if C takes his share from A and B in their old ratio.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-63","question":"A firm's capital employed is ₹10,00,000 and the normal rate of return is 12%. Its average profit is ₹1,80,000. What is goodwill at three years' purchase of super profit?","options":["₹5,40,000","₹1,80,000","₹5,00,000","₹3,60,000"],"answer":1,"explanation":"Normal profit = 12% × 10,00,000 = 1,20,000. Super profit = 1,80,000 − 1,20,000 = 60,000. Goodwill = 60,000 × 3 = ₹1,80,000. ₹5,40,000 multiplies the whole average profit; ₹5,00,000 capitalises the super profit instead.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-64","question":"A firm earns an average profit of ₹1,50,000; the normal rate of return is 10%. Its assets are ₹18,00,000 and outside liabilities ₹5,00,000. What is goodwill by capitalising the average profit?","options":["₹15,00,000","Nil","₹2,00,000","₹1,50,000"],"answer":2,"explanation":"Capitalised value = 1,50,000 ÷ 10% = 15,00,000. Net assets = 18,00,000 − 5,00,000 = 13,00,000. Goodwill = 15,00,000 − 13,00,000 = ₹2,00,000. Comparing with total assets (ignoring liabilities) would wrongly show no goodwill.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-65","question":"A and B have capitals of ₹3,00,000 and ₹2,00,000 after all adjustments. C is admitted for a 1/4 share and brings ₹2,00,000 as capital, but nothing for goodwill. What is the hidden goodwill of the firm?","options":["₹3,00,000","₹1,00,000","₹25,000","₹75,000"],"answer":1,"explanation":"C's ₹2,00,000 for 1/4 implies total capital of ₹8,00,000. Actual capital including C = 3,00,000 + 2,00,000 + 2,00,000 = ₹7,00,000. Hidden goodwill = ₹1,00,000 (C's share of it ₹25,000). ₹3,00,000 forgets to include C's own capital.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-66","question":"A and B share profits 3 : 2. C is admitted for a 1/5 share and pays ₹50,000 as premium for goodwill. The new ratio is A 2 : B 2 : C 1. How is the premium shared?","options":["A ₹30,000 and B ₹20,000","A ₹50,000 and B nil","A ₹25,000 and B ₹25,000","A ₹40,000 and B ₹10,000"],"answer":1,"explanation":"Premium goes to the partners who sacrifice, in the sacrificing ratio. A: 3/5 − 2/5 = 1/5; B: 2/5 − 2/5 = 0. Only A sacrifices, so A gets all ₹50,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-67","question":"On admitting a partner, the firm revalues: building (book value ₹5,00,000) up by 10%; stock down by ₹15,000; a 5% provision is created on debtors of ₹1,00,000; an unrecorded liability of ₹8,000 is brought in; creditors of ₹2,000 are found not payable. What is the profit on revaluation?","options":["₹20,000","₹40,000","₹24,000","₹29,000"],"answer":2,"explanation":"+50,000 (building) − 15,000 (stock) − 5,000 (provision) − 8,000 (new liability) + 2,000 (creditors written back) = ₹24,000, shared by the old partners in the old ratio. Treating the creditor write-back as a loss gives ₹20,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-68","question":"The partnership deed is silent on all financial matters. Under the Indian Partnership Act, 1932, which of these is allowed?","options":["Interest on capital at 6% a year","Interest at 6% a year on a loan given by a partner to the firm","A salary to the working partner","Sharing profits in the ratio of capitals"],"answer":1,"explanation":"Without agreement, profits are shared equally, there is no interest on capital and no salary, but a partner's loan to the firm carries interest at 6% a year.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-69","question":"Profit for the year is ₹1,20,000. A's capital is ₹4,00,000 and B's ₹2,00,000. Interest on capital is 10%, B gets a salary of ₹2,000 a month, and the remaining profit is shared 3 : 2. What is B's total share?","options":["₹62,000","₹58,400","₹45,200","₹61,600"],"answer":1,"explanation":"Interest: A 40,000, B 20,000. B's salary 24,000. Divisible = 1,20,000 − 60,000 − 24,000 = 36,000; B's 2/5 = 14,400. B total = 20,000 + 24,000 + 14,400 = ₹58,400. ₹61,600 is A's total; ₹62,000 splits the balance equally.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-70","question":"A, B and C share profits 2 : 2 : 1. C is guaranteed a minimum profit of ₹30,000, any shortfall to be borne by A and B in the ratio 3 : 2. The firm's profit is ₹1,00,000. What is A's final share?","options":["₹40,000","₹35,000","₹34,000","₹30,000"],"answer":2,"explanation":"C's normal share = 20,000; shortfall 10,000. A bears 3/5 = 6,000, so A gets 40,000 − 6,000 = ₹34,000 (B gets 36,000). ₹35,000 shares the shortfall equally.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-71","question":"A partner withdraws ₹5,000 at the beginning of every month for 12 months. Interest on drawings is 12% a year. What is the interest on drawings?","options":["₹3,600","₹3,900","₹3,300","₹7,200"],"answer":1,"explanation":"Total ₹60,000; drawings at the start of each month are outstanding for 6.5 months on average: 60,000 × 12% × 6.5/12 = ₹3,900. End-of-month drawings would give 5.5 months (₹3,300) and mid-month 6 months (₹3,600).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-72","question":"A partner withdraws ₹15,000 at the beginning of each quarter. Interest on drawings is 10% a year. What is the interest on drawings for the year?","options":["₹2,250","₹3,000","₹3,750","₹6,000"],"answer":2,"explanation":"Total ₹60,000. Average period for start-of-quarter drawings = (12 + 9 + 6 + 3) ÷ 4 = 7.5 months: 60,000 × 10% × 7.5/12 = ₹3,750. End-of-quarter drawings would give 4.5 months (₹2,250).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-73","question":"A, B and C share profits 4 : 3 : 2. B retires, and A and C take over his share in the ratio 1 : 2. What is the new ratio of A and C?","options":["2 : 1","5 : 4","1 : 2","4 : 3"],"answer":1,"explanation":"B's 3/9 is split 1 : 2: A gains 1/9 and C 2/9. A = 4/9 + 1/9 = 5/9; C = 2/9 + 2/9 = 4/9 → 5 : 4. 1 : 2 is only the gaining ratio.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-74","question":"A, B and C share profits 3 : 2 : 1. C retires; A and B continue in the ratio 3 : 2. Goodwill is valued at ₹1,80,000 and is not to appear in the books. How much does A's capital account contribute to C's share of goodwill?","options":["₹15,000","₹30,000","₹18,000","₹90,000"],"answer":2,"explanation":"C's share = 1,80,000 × 1/6 = 30,000. Gains: A 3/5 − 3/6 = 3/30, B 2/5 − 2/6 = 2/30, so gaining ratio 3 : 2. A pays 30,000 × 3/5 = ₹18,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-75","question":"A and B share profits equally and decide to share 3 : 2 in future. Goodwill is valued at ₹60,000 and is not to be shown in the books. What entry is passed?","options":["B's capital Dr ₹6,000 To A's capital ₹6,000","A's capital Dr ₹6,000 To B's capital ₹6,000","A's capital Dr ₹36,000 To B's capital ₹36,000","No entry is needed for a change in ratio"],"answer":1,"explanation":"A gains 3/5 − 1/2 = 1/10 and B sacrifices 1/10. The gainer compensates the sacrificer: 60,000 × 1/10 = ₹6,000, debited to A and credited to B.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-76","question":"A, B and C share profits 2 : 2 : 1. C dies on 30 June. His share of profit up to death is based on the average of the last three years' profits: ₹1,80,000, ₹2,10,000 and ₹2,70,000. The year starts on 1 April. What is C's share of profit?","options":["₹13,500","₹11,000","₹44,000","₹22,000"],"answer":1,"explanation":"Average profit = 6,60,000 ÷ 3 = 2,20,000. April to June = 3 months: 2,20,000 × 3/12 × 1/5 = ₹11,000. Using only last year's ₹2,70,000 gives ₹13,500; using six months gives ₹22,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-77","question":"Under the fixed capital method, where are the partners' interest on capital, salary and share of profit credited?","options":["To their capital accounts","To the profit and loss account","To their current accounts","To the revaluation account"],"answer":2,"explanation":"With fixed capitals, the capital accounts carry only the agreed capital (and permanent additions or withdrawals); all routine items such as interest, salary, drawings and profit share go through current accounts.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-78","question":"On dissolution, assets (other than cash) with a book value of ₹5,00,000 realise ₹4,40,000. Creditors of ₹1,20,000 accept ₹1,15,000 in full settlement, and realisation expenses of ₹6,000 are paid by the firm. What is the loss on realisation?","options":["₹66,000","₹55,000","₹61,000","₹60,000"],"answer":2,"explanation":"Loss on assets 60,000 − gain on creditors 5,000 + expenses 6,000 = ₹61,000. Treating the creditors' discount as a loss gives ₹66,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-79","question":"After all adjustments, A's capital is ₹4,50,000 and B's ₹3,00,000. C is admitted for a 1/4 share and must bring capital equal to 1/4 of the total capital of the new firm. How much does C bring?","options":["₹1,87,500","₹2,50,000","₹3,00,000","₹2,00,000"],"answer":1,"explanation":"Old partners' ₹7,50,000 is 3/4 of the new total, so total = 10,00,000 and C brings ₹2,50,000. ₹1,87,500 is 1/4 of the old capital, not of the new total.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-80","question":"A and B share profits 3 : 2 and have capitals of ₹3,00,000 and ₹2,20,000. C is admitted for 1/5 and brings ₹1,20,000. A and B keep their ratio between themselves and agree to adjust their capitals on the basis of C's capital, in the new profit-sharing ratio. What adjustment does A make?","options":["A brings in ₹12,000","A withdraws ₹12,000","A withdraws ₹1,20,000","A brings in ₹48,000"],"answer":1,"explanation":"Total capital implied by C = 1,20,000 × 5 = 6,00,000. New ratio: A 3/5 × 4/5 = 12/25, B 8/25, C 5/25. A's capital should be 6,00,000 × 12/25 = 2,88,000, so A withdraws 3,00,000 − 2,88,000 = ₹12,000 (B, whose capital should be ₹1,92,000, withdraws ₹28,000).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-81","question":"The partnership deed allows interest on capital: A ₹24,000 and B ₹16,000. The firm's profit is only ₹30,000. Interest on capital is treated as an appropriation of profit. How is the profit distributed?","options":["A ₹24,000 and B ₹16,000, and the ₹10,000 shortfall is shared as a loss","A ₹15,000 and B ₹15,000","A ₹18,000 and B ₹12,000","A ₹24,000 and B ₹6,000"],"answer":2,"explanation":"As an appropriation, interest on capital cannot exceed the available profit; the ₹30,000 is shared in the ratio of the interest, 24 : 16 = 3 : 2, giving A ₹18,000 and B ₹12,000. (If interest were a charge, it would be allowed in full and create a loss.)","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-82","question":"When the partnership deed is silent, which of these rules apply under the Indian Partnership Act, 1932? (1) Profits and losses are shared equally (2) No interest on capital (3) Interest at 6% a year on partners' loans (4) No salary or commission to any partner","options":["(1) and (2) only","(1), (2) and (3) only","(1), (2), (3) and (4)","(2) and (4) only"],"answer":2,"explanation":"All four are the default rules of Section 13 when the partners have not agreed otherwise.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-83","question":"Goodwill is to be valued at two years' purchase of the weighted average profit of the last three years, weighted 1, 2 and 3 (latest year highest). Profits were ₹1,00,000, ₹1,20,000 and ₹1,50,000; the latest year's profit includes a non-recurring gain of ₹30,000. What is goodwill?","options":["₹2,63,333","₹2,33,333","₹2,26,667","₹1,16,667"],"answer":1,"explanation":"Normalised latest profit = 1,20,000. Weighted average = (1,00,000 × 1 + 1,20,000 × 2 + 1,20,000 × 3) ÷ 6 = 7,00,000 ÷ 6 = 1,16,667. Goodwill = 2 × 1,16,667 = ₹2,33,333. Keeping the non-recurring gain gives ₹2,63,333.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-84","question":"On admitting a partner, the partners want the assets and liabilities to stay at their old book values even though some have been revalued. What do they use?","options":["A revaluation account, closed to the new ratio","A realisation account","A memorandum revaluation account","A goodwill account"],"answer":2,"explanation":"A memorandum revaluation account records the net gain or loss, credited to the old partners in the old ratio, and then reverses it among all partners in the new ratio, so the book values stay unchanged.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-85","question":"Goodwill of ₹40,000 already stands in the books when a new partner is admitted. What happens to it?","options":["It is carried forward unchanged","It is written off among the old partners in the old ratio","It is written off among all partners in the new ratio","It is credited to the new partner"],"answer":1,"explanation":"Existing goodwill belongs to the old partners and is written off to their capital accounts in the old ratio before the new partner's goodwill is dealt with.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-86","question":"A, B and C share profits 2 : 2 : 1. C retires. The balance sheet shows a general reserve of ₹60,000 and a debit balance of ₹15,000 in the profit and loss account. What net amount is credited to C's capital for these two items?","options":["₹12,000","₹9,000","₹15,000","₹3,000"],"answer":1,"explanation":"Both items are distributed in the old ratio: (60,000 − 15,000) × 1/5 = ₹9,000. ₹12,000 forgets the accumulated loss.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-87","question":"A partner's closing capital is ₹2,30,000 under the fluctuating capital method. During the year his drawings were ₹30,000 and his share of profit ₹40,000. Interest on capital at 10% a year on opening capital has been credited to his capital account. What was the interest on capital?","options":["₹23,000","₹20,000","₹22,000","₹26,000"],"answer":1,"explanation":"Closing = opening × 1.10 + 40,000 − 30,000, so 1.1 × opening = 2,20,000 and opening = 2,00,000. Interest = ₹20,000. ₹22,000 forgets that the interest itself sits inside the closing balance.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-88","question":"The document setting out the terms agreed among partners is called the:","options":["Memorandum of association","Prospectus","Partnership deed (articles of partnership)","Certificate of incorporation"],"answer":2,"explanation":"A partnership deed, also called articles of partnership, records capital, profit ratio, interest, salaries and other terms. The others relate to companies.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-89","question":"A new partner pays the old partners their share of goodwill privately, outside the firm. What entry is made in the firm's books?","options":["Cash Dr To Premium for Goodwill","No entry","Goodwill A/c Dr To Old partners' capitals","New partner's capital Dr To Old partners' capitals"],"answer":1,"explanation":"The payment does not pass through the firm, so the firm's books record nothing for it.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-90","question":"A, B and C share profits 5 : 3 : 2. D is admitted for 1/5, taking 1/10 from A and the rest equally from B and C. What is the new ratio of A, B, C and D?","options":["9 : 5 : 2 : 4","8 : 6 : 2 : 4","8 : 5 : 3 : 4","20 : 12 : 8 : 10"],"answer":2,"explanation":"A gives 1/10; B and C give 1/20 each. A = 5/10 − 1/10 = 8/20; B = 6/20 − 1/20 = 5/20; C = 4/20 − 1/20 = 3/20; D = 4/20 → 8 : 5 : 3 : 4. 20 : 12 : 8 : 10 assumes everyone gives in the old ratio.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-91","question":"Under Schedule III, where is the securities premium shown in a company's balance sheet?","options":["Under 'Other equity' (reserves and surplus)","Under 'Share capital'","Under 'Other current liabilities'","As income in the statement of profit and loss"],"answer":0,"explanation":"Securities premium is part of reserves, shown under Other equity; it is never income and is not share capital.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-92","question":"1,000 equity shares of ₹10 each were issued at par and ₹8 per share has been called up. A shareholder holding all 1,000 shares paid ₹5 per share and failed to pay the ₹3 call, so the shares are forfeited. What is credited to the Share Forfeiture account?","options":["₹5,000","₹8,000","₹3,000","₹10,000"],"answer":0,"explanation":"Share capital is debited with the called-up amount (₹8,000), Calls in arrears credited with the unpaid ₹3,000, and Share Forfeiture credited with the amount actually received, ₹5,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-93","question":"500 shares of ₹10 were issued at ₹12; the ₹2 premium was payable with allotment. Application ₹3, allotment ₹5 (including premium), first call ₹2. A holder of 500 shares paid only the application money and the shares were forfeited after the first call. What is the forfeiture entry?","options":["Share capital Dr ₹4,000; Securities premium Dr ₹1,000; To Share forfeiture ₹1,500 and the unpaid allotment and call accounts","Share capital Dr ₹4,000; To Share forfeiture ₹1,500 and the unpaid allotment and call accounts, with premium left untouched","Share capital Dr ₹5,000; To Share forfeiture ₹1,500 and the unpaid accounts","Share capital Dr ₹4,000; Securities premium Dr ₹1,000; To Share forfeiture ₹2,500 and the unpaid accounts"],"answer":0,"explanation":"Called-up capital = 3 + 3 + 2 = ₹8 × 500 = ₹4,000. The premium was never received, so it is reversed (Dr ₹1,000). Forfeiture = amount received = 500 × 3 = ₹1,500. Credits: unpaid allotment ₹2,500 + unpaid call ₹1,000 + forfeiture ₹1,500 = ₹5,000 = debits.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-94","question":"200 fully called shares of ₹10 each, on which ₹6 per share had been received, were forfeited. 150 of them are reissued as fully paid at ₹8 per share. What amount is transferred to capital reserve?","options":["₹900","₹300","₹1,200","₹600"],"answer":3,"explanation":"Forfeited amount on the 150 reissued shares = 150 × 6 = 900. Discount on reissue = 150 × 2 = 300. Transfer = 900 − 300 = ₹600. The forfeiture on the other 50 shares (₹300) stays in the forfeiture account until they are reissued.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-95","question":"300 shares of ₹10 each, ₹7 called up, were forfeited for non-payment of a ₹3 call (the holder had paid ₹4). They are reissued as ₹10 fully paid. What is the maximum discount per share allowed on reissue?","options":["₹3","₹6","₹7","₹4"],"answer":3,"explanation":"Discount on reissue cannot exceed the amount forfeited on those shares, which is the ₹4 per share received from the original holder.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-96","question":"A company received applications for 30,000 shares and allotted 20,000 pro rata. Application money is ₹3 and allotment money ₹4 per share; excess application money is adjusted against allotment. How much does an applicant for 600 shares pay on allotment?","options":["₹1,000","₹1,600","₹2,400","₹600"],"answer":0,"explanation":"He gets 600 × 20,000/30,000 = 400 shares. Paid on application 600 × 3 = 1,800; needed 400 × 3 = 1,200; excess 600. Allotment due 400 × 4 = 1,600, less 600 = ₹1,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-97","question":"Shares of ₹10 are payable ₹3 on application, ₹4 on allotment and ₹3 on call; allotment is pro rata at 2 shares for every 3 applied, with excess application money adjusted against allotment. An applicant for 600 shares fails to pay allotment and call, and his shares are forfeited. What is credited to Share Forfeiture?","options":["₹1,200","₹600","₹4,000","₹1,800"],"answer":3,"explanation":"He was allotted 400 shares and paid 600 × 3 = ₹1,800 on application. ₹1,200 was applied to application money and ₹600 to allotment, so the whole ₹1,800 has been received on his 400 shares and is forfeited.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-98","question":"1,000 debentures of ₹100 are issued at ₹95 and are redeemable at ₹105. What is the loss on issue of debentures?","options":["₹10,000","₹5,000","₹15,000","Nil"],"answer":0,"explanation":"Discount ₹5 + premium payable on redemption ₹5 = ₹10 per debenture; × 1,000 = ₹10,000, written off over the life of the debentures.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-99","question":"Under Table F of the Companies Act, 2013 (where the articles adopt it), what interest applies to calls in arrears and calls in advance?","options":["Up to 10% a year on calls in arrears; up to 12% a year on calls in advance","12% on calls in arrears; 10% on calls in advance","10% on both","No interest is allowed on either"],"answer":0,"explanation":"Table F lets directors charge interest on unpaid calls at up to 10% a year, and pay interest on calls received in advance at up to 12% a year, unless the company decides otherwise.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-100","question":"Bonus shares cannot be issued out of which of these?","options":["Free reserves","Securities premium","Capital redemption reserve","Revaluation reserve"],"answer":3,"explanation":"Section 63 permits bonus issues from free reserves, securities premium and capital redemption reserve, but not from reserves created by revaluing assets.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-101","question":"Which sequence of share capital is always correct?","options":["Paid-up ≥ called-up ≥ issued","Subscribed ≥ issued ≥ authorised","Called-up ≥ subscribed ≥ paid-up","Authorised ≥ issued ≥ subscribed ≥ called-up ≥ paid-up"],"answer":3,"explanation":"A company cannot issue more than it is authorised to, cannot have more subscribed than issued, cannot call more than subscribed and cannot receive more than called (calls in advance are shown separately).","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-102","question":"Net profit is ₹2,00,000. Depreciation ₹40,000; profit on sale of machinery ₹10,000; increase in debtors ₹25,000; decrease in stock ₹15,000; increase in creditors ₹12,000; decrease in outstanding expenses ₹3,000. What is the cash from operating activities?","options":["₹2,49,000","₹2,31,000","₹2,09,000","₹2,29,000"],"answer":3,"explanation":"2,00,000 + 40,000 − 10,000 − 25,000 + 15,000 + 12,000 − 3,000 = ₹2,29,000. Reversing every working-capital sign gives ₹2,31,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-103","question":"The provision for tax was ₹60,000 at the start of the year and ₹80,000 at the end; the tax charged to the profit and loss account was ₹95,000. How much tax was paid during the year?","options":["₹75,000","₹95,000","₹1,15,000","₹20,000"],"answer":0,"explanation":"Tax paid = opening provision + charge − closing provision = 60,000 + 95,000 − 80,000 = ₹75,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-104","question":"Machinery (net of depreciation) was ₹5,00,000 at the start and ₹6,20,000 at the end of the year. Depreciation for the year was ₹70,000, and a machine with a book value of ₹40,000 was sold for ₹35,000. How much machinery was bought?","options":["₹1,20,000","₹1,90,000","₹2,25,000","₹2,30,000"],"answer":3,"explanation":"Closing = opening + purchases − depreciation − book value sold: purchases = 6,20,000 + 70,000 + 40,000 − 5,00,000 = ₹2,30,000. Using the sale price instead of book value gives ₹2,25,000; forgetting the sale gives ₹1,90,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-105","question":"In a manufacturing company's cash-flow statement, how is interest received on investments classified?","options":["Investing activity","Operating activity","Financing activity","It is not shown"],"answer":0,"explanation":"For a non-financial enterprise, interest and dividends received are returns on investments and are shown under investing activities; for a bank or finance company they are operating.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-106","question":"Which of these is excluded from the cash-flow statement and disclosed only by way of a note?","options":["Purchase of machinery for cash","Redemption of debentures in cash","Payment of dividend","Conversion of debentures into equity shares"],"answer":3,"explanation":"Converting debentures into shares involves no cash, so it is a non-cash financing transaction disclosed separately; the other three are cash flows.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-107","question":"Which of these qualifies as a cash equivalent?","options":["A treasury bill with an original maturity of three months","Equity shares of a listed company held for trading","A fixed deposit with an original maturity of one year","An investment in a subsidiary"],"answer":0,"explanation":"Cash equivalents are short-term, highly liquid investments with insignificant risk of change in value, normally with a maturity of three months or less from acquisition. Equity shares can change in value significantly.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-108","question":"During the year a company issued equity shares of ₹5,00,000 at a 10% premium, redeemed debentures of ₹2,00,000 at a 5% premium, paid debenture interest of ₹30,000 and dividends of ₹80,000, and raised a long-term loan of ₹1,00,000. What is the net cash from financing activities?","options":["₹3,30,000","₹3,40,000","₹2,80,000","₹4,40,000"],"answer":0,"explanation":"+5,50,000 (issue with premium) − 2,10,000 (redemption with premium) − 30,000 − 80,000 + 1,00,000 = ₹3,30,000. Redeeming at par gives ₹3,40,000; ignoring the issue premium gives ₹2,80,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-109","question":"Profit before tax is ₹3,00,000 after crediting dividend received ₹20,000 and profit on sale of investments ₹15,000, and after charging depreciation ₹50,000, goodwill amortisation ₹10,000 and debenture interest ₹25,000. Inventory rose by ₹30,000, trade payables fell by ₹8,000 and prepaid expenses fell by ₹2,000. Tax paid was ₹70,000. What is the cash from operating activities?","options":["₹2,19,000","₹2,79,000","₹3,16,000","₹2,44,000"],"answer":3,"explanation":"Operating profit before working-capital changes = 3,00,000 − 20,000 − 15,000 + 50,000 + 10,000 + 25,000 = 3,50,000. Working capital: −30,000 − 8,000 + 2,000 → 3,14,000. Less tax 70,000 = ₹2,44,000. Leaving interest in operating gives ₹2,19,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-110","question":"Which of these increases cash from operating activities under the indirect method?","options":["Increase in inventory","Decrease in trade payables","Profit on sale of a fixed asset","Decrease in trade receivables"],"answer":3,"explanation":"Collecting receivables releases cash, so a fall in receivables is added. More inventory or lower payables absorb cash, and a profit on sale is deducted because the cash is shown under investing.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-111","question":"How is dividend paid by a manufacturing company classified in its cash-flow statement under Indian standards?","options":["Operating activity","Financing activity","Investing activity","It is not shown, being an appropriation of profit"],"answer":1,"explanation":"Dividends paid are a cost of obtaining financial resources, so they are financing outflows.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-112","question":"How many of these statements about a manufacturing company's cash-flow statement are true? (1) A bonus issue of shares does not appear in it. (2) Loss on sale of machinery is added back in operating activities. (3) Proceeds from the sale of machinery appear under investing activities. (4) Interest paid is an operating outflow.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) True: no cash moves. (2) True: the loss is non-cash and the proceeds are investing. (3) True. (4) False for a non-financial company: interest paid is financing (it is operating only for financial enterprises). Three are true.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-113","question":"For which purpose can a company NOT use its securities premium?","options":["Paying a cash dividend","Issuing fully paid bonus shares","Writing off preliminary expenses","Buying back its own shares"],"answer":0,"explanation":"Section 52 lists the permitted uses: fully paid bonus shares, writing off preliminary expenses, issue expenses or discount, premium on redemption, and buy-back. It cannot be distributed as dividend.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-114","question":"A company buys a building for ₹6,00,000 and pays the vendor by issuing equity shares of ₹10 each at a 20% premium. How many shares are issued?","options":["50,000","60,000","72,000","48,000"],"answer":0,"explanation":"Issue price = 10 + 2 = ₹12. Shares = 6,00,000 ÷ 12 = 50,000. 60,000 divides by face value and ignores the premium.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-115","question":"A company issues its own debentures of ₹5,00,000 to a bank as collateral security for a loan of ₹4,00,000. What is the correct treatment?","options":["Record a liability of ₹9,00,000 (loan plus debentures)","Credit debentures ₹5,00,000 and debit cash ₹5,00,000","Treat the debentures as income until the loan is repaid","No new liability: either just a note under the loan, or a debentures account offset by a debenture suspense account"],"answer":3,"explanation":"Collateral debentures become a liability only if the company defaults on the loan. They are shown by a note, or recorded and immediately offset by a debenture suspense account, so the only real liability is the ₹4,00,000 loan.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-116","question":"Preference shares carry a preferential right as to:","options":["Voting on all resolutions","Appointment of directors","Bonus shares","Dividend and return of capital on winding up"],"answer":3,"explanation":"Preference shareholders get a fixed dividend before equity shareholders and are repaid capital before them on winding up; their voting rights are limited.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-117","question":"A shareholder holding 100 shares of ₹10 (fully called) paid only ₹2 on application and ₹3 on allotment; his shares were forfeited. 60 of them are reissued as fully paid at ₹9 each. What is transferred to capital reserve?","options":["₹300","₹200","₹60","₹240"],"answer":3,"explanation":"Forfeited per share = ₹5; on 60 shares = 300. Discount on reissue = 60 × 1 = 60. Capital reserve = 300 − 60 = ₹240. The ₹200 on the 40 unissued shares stays in the forfeiture account.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-118","question":"How is interest received on loans given classified in the cash-flow statement of a finance company?","options":["Investing activity","Financing activity","It is not shown","Operating activity"],"answer":3,"explanation":"Lending is the main revenue-producing activity of a finance company, so interest received is an operating cash flow.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-119","question":"How is a bank overdraft that is repayable on demand and forms an integral part of a company's cash management treated under Ind AS 7?","options":["As a component of cash and cash equivalents","As a financing inflow when drawn","As an investing activity","As an operating outflow"],"answer":0,"explanation":"Ind AS 7 includes such overdrafts as a (negative) component of cash and cash equivalents, since the balance often swings between positive and overdrawn.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-120","question":"A company's cash from operations (after tax) is ₹4,20,000. It spent ₹2,50,000 on new plant and received ₹30,000 from selling old plant. Taking free cash flow as operating cash flow less net capital expenditure, what is the free cash flow?","options":["₹1,70,000","₹2,00,000","₹4,50,000","₹2,30,000"],"answer":1,"explanation":"Net capex = 2,50,000 − 30,000 = 2,20,000. FCF = 4,20,000 − 2,20,000 = ₹2,00,000. Ignoring the disposal proceeds gives ₹1,70,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-121","question":"Current assets are ₹4,80,000 and current liabilities ₹2,00,000. What is the current ratio?","options":["0.42 : 1","1.4 : 1","2.4 : 1","2.8 : 1"],"answer":2,"explanation":"Current ratio = 4,80,000 ÷ 2,00,000 = 2.4 : 1.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-122","question":"Current assets of ₹6,00,000 include inventory of ₹1,80,000 and prepaid expenses of ₹20,000. Current liabilities are ₹2,50,000. What is the quick ratio?","options":["1.68 : 1","2.4 : 1","1.6 : 1","1.52 : 1"],"answer":2,"explanation":"Quick assets = 6,00,000 − 1,80,000 − 20,000 = 4,00,000; quick ratio = 4,00,000 ÷ 2,50,000 = 1.6 : 1. Removing only inventory gives 1.68.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-123","question":"A company's current ratio is 2.5 : 1, its quick ratio 1.5 : 1 and its working capital ₹1,20,000. Current assets consist only of quick assets and inventory. What is the inventory?","options":["₹1,20,000","₹40,000","₹80,000","₹2,00,000"],"answer":2,"explanation":"CA − CL = 1,20,000 and CA = 2.5 CL, so 1.5 CL = 1,20,000: CL = 80,000, CA = 2,00,000. Quick assets = 1.5 × 80,000 = 1,20,000, so inventory = 2,00,000 − 1,20,000 = ₹80,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-124","question":"A company's current ratio is 2 : 1. Which of these would increase it? (1) Paying a trade creditor in cash (2) Buying stock on credit (3) Raising a long-term loan in cash (4) Selling stock costing ₹10,000 for ₹8,000 cash","options":["(1) only","(1) and (3) only","(1), (3) and (4)","(2) and (3) only"],"answer":1,"explanation":"(1) Equal fall in CA and CL raises a ratio above 1 (e.g. 4/2 → 3/1). (2) Equal rise lowers it (4/2 → 5/3). (3) CA rises with no current liability: up. (4) CA falls by the ₹2,000 loss: down. So (1) and (3).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-125","question":"Equity share capital ₹5,00,000; reserves ₹3,00,000; 10% debentures ₹4,00,000; long-term bank loan ₹2,00,000; trade creditors ₹1,00,000. What is the debt–equity ratio?","options":["0.875 : 1","1.2 : 1","0.75 : 1","1.33 : 1"],"answer":2,"explanation":"Long-term debt = 4,00,000 + 2,00,000 = 6,00,000; equity = 5,00,000 + 3,00,000 = 8,00,000. Ratio = 0.75 : 1. Including creditors gives 0.875; leaving out reserves gives 1.2.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-126","question":"Profit after tax is ₹2,10,000, the tax rate is 30% and debenture interest is ₹60,000. What is the interest coverage ratio?","options":["3.5 times","5 times","6 times","4.5 times"],"answer":2,"explanation":"PBT = 2,10,000 ÷ 0.7 = 3,00,000; EBIT = 3,00,000 + 60,000 = 3,60,000. Coverage = 3,60,000 ÷ 60,000 = 6 times. Using PAT gives 3.5 and PBT gives 5.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-127","question":"Cost of goods sold is ₹7,20,000; opening inventory ₹80,000 and closing inventory ₹1,00,000. What is the inventory turnover ratio?","options":["7.2 times","9 times","8 times","10 times"],"answer":2,"explanation":"Average inventory = (80,000 + 1,00,000) ÷ 2 = 90,000. Turnover = 7,20,000 ÷ 90,000 = 8 times.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-128","question":"Sales are ₹12,00,000 with a gross profit of 25% on sales. Opening inventory is ₹1,40,000 and closing inventory ₹1,60,000. What is the inventory turnover ratio?","options":["8 times","6.4 times","7.5 times","6 times"],"answer":3,"explanation":"COGS = 75% × 12,00,000 = 9,00,000; average inventory = 1,50,000; turnover = 6 times. Using sales gives 8; treating 25% as a mark-up on cost gives 6.4.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-129","question":"Total sales are ₹9,60,000, of which 75% are on credit. Debtors were ₹80,000 at the start and ₹1,00,000 at the end of the year, and bills receivable of ₹20,000 are held at the end. Using a 360-day year, what is the average collection period?","options":["45 days","37.5 days","50 days","60 days"],"answer":2,"explanation":"Credit sales = 7,20,000. Closing receivables = 1,00,000 + 20,000 = 1,20,000; average = (80,000 + 1,20,000) ÷ 2 = 1,00,000. Turnover = 7.2; period = 360 ÷ 7.2 = 50 days. Ignoring bills receivable gives 45 days; using total sales gives 37.5.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-130","question":"Goods are sold at a mark-up of 25% on cost. What is the gross profit ratio?","options":["25%","20%","33.33%","12.5%"],"answer":1,"explanation":"Cost 100, price 125, profit 25: margin on sales = 25 ÷ 125 = 20%.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-131","question":"Net profit margin is 8%, total asset turnover 1.5 times, total assets ₹12,00,000 and shareholders' equity ₹4,80,000. What is the return on equity?","options":["12%","30%","20%","25%"],"answer":1,"explanation":"DuPont: ROE = margin × asset turnover × equity multiplier = 8% × 1.5 × (12,00,000 ÷ 4,80,000 = 2.5) = 30%. 12% is the return on assets.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-132","question":"A company's ROE is 18%, its ROA 6% and its net profit margin 4%. Assets are financed only by equity and liabilities. What is its total liabilities to total assets ratio?","options":["33.33%","50%","66.67%","75%"],"answer":2,"explanation":"Equity multiplier = ROE ÷ ROA = 3, so equity is one-third of assets and liabilities two-thirds: 66.67%. (Asset turnover = 6% ÷ 4% = 1.5 is not needed.)","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-133","question":"Shareholders' funds are ₹6,00,000 and total assets ₹10,00,000. What is the proprietary ratio?","options":["0.6 : 1","1.5 : 1","0.4 : 1","1.67 : 1"],"answer":0,"explanation":"Proprietary ratio = shareholders' funds ÷ total assets = 0.6 : 1.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-134","question":"Current ratio 2.5 : 1; quick ratio 1.5 : 1; current liabilities ₹1,60,000; inventory turnover (on cost of goods sold) 6 times, with opening and closing inventory equal; gross profit 20% of sales. What are the sales?","options":["₹9,60,000","₹11,52,000","₹12,00,000","₹19,20,000"],"answer":2,"explanation":"Inventory = (2.5 − 1.5) × 1,60,000 = 1,60,000. COGS = 6 × 1,60,000 = 9,60,000. Sales = 9,60,000 ÷ 0.8 = ₹12,00,000. Adding 20% to cost gives ₹11,52,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-135","question":"EBIT is ₹3,00,000, including ₹20,000 income from non-trade investments of ₹2,00,000. Capital employed is equity ₹12,00,000 plus long-term debt ₹8,00,000 (these funds include the investments). What is the ROCE after excluding the investments and their income?","options":["15%","15.56%","25%","14%"],"answer":1,"explanation":"Operating EBIT = 3,00,000 − 20,000 = 2,80,000; operating capital employed = 20,00,000 − 2,00,000 = 18,00,000. ROCE = 15.56%. Not excluding either gives 15%.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-136","question":"Profit after tax is ₹12,00,000, preference dividend ₹2,00,000, and there are 2,00,000 equity shares. What is the EPS?","options":["₹6","₹5","₹7","₹4"],"answer":1,"explanation":"EPS = (12,00,000 − 2,00,000) ÷ 2,00,000 = ₹5. Forgetting the preference dividend gives ₹6.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-137","question":"EPS is ₹5, the market price ₹60 and the dividend per share ₹2. What are the payout ratio and the dividend yield?","options":["Payout 60%, yield 3.33%","Payout 40%, yield 8.33%","Payout 40%, yield 3.33%","Payout 2.5%, yield 12%"],"answer":2,"explanation":"Payout = DPS ÷ EPS = 2 ÷ 5 = 40%. Yield = DPS ÷ price = 2 ÷ 60 = 3.33%. (8.33% is EPS ÷ price, the earnings yield.)","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-138","question":"Quick assets are ₹3,60,000 and current liabilities ₹3,00,000. The company then buys inventory worth ₹60,000 on credit. What is the new quick ratio?","options":["1.2 : 1","1.4 : 1","1.0 : 1","0.83 : 1"],"answer":2,"explanation":"Inventory is not a quick asset, but the creditor is a current liability: 3,60,000 ÷ 3,60,000 = 1.0 : 1.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-139","question":"Liquidity ratios measure a firm's:","options":["Long-term solvency","Profitability","Efficiency in using its assets","Ability to meet short-term obligations"],"answer":3,"explanation":"Current and quick ratios test whether current assets can cover current liabilities.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-140","question":"Cost of goods sold is ₹6,00,000, operating expenses ₹1,00,000 and net sales ₹8,75,000. What is the operating ratio?","options":["68.57%","80%","20%","85%"],"answer":1,"explanation":"Operating ratio = (COGS + operating expenses) ÷ net sales = 7,00,000 ÷ 8,75,000 = 80%. 68.57% leaves out operating expenses.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-141","question":"Profit after tax ₹3,00,000; depreciation ₹50,000; interest on term loan ₹1,00,000; principal instalment due ₹1,50,000. What is the debt service coverage ratio?","options":["1.4 times","3.0 times","1.8 times","4.5 times"],"answer":2,"explanation":"DSCR = (PAT + depreciation + interest) ÷ (interest + principal) = 4,50,000 ÷ 2,50,000 = 1.8 times. Leaving interest out of the numerator gives 1.4.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-142","question":"Current assets are ₹3,00,000 and current liabilities ₹1,50,000. A machine is bought for ₹50,000: ₹20,000 in cash and the rest by a three-month bill payable. What is the new current ratio?","options":["1.87 : 1","1.67 : 1","1.56 : 1","2.0 : 1"],"answer":2,"explanation":"CA = 3,00,000 − 20,000 = 2,80,000; CL = 1,50,000 + 30,000 = 1,80,000. Ratio = 1.56 : 1. Forgetting the bill payable gives 1.87.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-143","question":"Sales are ₹18,00,000, fixed assets ₹6,00,000 and current assets ₹3,00,000. What is the total asset turnover?","options":["3 times","2 times","6 times","1.5 times"],"answer":1,"explanation":"Total assets = 9,00,000; turnover = 18,00,000 ÷ 9,00,000 = 2 times. 3 times is the fixed-asset turnover.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-144","question":"Assertion (A): A very high current ratio may indicate poor working-capital management. Reason (R): Excess current assets such as idle cash or slow-moving stock earn little or no return.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A high ratio is safe for creditors but often means funds are locked in idle cash, excess stock or slow debtors, which earn nothing. That is exactly why it can signal inefficiency.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-145","question":"How many of these statements are true? (1) Issuing equity shares for cash lowers the debt–equity ratio. (2) Converting debentures into equity shares lowers the debt–equity ratio. (3) Redeeming debentures out of cash raises the current ratio. (4) A bonus issue changes the debt–equity ratio.","options":["One","Two","Three","Four"],"answer":1,"explanation":"(1) True: equity rises. (2) True: debt falls and equity rises. (3) False: cash (a current asset) falls with no change in current liabilities, so the ratio falls. (4) False: reserves become share capital, total equity is unchanged. Two are true.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-146","question":"Credit sales are ₹7,20,000 and the average collection period is 45 days (360-day year). What are the average debtors?","options":["₹1,60,000","₹72,000","₹90,000","₹80,000"],"answer":2,"explanation":"Debtors turnover = 360 ÷ 45 = 8; average debtors = 7,20,000 ÷ 8 = ₹90,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-147","question":"Which of these is a solvency (long-term) ratio?","options":["Current ratio","Inventory turnover","Debt–equity ratio","Gross profit ratio"],"answer":2,"explanation":"Debt–equity measures long-term financial risk; current ratio is liquidity, inventory turnover is activity and GP ratio is profitability.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-148","question":"Fixed-asset turnover is 4 times on fixed assets of ₹3,00,000; gross profit is 25% of sales; inventory turnover is 8 times on cost of goods sold. What is the average inventory?","options":["₹1,50,000","₹1,20,000","₹1,12,500","₹1,00,000"],"answer":2,"explanation":"Sales = 4 × 3,00,000 = 12,00,000; COGS = 9,00,000; average inventory = 9,00,000 ÷ 8 = ₹1,12,500. Dividing sales by 8 gives ₹1,50,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-149","question":"Net profit is ₹72,000, gross sales ₹9,60,000 and sales returns ₹60,000. What is the net profit ratio?","options":["7.5%","12%","8%","9%"],"answer":2,"explanation":"Net sales = 9,00,000; NP ratio = 72,000 ÷ 9,00,000 = 8%. Using gross sales gives 7.5%.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-150","question":"Which statement about financial leverage and the gap between ROE and ROA is correct?","options":["ROE always exceeds ROA once a firm borrows","Leverage raises ROE whenever interest rates are positive","ROE equals ROA multiplied by the debt ratio","Borrowing raises ROE only while the return earned on assets exceeds the after-tax cost of debt"],"answer":3,"explanation":"Debt magnifies returns both ways. If assets earn more than debt costs after tax, the surplus accrues to equity and ROE rises; if they earn less, ROE falls below what it would be unlevered.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-151","question":"Sales are ₹5,00,000, variable costs ₹3,00,000 and fixed costs ₹1,20,000. What is the P/V ratio?","options":["40%","60%","16%","24%"],"answer":0,"explanation":"Contribution = 5,00,000 − 3,00,000 = 2,00,000; P/V ratio = 2,00,000 ÷ 5,00,000 = 40%. 60% is the variable-cost ratio.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-152","question":"Fixed costs are ₹1,20,000 and the P/V ratio is 40%. What is the break-even sales?","options":["₹2,00,000","₹4,80,000","₹1,68,000","₹3,00,000"],"answer":3,"explanation":"BEP = fixed cost ÷ P/V ratio = 1,20,000 ÷ 0.40 = ₹3,00,000. Dividing by the variable-cost ratio (60%) gives ₹2,00,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-153","question":"Actual sales are ₹5,00,000, break-even sales ₹3,00,000 and the P/V ratio 40%. What is the profit?","options":["₹80,000","₹1,20,000","₹2,00,000","₹60,000"],"answer":0,"explanation":"Margin of safety = 2,00,000; profit = MoS × P/V ratio = 2,00,000 × 40% = ₹80,000. ₹2,00,000 is the margin of safety itself.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-154","question":"With sales of ₹4,00,000 a firm earns ₹20,000; with sales of ₹5,00,000 it earns ₹50,000. Selling price and costs per unit do not change. What is the break-even sales?","options":["₹3,33,333","₹3,00,000","₹2,50,000","₹4,00,000"],"answer":0,"explanation":"P/V ratio = change in profit ÷ change in sales = 30,000 ÷ 1,00,000 = 30%. Fixed cost = 4,00,000 × 30% − 20,000 = 1,00,000. BEP = 1,00,000 ÷ 0.30 = ₹3,33,333.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-155","question":"Selling price ₹50 a unit, variable cost ₹30 a unit, fixed costs ₹2,00,000. The firm wants a profit after tax of ₹60,000; the tax rate is 25%. How many units must it sell?","options":["13,000 units","13,750 units","10,000 units","14,000 units"],"answer":3,"explanation":"Profit before tax needed = 60,000 ÷ 0.75 = 80,000. Units = (2,00,000 + 80,000) ÷ 20 = 14,000. Ignoring tax gives 13,000; adding 25% to the after-tax profit (75,000) gives 13,750.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-156","question":"Product A sells at ₹100 with variable cost ₹60; product B sells at ₹80 with variable cost ₹60. They are sold in the ratio 3 units of A to 2 units of B, and fixed costs are ₹1,60,000. How many units in total must be sold to break even?","options":["4,000 units","5,000 units","5,333 units","8,000 units"],"answer":1,"explanation":"Contribution per mix of 5 units = 3 × 40 + 2 × 20 = 160, so ₹32 per unit on average. BEP = 1,60,000 ÷ 32 = 5,000 units (3,000 A and 2,000 B). A simple average contribution of ₹30 gives 5,333.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-157","question":"Direct materials ₹2,00,000; direct labour ₹1,20,000; direct expenses ₹30,000; factory overheads ₹80,000; opening work-in-progress ₹20,000; closing work-in-progress ₹30,000. What is the works (factory) cost?","options":["₹4,20,000","₹4,30,000","₹4,70,000","₹3,50,000"],"answer":0,"explanation":"Prime cost = 3,50,000. Works cost = 3,50,000 + 80,000 + 20,000 − 30,000 = ₹4,20,000. ₹4,30,000 forgets the work-in-progress adjustment; ₹3,50,000 is prime cost.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-158","question":"Cost of production is ₹5,00,000; opening finished goods ₹40,000; closing finished goods ₹60,000; selling and distribution overheads ₹30,000. What is the cost of sales?","options":["₹4,80,000","₹5,10,000","₹5,30,000","₹5,00,000"],"answer":1,"explanation":"Cost of goods sold = 5,00,000 + 40,000 − 60,000 = 4,80,000; cost of sales = 4,80,000 + 30,000 = ₹5,10,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-159","question":"A firm with no opening stock produces 10,000 units and sells 8,000. Fixed manufacturing overhead is ₹1,50,000. How do profits under absorption costing and marginal costing compare?","options":["Absorption profit higher by ₹30,000","Marginal profit higher by ₹30,000","Absorption profit higher by ₹37,500","Both profits are equal"],"answer":0,"explanation":"Absorption costing carries ₹15 of fixed overhead per unit (1,50,000 ÷ 10,000) into the 2,000 units of closing stock, deferring ₹30,000 to the next period, so its profit is higher by ₹30,000. Spreading the overhead over units sold gives the wrong ₹37,500.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-160","question":"Machine hours are limited to 8,000. Product X gives a contribution of ₹40 a unit and needs 4 hours; product Y gives ₹30 and needs 2 hours. Maximum demand is 1,500 units of X and 3,000 of Y. What is the maximum contribution?","options":["₹90,000","₹1,20,000","₹1,50,000","₹1,10,000"],"answer":3,"explanation":"Contribution per hour: X ₹10, Y ₹15, so make Y first: 3,000 units use 6,000 hours (₹90,000). The remaining 2,000 hours make 500 units of X (₹20,000). Total ₹1,10,000. Ranking by contribution per unit (X first) gives only ₹90,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-161","question":"A component costs ₹42 a unit in variable cost to make, plus ₹10 a unit of allocated fixed overhead that will continue whether it is made or bought. A supplier offers it at ₹48. What should the firm do?","options":["Buy, saving ₹4 a unit","Make, saving ₹6 a unit","Buy, since the full cost of ₹52 exceeds ₹48","It is indifferent"],"answer":1,"explanation":"The fixed overhead is unavoidable, so only the variable ₹42 is relevant. Buying at ₹48 costs ₹6 a unit more, so make. Comparing ₹48 with the full cost of ₹52 is the classic mistake.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-162","question":"A firm has idle capacity. Its normal price is ₹100 a unit and variable cost ₹70. A customer offers to buy 2,000 extra units at ₹80; fixed costs will not change. What is the effect of accepting?","options":["Profit rises by ₹20,000","Profit falls by ₹40,000","No change in profit","Profit rises by ₹60,000"],"answer":0,"explanation":"Each extra unit adds ₹80 − ₹70 = ₹10 of contribution: 2,000 × 10 = ₹20,000. With spare capacity and no effect on regular prices, the order is worth taking.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-163","question":"As output increases within the relevant range, fixed cost per unit:","options":["Rises","Stays constant","Rises and then falls","Falls"],"answer":3,"explanation":"Total fixed cost is constant, so spreading it over more units lowers the cost per unit. Variable cost per unit stays constant.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-164","question":"A firm's margin of safety is 25% of sales and its P/V ratio is 40%. Sales are ₹8,00,000. What is the profit?","options":["₹80,000","₹2,00,000","₹3,20,000","₹1,00,000"],"answer":0,"explanation":"Profit = margin of safety × P/V ratio = (25% × 8,00,000) × 40% = 2,00,000 × 40% = ₹80,000; i.e. profit is 10% of sales.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-165","question":"Selling price is ₹40 a unit, variable cost ₹24 and fixed costs ₹1,60,000. If the selling price is cut by 10%, by what percentage does the break-even point in units rise?","options":["10% increase","33.33% increase","25% increase","16.67% increase"],"answer":1,"explanation":"Old contribution ₹16 → BEP 10,000 units. New price ₹36 → contribution ₹12 → BEP 13,333 units, a rise of 33.33%. A 10% price cut wipes out 25% of the contribution, so the BEP jumps far more than 10%.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-166","question":"Total cost is ₹1,80,000 at 10,000 units and ₹2,30,000 at 15,000 units. Using the high–low method, what is the expected total cost at 12,000 units?","options":["₹2,16,000","₹1,84,000","₹2,04,000","₹2,00,000"],"answer":3,"explanation":"Variable cost = 50,000 ÷ 5,000 = ₹10 a unit; fixed cost = 1,80,000 − 1,00,000 = 80,000. At 12,000 units: 80,000 + 1,20,000 = ₹2,00,000. Scaling the whole cost up by 20% gives ₹2,16,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-167","question":"A firm sells 10,000 units at ₹60 with variable cost ₹36 and fixed costs ₹1,80,000. If variable cost rises by 10% and the price is unchanged, how many units must it sell to keep the same profit?","options":["11,765 units","11,000 units","10,909 units","12,500 units"],"answer":0,"explanation":"Current profit = 10,000 × 24 − 1,80,000 = 60,000. New variable cost ₹39.60, contribution ₹20.40. Units = (1,80,000 + 60,000) ÷ 20.40 ≈ 11,765.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-168","question":"Plan A has fixed costs of ₹2,00,000 and variable costs of 60% of sales. Plan B has fixed costs of ₹3,20,000 and variable costs of 40% of sales. At what level of sales are the two plans equally profitable?","options":["₹3,00,000","₹8,00,000","₹5,00,000","₹6,00,000"],"answer":3,"explanation":"Equal profit when the extra fixed cost of B equals its extra contribution: (3,20,000 − 2,00,000) ÷ (60% − 40%) = ₹6,00,000. Above this, B (higher P/V ratio) is better. ₹5,00,000 and ₹8,00,000 are the break-even points of A and B.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-169","question":"Budgeted overheads are ₹4,80,000 for 60,000 budgeted machine hours. Actual hours worked are 64,000 and actual overheads ₹5,00,000. What is the over- or under-absorption?","options":["Over-absorbed ₹12,000","Under-absorbed ₹20,000","Under-absorbed ₹12,000","Over-absorbed ₹32,000"],"answer":0,"explanation":"Rate = ₹8 an hour; absorbed = 64,000 × 8 = 5,12,000; actual 5,00,000. More was absorbed than incurred: over-absorbed by ₹12,000. Comparing actual with budget gives the misleading ₹20,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-170","question":"A factory had 900 workers at the start of the year and 1,100 at the end; 50 workers left during the year. What is the labour turnover rate by the separation method?","options":["5%","4.55%","5.56%","10%"],"answer":0,"explanation":"Average workers = (900 + 1,100) ÷ 2 = 1,000; turnover = 50 ÷ 1,000 = 5%. Dividing by the closing or opening figure gives 4.55% or 5.56%.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-171","question":"Annual demand is 9,000 units, the cost of placing an order ₹240, the unit price ₹60 and the annual carrying cost 20% of the unit price. What is the economic order quantity?","options":["600 units","849 units","300 units","1,200 units"],"answer":0,"explanation":"Carrying cost = 20% × 60 = ₹12 a unit a year. EOQ = √(2 × 9,000 × 240 ÷ 12) = √3,60,000 = 600 units. Using a ₹6 carrying cost (10%) gives 849.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-172","question":"Maximum usage is 500 units a day and the maximum lead time 12 days; normal usage is 400 units a day and the normal lead time 10 days. What is the minimum stock level?","options":["4,000 units","6,000 units","1,500 units","2,000 units"],"answer":3,"explanation":"Re-order level = 500 × 12 = 6,000. Minimum level = re-order level − normal usage × normal lead time = 6,000 − 4,000 = 2,000 units.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-173","question":"Opening stock is 100 units at ₹20; 200 units are bought at ₹23; then 250 units are issued. How does the closing stock under FIFO compare with that under the weighted average method?","options":["₹50 higher under FIFO","₹50 lower under FIFO","₹150 higher under FIFO","No difference"],"answer":0,"explanation":"FIFO: the 50 units left are from the ₹23 lot = ₹1,150. Weighted average rate = (2,000 + 4,600) ÷ 300 = ₹22, so closing = 50 × 22 = ₹1,100. FIFO is ₹50 higher (prices are rising).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-174","question":"Which of these is a period cost that is not included in inventory?","options":["Direct labour","Factory rent","Raw materials","Salesmen's commission"],"answer":3,"explanation":"Selling costs are charged to the period in which they arise; materials, labour and factory overheads are product costs carried in inventory.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-175","question":"The P/V ratio is 25%, fixed costs ₹1,50,000 and sales ₹8,00,000. What is the profit?","options":["₹2,00,000","₹6,50,000","₹1,00,000","₹50,000"],"answer":3,"explanation":"Contribution = 25% × 8,00,000 = 2,00,000; profit = 2,00,000 − 1,50,000 = ₹50,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-176","question":"The standard price of a material is ₹20 a kg. 5,000 kg are bought and used at ₹22 a kg. What is the material price variance?","options":["₹10,000 (F)","₹10,000 (A)","₹11,000 (A)","₹9,091 (A)"],"answer":1,"explanation":"Price variance = AQ × (SP − AP) = 5,000 × (20 − 22) = −10,000, adverse because more was paid than standard.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-177","question":"The standard is 2 kg of material at ₹20 a kg per unit. 2,400 units are produced using 5,000 kg bought at ₹22 a kg. What is the material usage variance?","options":["₹4,400 (A)","₹4,000 (F)","₹4,000 (A)","₹8,000 (A)"],"answer":2,"explanation":"Standard quantity for actual output = 2,400 × 2 = 4,800 kg. Usage variance = SP × (SQ − AQ) = 20 × (4,800 − 5,000) = ₹4,000 adverse. Valuing at the actual price (₹22) gives ₹4,400, which wrongly mixes in price.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-178","question":"The standard is 2 kg at ₹20 a kg per unit. 2,400 units are made using 5,000 kg costing ₹22 a kg. What is the material cost variance?","options":["₹6,000 (A)","₹14,000 (A)","₹14,000 (F)","₹10,000 (A)"],"answer":1,"explanation":"Standard cost = 4,800 × 20 = 96,000; actual cost = 5,000 × 22 = 1,10,000. Cost variance = ₹14,000 adverse = price variance ₹10,000 (A) + usage variance ₹4,000 (A).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-179","question":"Standard: 3 labour hours per unit at ₹40 an hour. 1,000 units are produced; 3,300 hours are paid at ₹42, of which 100 hours were idle because of a machine breakdown. What is the labour efficiency variance?","options":["₹12,000 (A)","₹8,000 (A)","₹8,400 (A)","₹4,000 (A)"],"answer":1,"explanation":"Hours worked = 3,300 − 100 = 3,200; standard hours = 3,000. Efficiency = 40 × (3,000 − 3,200) = ₹8,000 (A). Idle time (100 × 40 = ₹4,000 A) and rate (3,300 × 2 = ₹6,600 A) are separate; together they make up the total ₹18,600 (A). Ignoring idle time gives ₹12,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-180","question":"The standard mix is 60% material A at ₹50 a kg and 40% material B at ₹30 a kg. The actual input is 1,000 kg: 650 kg of A and 350 kg of B. What is the material mix variance?","options":["₹1,000 (F)","₹4,000 (A)","₹1,000 (A)","₹2,500 (A)"],"answer":2,"explanation":"Revised standard quantities for 1,000 kg: A 600, B 400. Mix variance = SP × (RSQ − AQ): A 50 × (600 − 650) = −2,500; B 30 × (400 − 350) = +1,500. Net ₹1,000 adverse: more of the dearer material was used.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-181","question":"Budgeted fixed overhead is ₹1,20,000 for 12,000 units (₹10 a unit). Actual output is 11,000 units and actual fixed overhead ₹1,26,000. What is the fixed overhead volume variance?","options":["₹6,000 (A)","₹16,000 (A)","₹10,000 (F)","₹10,000 (A)"],"answer":3,"explanation":"Volume variance = rate × (actual output − budgeted output) = 10 × (11,000 − 12,000) = ₹10,000 (A). The ₹6,000 (A) is the expenditure variance; together they make the total ₹16,000 (A).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-182","question":"The standard selling price is ₹50 a unit. 10,000 units are actually sold at ₹48. What is the sales price variance?","options":["₹20,000 (F)","₹20,000 (A)","₹19,200 (A)","₹2,000 (A)"],"answer":1,"explanation":"Sales price variance = actual units × (actual price − standard price) = 10,000 × (48 − 50) = ₹20,000 adverse.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-183","question":"Budgeted sales were 12,000 units at ₹50 with a standard contribution of ₹15 a unit; actual sales were 10,000 units. Under marginal costing, what is the sales volume variance?","options":["₹1,00,000 (A)","₹30,000 (A)","₹30,000 (F)","₹24,000 (A)"],"answer":1,"explanation":"Under marginal costing the volume variance is valued at standard contribution: (10,000 − 12,000) × 15 = ₹30,000 (A). Valuing it at the selling price (₹1,00,000) overstates the effect on profit.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-184","question":"A cost variance is favourable when:","options":["Actual cost exceeds standard cost","Actual output is below budget","Actual cost is below standard cost","The standard is revised upward"],"answer":2,"explanation":"Spending less than the standard for the actual output is favourable; spending more is adverse.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-185","question":"At 10,000 units the budget shows variable costs ₹2,00,000, semi-variable costs ₹80,000 (50% fixed) and fixed costs ₹1,00,000. What is the flexible budget cost at 12,000 units?","options":["₹4,56,000","₹4,36,000","₹4,28,000","₹3,80,000"],"answer":2,"explanation":"Variable: 2,00,000 × 1.2 = 2,40,000. Semi-variable: 40,000 fixed + 40,000 × 1.2 = 88,000. Fixed 1,00,000. Total ₹4,28,000. Treating all semi-variable cost as variable gives ₹4,36,000; scaling everything gives ₹4,56,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-186","question":"Sales are ₹1,00,000 in January, ₹1,20,000 in February and ₹1,50,000 in March. 20% of sales are for cash; credit sales are collected 50% in the next month and 50% in the month after. What are the total cash receipts in March?","options":["₹1,20,000","₹1,10,000","₹1,35,000","₹1,18,000"],"answer":3,"explanation":"March cash sales 30,000; half of February's credit sales (96,000) = 48,000; half of January's credit sales (80,000) = 40,000. Total ₹1,18,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-187","question":"Budgeted sales are 20,000 units. Finished-goods stock is 3,000 units at the start and should be 4,500 at the end. Each unit needs 2 kg of material; material stock is 6,000 kg at the start and should be 8,000 kg at the end. How much material must be purchased?","options":["45,000 kg","43,000 kg","40,000 kg","41,000 kg"],"answer":0,"explanation":"Production = 20,000 + 4,500 − 3,000 = 21,500 units → 43,000 kg needed. Purchases = 43,000 + 8,000 − 6,000 = 45,000 kg. 43,000 kg ignores the material stock change; 40,000 kg budgets on sales instead of production.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-188","question":"Zero-based budgeting is best described as:","options":["Last year's figures adjusted for inflation","A budget that changes with the level of activity","A rolling budget updated every quarter","A budget in which every activity must be justified afresh, starting from zero"],"answer":3,"explanation":"ZBB ignores the previous year's base; each activity must be justified by its costs and benefits. A budget that changes with activity is a flexible budget.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-189","question":"A proprietor's household electricity bill paid from the business bank account is recorded as drawings, not as an expense of the business. Which concept requires this?","options":["Going concern","Money measurement","Business entity","Accrual"],"answer":2,"explanation":"The business entity concept treats the business as separate from its owner, so the owner's personal expenses are drawings.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-190","question":"Under Ind AS 115, a company sells 1,000 units at ₹500 each with a right of return; it expects 5% of the goods to be returned. Each unit costs ₹300. How much revenue is recognised?","options":["₹5,00,000","₹4,75,000","₹4,85,000","₹2,85,000"],"answer":1,"explanation":"Revenue is recognised only for the consideration the company expects to keep: 950 units × 500 = ₹4,75,000. A refund liability of ₹25,000 and an asset for the right to recover goods (50 × 300 = ₹15,000) are also recognised.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-191","question":"Under Ind AS 115, a company sells a machine together with two years of servicing for ₹1,20,000. Sold separately, the machine would fetch ₹1,00,000 and the servicing ₹50,000. How much revenue is allocated to the machine?","options":["₹1,00,000","₹70,000","₹80,000","₹1,20,000"],"answer":2,"explanation":"The price is allocated in proportion to stand-alone selling prices: 1,20,000 × 1,00,000/1,50,000 = ₹80,000 (servicing ₹40,000, recognised over two years). Giving the servicing its full ₹50,000 and the machine the remainder (₹70,000) is not the relative method.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-192","question":"A customer has sued a company. Its lawyers say a loss is possible but not probable, and the amount cannot be estimated reliably. How is this treated under Ind AS 37?","options":["Disclosed as a contingent liability in the notes","A provision is recognised","Ignored completely","Recognised as both a liability and an asset"],"answer":0,"explanation":"A provision needs a probable outflow and a reliable estimate. A possible obligation is disclosed as a contingent liability; only a remote one is ignored.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-193","question":"Under Ind AS 10, how many of these are adjusting events for a company whose year ends on 31 March? (1) A debtor owing money on 31 March is declared bankrupt in April. (2) A warehouse is destroyed by fire in May, before the accounts are approved. (3) An equity dividend is proposed after the year end and is shown as a liability at year end. (4) A court case pending at year end is settled in April, confirming an obligation that existed on 31 March.","options":["One","Two","Three","Four"],"answer":1,"explanation":"(1) Adjusting: it confirms the debt was bad at year end. (2) Non-adjusting: the fire is a new event. (3) Wrong treatment: a dividend proposed after year end is not a liability at year end, so it is not an adjusting event. (4) Adjusting. Two are adjusting events.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-194","question":"Which of these is an example of 'substance over form'?","options":["Recording goods at cost, not market value","Recording only transactions that can be measured in money","Assuming the business will continue for the foreseeable future","A lessee recognising a right-of-use asset for a machine it does not legally own"],"answer":3,"explanation":"Under Ind AS 116 the lessee controls the asset's use for the lease term, so the economic substance (an asset and a lease liability) is recorded despite the legal form (ownership stays with the lessor).","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-195","question":"A company changes its inventory cost formula from FIFO to weighted average to give more relevant information. How does Ind AS 8 require this to be applied?","options":["Prospectively only","Retrospectively, restating comparatives, unless impracticable","By disclosure only, with no adjustment","By charging the whole cumulative effect to the current year's profit without restating"],"answer":1,"explanation":"A change in the cost formula is a change in accounting policy. Ind AS 8 requires retrospective application, adjusting opening equity and comparatives, unless that is impracticable.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-196","question":"An asset's carrying amount is ₹10,00,000. Its fair value less costs of disposal is ₹7,80,000 and its value in use is ₹8,20,000. What impairment loss is recognised under Ind AS 36?","options":["₹2,20,000","₹1,80,000","₹2,00,000","Nil"],"answer":1,"explanation":"Recoverable amount is the higher of the two, ₹8,20,000. Impairment = 10,00,000 − 8,20,000 = ₹1,80,000. Using the lower figure gives ₹2,20,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-197","question":"A standard cost is:","options":["A predetermined cost of what a unit should cost under efficient conditions","The actual historical cost of the last batch","The market price of the finished product","The average cost of all competitors"],"answer":0,"explanation":"Standards are set in advance; comparing them with actual costs gives the variances used for control.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-198","question":"Standard: 2 machine hours per unit and variable overhead of ₹15 an hour. 4,000 units are produced in 8,400 hours, and actual variable overhead is ₹1,30,000. What is the variable overhead expenditure variance?","options":["₹10,000 (A)","₹6,000 (A)","₹4,000 (F)","₹4,000 (A)"],"answer":3,"explanation":"Expenditure variance = actual hours × standard rate − actual overhead = 8,400 × 15 − 1,30,000 = −4,000 (A). Efficiency = 15 × (8,000 − 8,400) = ₹6,000 (A). Total ₹10,000 (A).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-199","question":"In budgeting, the 'principal budget factor' (key factor) is:","options":["The factor that limits the organisation's activity, such as sales demand","The budget with the largest rupee amount","The fixed overhead budget","The cash budget"],"answer":0,"explanation":"The key factor limits activity, often sales demand but sometimes materials, labour or machine capacity, so it is budgeted first and the other budgets follow from it.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-200","question":"The standard labour rate is ₹50 an hour; 2,000 hours are paid at ₹48 an hour. What is the labour rate variance?","options":["₹4,000 (A)","₹96,000 (F)","₹4,000 (F)","₹3,840 (F)"],"answer":2,"explanation":"Rate variance = actual hours paid × (SR − AR) = 2,000 × (50 − 48) = ₹4,000, favourable because less was paid than standard.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-201","question":"Goods are sent on consignment by a manufacturer to an agent in another city. Until the agent sells them, who owns the goods?","options":["The consignor (the manufacturer)","The consignee (the agent)","The carrier while they are in transit, then the agent","The eventual buyer, from the date of dispatch"],"answer":0,"explanation":"A consignment is an agency arrangement: the consignee only holds and sells the goods for the consignor, so ownership stays with the consignor until a sale to a third party. That is why unsold goods with the agent appear in the consignor's closing stock.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-202","question":"1,000 units costing ₹200 each are sent on consignment. The consignor pays freight of ₹10,000 and the consignee pays unloading and carriage to his godown of ₹4,000; the consignee also spends ₹6,000 on advertising and selling. 800 units are sold. At what value is the unsold stock carried?","options":["₹40,000","₹42,000","₹44,000","₹42,800"],"answer":3,"explanation":"Unsold stock carries its cost plus a proportion of the expenses incurred to bring the goods to the place of sale (freight and the consignee's unloading and carriage), but not selling expenses: 200 × (200 + 14,000 ÷ 1,000) = 200 × 214 = ₹42,800. ₹44,000 wrongly loads the selling expenses; ₹42,000 picks up only the consignor's freight.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-203","question":"A consignee sells consigned goods for ₹5,00,000: ₹3,00,000 in cash and ₹2,00,000 on credit. He gets 5% ordinary commission and 2% del credere commission, both on total sales. ₹8,000 of the credit sales turn out to be bad. Ignoring expenses, how much does the consignor finally receive for these sales?","options":["₹4,57,000","₹4,65,000","₹4,71,000","₹4,75,000"],"answer":1,"explanation":"With del credere commission the consignee guarantees the debts, so the ₹8,000 bad debt is his loss, not the consignor's. Consignor gets 5,00,000 − 7% × 5,00,000 = ₹4,65,000. ₹4,57,000 also deducts the bad debt; ₹4,71,000 applies the 2% to credit sales only; ₹4,75,000 forgets the del credere commission.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-204","question":"A and B enter a joint venture sharing profits 3 : 2. A buys goods for ₹60,000 and pays ₹4,000 of expenses. B sells goods for ₹90,000, pays ₹6,000 of expenses and takes over the unsold goods at an agreed ₹5,000. B holds all the cash from sales. How much must B pay A in final settlement?","options":["₹64,000","₹76,000","₹74,000","₹79,000"],"answer":3,"explanation":"Venture profit = sales 90,000 + stock taken over 5,000 − costs (60,000 + 4,000 + 6,000) = ₹25,000; A's 3/5 share = ₹15,000. A must get back his outlay ₹64,000 plus his profit ₹15,000 = ₹79,000. Forgetting the stock taken over gives profit ₹20,000 and ₹76,000; giving A only 2/5 gives ₹74,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-205","question":"Under a hire-purchase agreement, when does ownership of the asset normally pass to the hirer?","options":["When the last instalment is paid","When the agreement is signed","When the asset is delivered","When the down payment is made"],"answer":0,"explanation":"The hirer gets possession and use at once but remains a bailee; title passes only when all instalments have been paid (or the purchase option is exercised). That is the key difference from an instalment sale, where ownership passes immediately.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-206","question":"A machine with a cash price of ₹1,20,000 is bought on hire purchase: ₹20,700 down and three equal year-end instalments of ₹39,930. Interest is 10% a year on the outstanding cash price. How much interest is charged in year 2?","options":["₹9,930","₹3,630","₹6,830","₹6,930"],"answer":3,"explanation":"Opening balance 99,300. Year 1: interest 9,930, instalment 39,930 → balance 69,300. Year 2: interest 10% × 69,300 = ₹6,930 (year 3 is ₹3,630, which with 36,300 of principal exactly clears the last instalment). ₹6,830 just averages total interest of ₹20,490 over three years.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-207","question":"Same hire purchase: cash price ₹1,20,000, ₹20,700 down, instalments of ₹39,930 at each year end, 10% interest; the hirer depreciates the machine at 10% a year on the written-down value. The first instalment is paid, but the second is not, and the vendor repossesses the machine at the end of year 2. What loss does the hirer record on repossession?","options":["₹27,900","₹20,970","₹19,770","₹43,770"],"answer":1,"explanation":"Book value of the machine after two years = 1,20,000 × 0.9 × 0.9 = ₹97,200. Amount owed to the vendor = balance 69,300 + year-2 interest 6,930 = ₹76,230, which is cancelled by the repossession. Loss = 97,200 − 76,230 = ₹20,970. Leaving out year-2 interest gives ₹27,900; straight-line depreciation gives ₹19,770; ignoring depreciation gives ₹43,770.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-208","question":"Opening stock is 200 units at ₹50. Purchases are 300 units at ₹55 and then 400 units at ₹60. 650 units are sold during the period. What is the closing stock under FIFO (periodic)?","options":["₹15,000","₹14,028","₹12,750","₹13,750"],"answer":0,"explanation":"Closing stock is 900 − 650 = 250 units. Under FIFO the earliest units are sold first, so the closing 250 come from the latest purchase at ₹60 = ₹15,000. ₹14,028 is the periodic weighted average (50,500 ÷ 900 × 250); ₹12,750 values the stock from the oldest layers.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-209","question":"Opening stock 100 units at ₹40. 1 March: bought 300 at ₹48. 5 March: issued 200. 10 March: bought 200 at ₹52. 15 March: issued 250. What is the closing stock under the perpetual weighted-average method?","options":["₹7,350","₹7,200","₹7,800","₹7,500"],"answer":0,"explanation":"After 1 March: 400 units for ₹18,400 (average ₹46). Issue 200 → 200 left at ₹46 = ₹9,200. After 10 March: 400 units for ₹19,600 (average ₹49). Issue 250 → 150 left × ₹49 = ₹7,350. ₹7,200 uses one periodic average of ₹48; ₹7,800 is FIFO (150 × ₹52).","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-210","question":"Prices of a firm's inventory rose steadily through the year. How many of these statements are correct? (1) FIFO shows a higher closing stock than weighted average. (2) FIFO shows a lower cost of goods sold than weighted average. (3) Ind AS 2 allows LIFO if it is applied consistently. (4) Weighted average smooths out the effect of price changes on cost of goods sold.","options":["Two","Four","Three","One"],"answer":2,"explanation":"(1), (2) and (4) are correct: with rising prices FIFO leaves the newer, dearer units in stock and charges the older, cheaper units to cost of sales, while weighted average blends them. (3) is wrong: Ind AS 2 permits only FIFO and weighted average (or specific identification), not LIFO.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-211","question":"10,000 units are put into a process at a material cost of ₹1,50,000; conversion costs are ₹1,08,000. Normal loss is 10% of input and is sold as scrap at ₹6 a unit. Actual output is 8,800 units. What is the value of the abnormal loss transferred to the abnormal loss account?","options":["₹4,400","₹5,733","₹5,600","₹5,864"],"answer":2,"explanation":"Cost per unit of normal output = (2,58,000 − scrap 6,000) ÷ 9,000 = ₹28. Abnormal loss = 9,000 − 8,800 = 200 units × ₹28 = ₹5,600. ₹4,400 is the net charge to profit and loss after crediting scrap of ₹6 a unit; ₹5,733 ignores the scrap value; ₹5,864 divides by actual output.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-212","question":"Opening work-in-progress is 2,000 units, 40% complete as to conversion. 18,000 units are started. Closing work-in-progress is 3,000 units, 60% complete as to conversion. There are no losses. What are the equivalent units for conversion under the FIFO method?","options":["18,000","18,800","16,800","19,600"],"answer":0,"explanation":"Completed = 2,000 + 18,000 − 3,000 = 17,000, of which 15,000 were started and finished this period. FIFO counts only this period's work: finishing opening WIP 2,000 × 60% = 1,200 + 15,000 + closing 3,000 × 60% = 1,800 → 18,000. Weighted average would give 17,000 + 1,800 = 18,800; ignoring the work on opening WIP gives 16,800.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-213","question":"A joint cost of ₹3,00,000 produces 6,000 units of A and 4,000 units of B. B is sold at split-off for ₹45 a unit. A is processed further at a cost of ₹60,000 and sold for ₹80 a unit. How much joint cost is apportioned to A on the net realisable value method?","options":["₹2,18,182","₹1,80,000","₹1,50,000","₹2,10,000"],"answer":3,"explanation":"NRV of A = 6,000 × 80 − 60,000 = ₹4,20,000; B = 4,000 × 45 = ₹1,80,000. A's share = 3,00,000 × 4,20,000 ÷ 6,00,000 = ₹2,10,000. ₹2,18,182 uses A's final sales value without deducting further processing; ₹1,80,000 uses physical units.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-214","question":"Under activity-based costing, set-up costs of ₹2,40,000 are driven by 80 set-ups and inspection costs of ₹1,50,000 by 500 inspections. Product X (1,000 units) needs 30 set-ups and 100 inspections. What is X's overhead per unit under ABC?","options":["₹60","₹120","₹90","₹30"],"answer":1,"explanation":"Rates: ₹3,000 per set-up and ₹300 per inspection. X: 30 × 3,000 + 100 × 300 = ₹1,20,000 ÷ 1,000 units = ₹120. ₹90 and ₹30 pick up only one of the two pools.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-215","question":"In activity-based costing, which of these is a batch-level activity?","options":["Setting up a machine before each production run","Power consumed while the machine runs","Insurance of the factory building","Designing a new product"],"answer":0,"explanation":"Set-up cost is incurred once per batch, whatever the batch size. Machine power is unit-level (varies with each unit), factory insurance is facility-sustaining, and product design is product-sustaining.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-216","question":"A division earns ₹6,00,000 on investment of ₹40,00,000; the firm's cost of capital is 12%. The manager is offered a project needing ₹10,00,000 that will earn ₹1,40,000 a year. What happens to the division's ROI and residual income if the project is accepted?","options":["ROI rises to 15.4% and residual income rises by ₹20,000","ROI falls to 14.8% and residual income falls by ₹20,000","ROI is unchanged and residual income rises by ₹1,40,000","ROI falls to 14.8% while residual income rises by ₹20,000"],"answer":3,"explanation":"ROI moves from 15% to 7,40,000 ÷ 50,00,000 = 14.8%. Residual income moves from 6,00,000 − 4,80,000 = ₹1,20,000 to 7,40,000 − 6,00,000 = ₹1,40,000, a rise of ₹20,000. The project earns 14%, above the 12% cost of capital, so it adds value; a manager judged on ROI would wrongly reject it, the goal-congruence problem RI avoids.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-217","question":"In responsibility accounting, a segment whose manager is accountable for costs, revenues and the capital invested in it is called a:","options":["Cost centre","Investment centre","Revenue centre","Profit centre"],"answer":1,"explanation":"A cost centre answers for costs only, a revenue centre for revenue, a profit centre for both, and an investment centre additionally for the assets employed, so it is judged on ROI or residual income.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-218","question":"Division A makes a component with a variable cost of ₹60 and can sell all its output outside at ₹100; ₹5 a unit of selling costs is saved on internal transfers. A is working at full capacity. What is the minimum transfer price A should accept from Division B?","options":["₹100","₹60","₹95","₹65"],"answer":2,"explanation":"At full capacity, each unit transferred is a lost outside sale, so the minimum price = variable cost + lost contribution = market price less costs saved = 100 − 5 = ₹95. ₹60 would be right only with spare capacity.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-219","question":"The profit and loss account balance rose by ₹80,000 during the year after: transfer to general reserve ₹50,000; depreciation ₹40,000; goodwill written off ₹10,000; and a profit of ₹25,000 on sale of land credited to it. What are the funds from operations?","options":["₹2,05,000","₹1,05,000","₹1,55,000","₹1,15,000"],"answer":2,"explanation":"Start from the rise in retained profit and add back appropriations and non-fund charges, then remove non-operating gains: 80,000 + 50,000 + 40,000 + 10,000 − 25,000 = ₹1,55,000. Adding the land profit instead of deducting it gives ₹2,05,000; forgetting the reserve transfer gives ₹1,05,000; forgetting depreciation gives ₹1,15,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-220","question":"Current assets were ₹5,00,000 at the start and ₹6,20,000 at the end of the year; current liabilities were ₹2,40,000 and ₹3,10,000. What change in working capital appears in the schedule of changes in working capital?","options":["Increase of ₹1,20,000","Decrease of ₹50,000","Increase of ₹1,90,000","Increase of ₹50,000"],"answer":3,"explanation":"Working capital moved from 5,00,000 − 2,40,000 = ₹2,60,000 to 6,20,000 − 3,10,000 = ₹3,10,000, an increase of ₹50,000. ₹1,20,000 looks only at current assets and ignores the ₹70,000 rise in current liabilities.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-221","question":"A firm's super profit is expected to be ₹60,000 a year for the next 5 years. Using the annuity method with a 10% discount rate (5-year annuity factor 3.7908), what is goodwill?","options":["₹3,00,000","₹6,00,000","₹1,90,194","₹2,27,448"],"answer":3,"explanation":"Goodwill = present value of the super-profit stream = 60,000 × 3.7908 = ₹2,27,448. ₹3,00,000 is five years' purchase without discounting; ₹6,00,000 capitalises the super profit at 10% as if it were perpetual; ₹1,90,194 uses a 4-year factor (3.1699).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-222","question":"A company's assets total ₹50,00,000, including goodwill fairly valued at ₹4,00,000 and preliminary expenses not written off of ₹1,00,000. Outside liabilities are ₹12,00,000 and 10% preference share capital is ₹6,00,000. There are 2,00,000 equity shares. What is the intrinsic (net assets) value of an equity share?","options":["₹16.00","₹18.50","₹15.50","₹13.50"],"answer":2,"explanation":"Net assets for equity = 50,00,000 − preliminary expenses 1,00,000 (fictitious) − liabilities 12,00,000 − preference capital 6,00,000 = ₹31,00,000 ÷ 2,00,000 = ₹15.50. Keeping preliminary expenses gives ₹16; not deducting preference capital gives ₹18.50; also excluding the fairly valued goodwill gives ₹13.50.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-223","question":"A company with 1,00,000 fully paid equity shares of ₹100 expects profit after tax of ₹9,00,000 and transfers 20% of it to reserves, distributing the rest. The normal rate of dividend in the industry is 9%. What is the value of a share on the dividend-yield basis?","options":["₹80","₹100","₹72","₹64"],"answer":0,"explanation":"Dividend per share = 9,00,000 × 80% ÷ 1,00,000 = ₹7.20, a 7.2% rate on ₹100. Value = (7.2 ÷ 9) × 100 = ₹80. ₹100 uses the full 9% earnings rate and ignores the retention; ₹72 confuses the dividend with the value; ₹64 deducts the 20% retention twice.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-224","question":"T Ltd takes over S Ltd, which has 30,000 equity shares. For every 3 shares of S, T issues 2 equity shares of ₹10 each at ₹15, and it also pays ₹5 in cash for every share of S. What is the purchase consideration?","options":["₹3,50,000","₹4,50,000","₹3,00,000","₹8,25,000"],"answer":1,"explanation":"Shares issued = 30,000 × 2/3 = 20,000 × ₹15 = ₹3,00,000; cash = 30,000 × ₹5 = ₹1,50,000; total ₹4,50,000. Valuing the shares at par gives ₹3,50,000; leaving out the cash gives ₹3,00,000; inverting the ratio (3 for 2) gives ₹8,25,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-225","question":"How many of these statements about accounting for business combinations in India are correct? (1) Under Ind AS 103, a combination not under common control uses the acquisition method, with identifiable assets and liabilities at fair value. (2) Under Ind AS 103, a combination of entities under common control uses the pooling-of-interests method at carrying amounts. (3) Goodwill arising under Ind AS 103 is amortised over a maximum of ten years. (4) Under AS 14, the purchase method lets the transferee record assets either at their existing carrying amounts or at fair values.","options":["Two","Four","Three","One"],"answer":2,"explanation":"(1), (2) and (4) are correct. (3) is wrong: under Ind AS, goodwill is not amortised but tested for impairment at least annually.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-226","question":"Under Ind AS 116, how does a lessee normally account for a five-year lease of office space (not short-term, not low-value)?","options":["It charges the rent to profit and loss as an operating lease, with nothing on the balance sheet","It records the full building as its own fixed asset","It recognises a right-of-use asset and a lease liability","It discloses the lease only in the notes"],"answer":2,"explanation":"Ind AS 116 removed the operating/finance distinction for lessees. Apart from the short-term and low-value exemptions, every lease brings a right-of-use asset and a lease liability onto the balance sheet.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-227","question":"A lessee signs a 3-year lease with annual payments of ₹1,00,000 at each year end. The discount rate is 10% (3-year annuity factor 2.4869) and the lessee pays initial direct costs of ₹5,000. What is the right-of-use asset at commencement under Ind AS 116?","options":["₹2,48,690","₹3,05,000","₹2,53,690","₹3,00,000"],"answer":2,"explanation":"Lease liability = PV of payments = 1,00,000 × 2.4869 = ₹2,48,690. The right-of-use asset = lease liability + initial direct costs = ₹2,53,690. ₹2,48,690 forgets the direct costs; ₹3,05,000 uses undiscounted payments.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-228","question":"Same lease: payments of ₹1,00,000 at each year end for 3 years, 10% rate, lease liability ₹2,48,690 and right-of-use asset ₹2,53,690, depreciated straight-line over the lease term. What total expense does the lessee recognise in profit and loss in year 1?","options":["₹1,00,000","₹1,07,766","₹99,432","₹1,09,432"],"answer":3,"explanation":"Depreciation = 2,53,690 ÷ 3 = ₹84,563; interest = 10% × 2,48,690 = ₹24,869 (on the opening liability, since payment is at year end); total ₹1,09,432. ₹1,00,000 is the old operating-lease rent; ₹1,07,766 depreciates only the lease liability; ₹99,432 computes interest after deducting the year-end payment.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-229","question":"A lease liability of ₹2,48,690 is recognised at 10%. The first annual payment of ₹1,00,000 is made at the end of year 1. What is the lease liability at the end of year 1?","options":["₹1,48,690","₹1,73,559","₹1,65,793","₹2,73,559"],"answer":1,"explanation":"Closing liability = opening + interest − payment = 2,48,690 + 24,869 − 1,00,000 = ₹1,73,559. ₹1,48,690 forgets the interest; ₹1,65,793 simply takes two-thirds of the opening amount; ₹2,73,559 forgets the payment.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-230","question":"A head office invoices goods to its branch at cost plus 25%. Branch opening stock is ₹50,000 and closing stock ₹75,000 (both at invoice price); goods sent during the year are ₹5,00,000 at invoice price. All goods are sold at invoice price. What is the branch's true gross profit?","options":["₹1,00,000","₹95,000","₹1,18,750","₹75,000"],"answer":1,"explanation":"Goods sold at invoice price = 50,000 + 5,00,000 − 75,000 = ₹4,75,000. Loading included = 25/125 = 20% of invoice price, so true profit = 4,75,000 × 20% = ₹95,000. ₹1,00,000 is the loading on goods sent, not sold; ₹1,18,750 takes 25% of the invoice price.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-231","question":"Goods are invoiced to a branch at cost plus 33⅓%. The branch's closing stock is ₹48,000 at invoice price. How much stock reserve must be created to remove the unrealised profit?","options":["₹16,000","₹12,000","₹36,000","₹9,600"],"answer":1,"explanation":"A mark-up of one-third on cost equals one-quarter of the invoice price: 48,000 × 1/4 = ₹12,000 (cost is ₹36,000). ₹16,000 wrongly applies 33⅓% to the invoice price.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-232","question":"A lease of a mine gives the landlord a royalty of ₹5 a tonne with a minimum rent of ₹50,000 a year. Short workings can be recouped from excess royalty in the next two years only. Output is 6,000 tonnes in year 1, 9,000 in year 2 and 14,000 in year 3. Short workings are recouped in the order they arose. How much is paid to the landlord in year 3?","options":["₹50,000","₹45,000","₹70,000","₹65,000"],"answer":0,"explanation":"Year 1: royalty 30,000, pay 50,000, short working 20,000. Year 2: royalty 45,000, pay 50,000, short working 5,000 (no excess to recoup year 1's). Year 3: royalty 70,000, excess over minimum 20,000, which recoups year 1's 20,000 (its last chance); year 2's 5,000 waits for year 4. Payment = 70,000 − 20,000 = ₹50,000. ₹45,000 recoups 25,000, more than the excess allows.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-233","question":"Stock on 1 April was ₹80,000; purchases to the date of a fire were ₹4,00,000 and sales ₹5,00,000. Gross profit is 25% of sales. Salvage is worth ₹15,000. The stock is insured for ₹70,000 under a policy with an average clause. What is the claim?","options":["₹60,000","₹70,000","₹90,000","₹56,875"],"answer":0,"explanation":"Cost of sales = 5,00,000 × 75% = 3,75,000, so stock at the fire = 80,000 + 4,00,000 − 3,75,000 = ₹1,05,000. Loss = 1,05,000 − 15,000 = ₹90,000. Under-insured, so claim = 90,000 × 70,000 ÷ 1,05,000 = ₹60,000. ₹56,875 treats the 25% as a mark-up on cost; ₹70,000 and ₹90,000 ignore the average clause.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-234","question":"The standard time for a job is 10 hours and the worker finishes it in 8 hours. The hourly rate is ₹60. What does the worker earn under the Rowan premium plan?","options":["₹540","₹600","₹576","₹480"],"answer":2,"explanation":"Rowan bonus = (time saved ÷ standard time) × time taken × rate = (2 ÷ 10) × 8 × 60 = ₹96, so earnings = 480 + 96 = ₹576. ₹540 is the Halsey 50% plan (480 + 50% × 2 × 60); ₹600 pays the whole time saved.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-235","question":"The standard time for a job is 12 hours. At what actual time taken does a worker earn the same bonus under the Halsey plan (50% of time saved) and the Rowan plan?","options":["8 hours","6 hours","9 hours","4 hours"],"answer":1,"explanation":"Halsey bonus = 0.5 × (S − T) × R; Rowan bonus = (S − T) ÷ S × T × R. They are equal when T ÷ S = 0.5, i.e. T = 6 hours. Taking less time than this, Halsey pays more; taking more, Rowan pays more.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-236","question":"A product's annual demand is 30,000 units. Each production run costs ₹1,200 to set up, and holding one unit for a year costs ₹2. What is the economic batch quantity?","options":["6,000 units","4,243 units","8,485 units","3,000 units"],"answer":0,"explanation":"EBQ = √(2 × annual demand × set-up cost ÷ carrying cost per unit) = √(2 × 30,000 × 1,200 ÷ 2) = √3,60,00,000 = 6,000 units. Dropping the 2 gives 4,243; doubling inside the root wrongly gives 8,485.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-237","question":"A 40-seat bus makes 2 round trips a day on a route 25 km long (one way), 25 days a month, with average occupancy of 80%. How many passenger-kilometres does it run in a month?","options":["40,000","80,000","1,00,000","1,60,000"],"answer":1,"explanation":"Each round trip is 2 × 25 = 50 km, so 100 km a day and 2,500 km a month. Passengers carried on average = 40 × 80% = 32. Passenger-km = 32 × 2,500 = 80,000. 40,000 counts only one direction; 1,00,000 assumes full occupancy.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-238","question":"Service department S1 has costs of ₹27,000 and S2 ₹18,000 before inter-service charges. S1 gives 20% of its services to S2; S2 gives 50% of its services to S1; the rest go to production departments. Using simultaneous equations, what is S1's total cost to be distributed?","options":["₹40,000","₹36,000","₹27,000","₹45,000"],"answer":0,"explanation":"S1 = 27,000 + 0.5 S2 and S2 = 18,000 + 0.2 S1. Substituting: S1 = 27,000 + 9,000 + 0.1 S1, so 0.9 S1 = 36,000 and S1 = ₹40,000 (S2 = ₹26,000). ₹36,000 stops after one round of transfers; ₹45,000 adds all of S2's cost.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-239","question":"Profit as per cost accounts is ₹2,50,000. Overheads under-absorbed in the cost accounts are ₹15,000; interest received of ₹8,000 appears only in the financial accounts; depreciation is ₹40,000 in the financial accounts but ₹35,000 in the cost accounts; and closing stock is valued at ₹1,20,000 in the cost accounts but ₹1,10,000 in the financial accounts (opening stock is the same in both). What is the profit as per financial accounts?","options":["₹2,28,000","₹2,48,000","₹2,58,000","₹2,38,000"],"answer":0,"explanation":"Start with ₹2,50,000; deduct under-absorbed overheads 15,000 (an extra charge in the financial books); add interest 8,000; deduct the extra depreciation 5,000; deduct 10,000 because the lower closing stock in the financial books lowers profit: ₹2,28,000. Reversing the stock adjustment gives ₹2,48,000; ignoring it gives ₹2,38,000.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-240","question":"A club received subscriptions of ₹1,80,000 in cash during the year. This includes ₹10,000 for the previous year and ₹6,000 for the next year. Subscriptions of ₹14,000 for the current year are still outstanding, and ₹4,000 for the current year had been received in advance last year. What is subscription income for the year?","options":["₹1,82,000","₹1,80,000","₹1,78,000","₹1,88,000"],"answer":0,"explanation":"Income = 1,80,000 − 10,000 (last year) − 6,000 (next year) + 14,000 (outstanding) + 4,000 (received last year for this year) = ₹1,82,000. Forgetting last year's advance gives ₹1,78,000; treating this year's advance as income gives ₹1,88,000.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-241","question":"A draws a bill of ₹50,000 on B and discounts it with his bank. On maturity B dishonours it and the bank pays noting charges of ₹200. What entry does A pass?","options":["Bills Receivable A/c Dr ₹50,000 To B A/c ₹50,000","B A/c Dr ₹50,000 To Bills Receivable A/c ₹50,000","Bank A/c Dr ₹50,200 To B A/c ₹50,200","B A/c Dr ₹50,200 To Bank A/c ₹50,200"],"answer":3,"explanation":"The bank recovers the bill amount and noting charges from A, so A credits the bank and charges both to B, who is liable for them: B Dr ₹50,200, Bank Cr ₹50,200. Crediting Bills Receivable would be right only if A still held the bill.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-242","question":"On 1 September an investor buys 1,000 12% debentures of ₹100 each at ₹103 cum-interest. Interest is payable on 30 June and 31 December. At what cost are the debentures recorded in the investment account?","options":["₹1,03,000","₹97,000","₹1,01,000","₹1,05,000"],"answer":2,"explanation":"A cum-interest price includes interest accrued since the last payment date (1 July to 31 August, 2 months): 1,00,000 × 12% × 2/12 = ₹2,000. Cost = 1,03,000 − 2,000 = ₹1,01,000, and the ₹2,000 is a receivable recovered from the December interest. ₹97,000 deducts a full half-year's interest.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-243","question":"Under an internal reconstruction, 1,00,000 equity shares of ₹10 fully paid are reduced to ₹4 fully paid. The amount is used to write off a debit balance of ₹3,50,000 in the profit and loss account, goodwill of ₹1,50,000 and ₹80,000 of plant. What is transferred to capital reserve?","options":["₹1,00,000","₹2,50,000","₹20,000","₹1,70,000"],"answer":2,"explanation":"Capital reduction = 1,00,000 × (10 − 4) = ₹6,00,000. Used: 3,50,000 + 1,50,000 + 80,000 = ₹5,80,000. Balance ₹20,000 goes to capital reserve. ₹1,00,000 forgets the plant; ₹1,70,000 forgets the goodwill.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-244","question":"A firm expects a new product to sell at ₹500 and wants a profit margin of 20% on the selling price. Under target costing, what is the target cost?","options":["₹416.67","₹400","₹600","₹480"],"answer":1,"explanation":"Target cost = target price − required profit = 500 − 20% × 500 = ₹400. ₹416.67 treats the 20% as a mark-up on cost.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-245","question":"A contract priced at ₹50 lakh is accounted for over time using the cost-to-cost input method. Costs to date are ₹18 lakh and further costs to complete are estimated at ₹12 lakh. How much profit is recognised to date?","options":["₹20 lakh","₹30 lakh","₹12 lakh","₹8 lakh"],"answer":2,"explanation":"Progress = 18 ÷ 30 = 60%. Revenue to date = 60% × 50 = ₹30 lakh; profit = 30 − 18 = ₹12 lakh (60% of the expected ₹20 lakh). ₹30 lakh is the revenue, not the profit; ₹8 lakh applies the 40% still to be done.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-246","question":"A fixed-price contract for ₹40 lakh has incurred costs of ₹25 lakh and needs a further ₹20 lakh to complete. It is 25/45 complete. How much loss is recognised this year?","options":["₹5 lakh","₹2.78 lakh","Nil","₹25 lakh"],"answer":0,"explanation":"Total expected cost ₹45 lakh exceeds the price by ₹5 lakh, so the contract is onerous and the entire expected loss is recognised at once, not in proportion to progress. ₹2.78 lakh spreads the loss by completion (25/45).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-247","question":"Match each overhead with its usual basis of apportionment. (a) Factory rent (b) Canteen expenses (c) Power for machines (d) Insurance of stock. Bases: (1) Number of employees (2) Floor area (3) Value of stock (4) Horsepower × machine hours.","options":["a-2, b-4, c-1, d-3","a-3, b-1, c-4, d-2","a-1, b-2, c-3, d-4","a-2, b-1, c-4, d-3"],"answer":3,"explanation":"Rent follows the space occupied (floor area); canteen cost follows headcount; machine power follows rated horsepower times running hours; stock insurance follows the value of stock held.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-248","question":"Kaizen costing aims at:","options":["Setting a cost ceiling at the design stage from a target price","Charging overheads through activities","Small, continuous cost reductions during the production phase","Comparing actual costs with predetermined standards each month"],"answer":2,"explanation":"Kaizen costing seeks steady incremental savings once a product is in production. Fixing allowable cost at the design stage is target costing; overheads through activities is ABC; comparing against standards is standard costing.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-249","question":"A bottleneck machine has 10,000 hours a year and total factory costs (all costs other than materials) are ₹6,00,000. Product B sells at ₹165, uses ₹60 of materials and needs 1.5 bottleneck hours. What is B's throughput accounting ratio?","options":["1.00","1.17","1.75","0.86"],"answer":1,"explanation":"Throughput per bottleneck hour = (165 − 60) ÷ 1.5 = ₹70. Factory cost per bottleneck hour = 6,00,000 ÷ 10,000 = ₹60. TA ratio = 70 ÷ 60 = 1.17, so B covers its share of factory costs. 1.75 forgets to divide by the 1.5 hours; 0.86 inverts the ratio.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-250","question":"5,000 debentures of ₹100, redeemable at a 10% premium, are redeemed by converting them into equity shares of ₹10 each issued at ₹12.50. How many shares are issued?","options":["44,000","40,000","55,000","50,000"],"answer":0,"explanation":"Amount due = 5,000 × 110 = ₹5,50,000; shares = 5,50,000 ÷ 12.50 = 44,000. Ignoring the redemption premium gives 40,000; issuing at par gives 55,000.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-251","question":"In a consignment, the periodical statement showing the goods sold, the gross proceeds, the expenses incurred and the commission deducted is called the account sales. Who prepares it?","options":["The consignor, and sends it to the consignee","The carrier, on delivery of the goods","The buyer of the consigned goods","The consignee, and sends it to the consignor"],"answer":3,"explanation":"The consignee is the agent who sells the goods, so he reports the sales, his expenses and commission to the consignor in an account sales and remits the net balance.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-252","question":"In process costing, how is the cost of normal loss treated?","options":["It is charged to the costing profit and loss account","It is debited to an abnormal loss account","It is added to the value of scrap","It is absorbed by the good units produced"],"answer":3,"explanation":"Normal loss is an expected part of production, so its cost (less any scrap value) is spread over the good output, raising the cost per good unit. Only abnormal loss is taken out of the process and written off.","difficulty":"easy","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-253","question":"500 units costing ₹100 each are consigned, and the consignor pays ₹5,000 freight. 50 units are lost in transit through an accident, and the insurer admits a claim of ₹4,000. What net loss is charged to the consignor's profit and loss account?","options":["₹1,000","₹5,500","₹5,000","₹1,500"],"answer":3,"explanation":"Abnormal loss is valued at cost plus the proportionate freight: 50 × (100 + 5,000 ÷ 500) = ₹5,500. Net of the claim, 5,500 − 4,000 = ₹1,500 goes to profit and loss. ₹1,000 forgets the freight; ₹5,500 ignores the claim.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-254","question":"5,000 units enter a process at a total cost of ₹1,01,000. Normal loss is 10% of input and is sold as scrap at ₹4 a unit. Actual output is 4,700 units. What is the value of the abnormal gain debited to the process account?","options":["₹4,400","₹3,600","₹4,489","₹4,298"],"answer":0,"explanation":"Normal output = 4,500; cost per unit = (1,01,000 − scrap 2,000) ÷ 4,500 = ₹22. Abnormal gain = 4,700 − 4,500 = 200 units × 22 = ₹4,400. ₹3,600 is the net benefit after losing the scrap value of those 200 units; ₹4,489 ignores the scrap; ₹4,298 divides by actual output.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-255","question":"Opening WIP: 1,000 units (materials ₹12,000, 100% complete; conversion ₹5,000, 50% complete). Started 9,000 units; materials added ₹1,08,000, conversion ₹1,71,000. Closing WIP: 2,000 units, materials 100% and conversion 40% complete. No losses. Using the weighted-average method, what is the value of closing WIP?","options":["₹64,000","₹24,000","₹40,000","₹40,482"],"answer":2,"explanation":"Equivalent units: materials 8,000 + 2,000 = 10,000; conversion 8,000 + 800 = 8,800. Cost per EU: materials 1,20,000 ÷ 10,000 = ₹12; conversion 1,76,000 ÷ 8,800 = ₹20. Closing WIP = 2,000 × 12 + 800 × 20 = ₹40,000. ₹64,000 treats the WIP as fully converted; ₹40,482 is the FIFO answer.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-256","question":"How many of these statements about activity-based costing are correct? (1) It uses several cost pools, each with its own driver. (2) Compared with a single volume-based rate, it usually shifts overhead from low-volume, complex products to high-volume products. (3) Cost drivers are chosen because they cause the cost to be incurred. (4) Ind AS 2 requires inventory overheads to be absorbed using ABC.","options":["One","Two","Three","Four"],"answer":1,"explanation":"(1) and (3) are correct. (2) is reversed: volume-based rates over-cost high-volume products, so ABC usually moves overhead towards low-volume, complex products. (4) is wrong: Ind AS 2 requires a systematic allocation of production overheads on normal capacity but does not prescribe ABC.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-257","question":"Overheads of ₹4,40,000 consist of set-up costs ₹2,00,000 (40 set-ups) and machine costs ₹2,40,000 (20,000 machine hours). Product H: 10,000 units, 18,000 machine hours, 10 set-ups. Product L: 1,000 units, 2,000 machine hours, 30 set-ups. If ABC replaces a single machine-hour rate, what happens to H's overhead per unit?","options":["It falls by ₹13","It rises by ₹130","It rises by ₹13","No change, as total overhead is the same"],"answer":0,"explanation":"Single rate: 4,40,000 ÷ 20,000 = ₹22 an hour; H uses 1.8 hours a unit → ₹39.60. ABC: set-ups 10 × ₹5,000 = 50,000 plus machine 18,000 × ₹12 = 2,16,000 → 2,66,000 ÷ 10,000 = ₹26.60. H falls by ₹13; L rises from ₹44 to ₹174 (₹130), absorbing the set-up cost it causes.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-258","question":"The budget for 10,000 units allows variable cost of ₹50 a unit and fixed costs of ₹2,00,000. Actual output is 12,000 units and actual total cost ₹8,30,000. What is the total cost variance against the flexible budget?","options":["₹1,30,000 adverse","₹30,000 adverse","₹10,000 favourable","₹30,000 favourable"],"answer":1,"explanation":"Flexible budget for 12,000 units = 12,000 × 50 + 2,00,000 = ₹8,00,000; actual is ₹8,30,000, so ₹30,000 adverse. ₹1,30,000 compares with the original 10,000-unit budget; ₹10,000 favourable wrongly flexes the fixed costs too.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-259","question":"Under Ind AS 116, a lessee hires a car for 10 months with no purchase option. What may it do?","options":["It must recognise a right-of-use asset and lease liability, as there are no exemptions","Capitalise the car at its fair value as property, plant and equipment","Elect the short-term lease exemption and expense the payments, usually on a straight-line basis","Record nothing until the lease ends"],"answer":2,"explanation":"A lease of 12 months or less with no purchase option qualifies for the short-term exemption, so the lessee may simply expense the payments, normally straight-line over the term.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-260","question":"For a lessor, which of these indicate that a lease is a finance lease? (1) Ownership passes to the lessee at the end of the term. (2) The lease term covers the major part of the asset's economic life. (3) The present value of lease payments is substantially all of the asset's fair value. (4) The lessee can cancel at any time without penalty and the lessor bears gains and losses on the residual value.","options":["(1) and (2) only","(2), (3) and (4) only","All four","(1), (2) and (3) only"],"answer":3,"explanation":"A finance lease transfers substantially all the risks and rewards of ownership; (1), (2) and (3) are classic indicators. A lessee who can walk away freely while the lessor keeps the residual risk points to an operating lease.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-261","question":"Machinery at cost was ₹5,00,000 at the start and ₹6,50,000 at the end of the year; accumulated depreciation was ₹1,50,000 and ₹1,80,000. Depreciation for the year was ₹60,000. A machine costing ₹80,000 (accumulated depreciation ₹30,000) was sold for ₹40,000. How much machinery was bought?","options":["₹1,50,000","₹2,30,000","₹1,90,000","₹2,00,000"],"answer":1,"explanation":"Purchases = closing cost − opening cost + cost of the machine sold = 6,50,000 − 5,00,000 + 80,000 = ₹2,30,000. (Check: 1,50,000 + 60,000 − 30,000 = 1,80,000.) ₹1,50,000 ignores the sale; ₹1,90,000 adds the sale proceeds instead of the cost.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-262","question":"How many of these statements are correct? (1) A fund flow statement explains changes in working capital. (2) Buying inventory on credit changes neither working capital nor cash. (3) Collecting cash from debtors increases working capital. (4) Issuing shares for cash increases both working capital and cash.","options":["Two","Four","One","Three"],"answer":3,"explanation":"(1), (2) and (4) are correct. Credit purchases raise inventory and creditors equally, so working capital is unchanged, and no cash moves. (3) is wrong: collecting debtors swaps one current asset for another, so working capital is unchanged (though cash rises).","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-263","question":"A company's net assets available to equity are ₹60,00,000, and it has 40,000 equity shares of ₹100. Profit available to equity shareholders is ₹5,28,000, and the normal rate of return is 12%. What is the fair value of a share, taken as the average of the intrinsic value and the yield (earnings) value?","options":["₹150","₹130","₹110","₹260"],"answer":1,"explanation":"Intrinsic value = 60,00,000 ÷ 40,000 = ₹150. EPS = 5,28,000 ÷ 40,000 = ₹13.20, a 13.2% return on ₹100, so yield value = 13.2 ÷ 12 × 100 = ₹110. Fair value = (150 + 110) ÷ 2 = ₹130. ₹260 adds without averaging.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-264","question":"Under Ind AS 103, T acquires S by issuing shares worth ₹10,00,000. S's identifiable assets have a fair value of ₹11,00,000 and its liabilities ₹2,50,000; the book value of S's net assets is ₹7,00,000. What goodwill does T recognise?","options":["₹3,00,000","₹2,50,000","Nil","₹1,50,000"],"answer":3,"explanation":"Under the acquisition method goodwill = consideration − fair value of identifiable net assets = 10,00,000 − (11,00,000 − 2,50,000) = ₹1,50,000. Using book value gives ₹3,00,000, which wrongly lets the fair-value uplift sit in goodwill.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-265","question":"Under AS 14, an amalgamation in the nature of merger is accounted for by the pooling-of-interests method. S has share capital of ₹5,00,000 and a general reserve of ₹2,00,000. T issues shares with a face value of ₹6,00,000 as the purchase consideration. How does T record S's general reserve?","options":["At ₹1,00,000, after adjusting the ₹1,00,000 excess of share capital issued","At ₹2,00,000, with goodwill of ₹1,00,000","At ₹3,00,000","At ₹2,00,000, with a capital reserve of ₹1,00,000"],"answer":0,"explanation":"Under pooling, reserves are carried over, and the difference between share capital issued (₹6,00,000) and the transferor's share capital (₹5,00,000) is adjusted in reserves. The ₹1,00,000 excess reduces the reserve to ₹1,00,000; no goodwill arises.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-266","question":"A hirer records a hire-purchase asset under the full cash price method. On what amount is depreciation charged?","options":["The full cash price of the asset","The total hire-purchase price including interest","Only the instalments paid to date","The cash price less the down payment"],"answer":0,"explanation":"The asset is recorded at its full cash price on day one, and depreciation is based on that amount. Interest is a finance cost charged to profit and loss, not part of the asset's cost.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-267","question":"1,000 finished units cost ₹200 each; they are expected to sell at ₹220 with selling costs of ₹30 a unit. Raw material of 500 kg held for making more of the same product cost ₹80 a kg; its replacement cost is now ₹70 a kg. What is the total inventory value under Ind AS 2?","options":["₹2,40,000","₹2,30,000","₹2,25,000","₹2,35,000"],"answer":2,"explanation":"Finished goods: NRV = 220 − 30 = ₹190 < cost, so ₹1,90,000. Because the finished product will sell below cost, the raw material is written down too, and replacement cost is a good measure of its NRV: 500 × 70 = ₹35,000. Total ₹2,25,000. ₹2,30,000 keeps the material at cost, which is allowed only if the finished goods sell at or above cost.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-268","question":"Budgeted fixed overhead is ₹2,00,000 for 10,000 hours (₹20 an hour), with a standard of 2 hours a unit. Actual hours worked are 9,500 and actual output 4,600 units. What is the fixed overhead capacity variance?","options":["₹6,000 (A)","₹16,000 (A)","₹10,000 (F)","₹10,000 (A)"],"answer":3,"explanation":"Capacity variance = (actual hours − budgeted hours) × rate = (9,500 − 10,000) × 20 = ₹10,000 adverse. Efficiency variance = (standard hours 9,200 − actual 9,500) × 20 = ₹6,000 adverse; together they make the ₹16,000 adverse volume variance.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-269","question":"A firm's fixed costs are ₹3,00,000 a year, of which ₹1,80,000 would continue even if the plant were shut down temporarily. Contribution is ₹15 a unit. What is the shutdown point?","options":["20,000 units","12,000 units","8,000 units","10,000 units"],"answer":2,"explanation":"Shutting down saves only the avoidable fixed costs of ₹1,20,000. The plant should keep running as long as contribution covers them: 1,20,000 ÷ 15 = 8,000 units. 20,000 is the break-even point; 12,000 divides the unavoidable costs.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-270","question":"A company sells 10,000 units with a one-year warranty. Past experience shows 5% of units need minor repairs costing ₹200 each and 1% need major repairs costing ₹1,000 each. What warranty provision does Ind AS 37 require?","options":["₹1,00,000","₹2,00,000","₹1,20,000","₹7,20,000"],"answer":1,"explanation":"For a large population, the provision is the expected value: 10,000 × (5% × 200 + 1% × 1,000) = 10,000 × ₹20 = ₹2,00,000. ₹1,00,000 ignores major repairs; ₹1,20,000 prices all 6% at ₹200; ₹7,20,000 charges both repair costs to all 6%.","difficulty":"hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-271","question":"A company's profit for the year is ₹24,00,000. It had 2,00,000 equity shares at the start of the year and made a 1-for-4 bonus issue on 1 October. What is basic EPS for the year?","options":["₹10.67","₹12.00","₹9.60","₹11.00"],"answer":2,"explanation":"A bonus issue brings in no resources, so the new shares are treated as outstanding from the start of the year (and comparatives are restated): 2,50,000 shares; EPS = 24,00,000 ÷ 2,50,000 = ₹9.60. ₹10.67 time-weights the bonus shares (2,25,000) as if they were issued for cash; ₹12.00 ignores the bonus issue.","difficulty":"very-hard","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-272","question":"When valuing a consignee's unsold stock, which expense is NOT added to the cost of the goods?","options":["Freight to the consignee's town","Rent of the consignee's godown","Insurance in transit","Unloading charges at the consignee's town"],"answer":1,"explanation":"Only expenses that bring the goods to the place of sale (freight, transit insurance, unloading and the like) are added. Godown rent is a recurring expense of holding and selling the goods, so it is charged to the period.","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-273","question":"A and B open a joint bank account for a venture, A paying in ₹50,000 and B ₹30,000. Venture profit is ₹20,000, shared equally. After everything else is settled, the bank balance is distributed. How much does A receive?","options":["₹62,500","₹50,000","₹70,000","₹60,000"],"answer":3,"explanation":"A gets back his contribution of ₹50,000 plus half the profit (₹10,000) = ₹60,000; B gets ₹40,000, which together equal the ₹1,00,000 balance. ₹62,500 wrongly shares profit in the ratio of contributions (5 : 3).","difficulty":"moderate","source":"Big 4 · Bank MT · MBA placement pattern"},
  {"id":"mgmt-accounting-274","question":"An asset costing ₹5,50,000 with a residual value of ₹50,000 and a useful life of 4 years is depreciated by the sum-of-the-years'-digits method. What is its book value at the end of year 2?","options":["₹1,65,000","₹2,00,000","₹3,00,000","₹4,00,000"],"answer":1,"explanation":"SYD = 10; years 1-2 charge (4 + 3)/10 of the depreciable ₹5,00,000 = ₹3,50,000, leaving ₹2,00,000. ₹1,65,000 forgets to deduct residual value; ₹4,00,000 applies the fractions in reverse (1 + 2).","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-275","question":"A machine costing ₹8,00,000 (life 5 years, residual ₹80,000) is depreciated by the double-declining-balance method. What is the depreciation for year 3?","options":["₹1,02,400","₹1,03,680","₹1,72,800","₹1,15,200"],"answer":3,"explanation":"DDB rate = 2 × 20% = 40% on opening book value, ignoring residual value: 8,00,000 → 4,80,000 → 2,88,000, so year 3 = 40% × 2,88,000 = ₹1,15,200. ₹1,03,680 wrongly applies the rate to cost less residual; ₹1,02,400 uses 20% WDV.","difficulty":"hard","source":"Big 4 · Bank MT"},
  {"id":"mgmt-accounting-276","question":"A machine bought on 1 April 2020 for ₹12,00,000 is depreciated straight-line over 10 years with nil residual value. On 1 April 2023 an upgrade costing ₹1,20,000 is capitalised, the remaining life is revised to 6 years and the residual value to ₹60,000. What is the depreciation for 2023-24?","options":["₹1,50,000","₹1,60,000","₹1,40,000","₹1,30,000"],"answer":0,"explanation":"A change in estimate is prospective: carrying amount 12,00,000 − 3,60,000 + 1,20,000 = ₹9,60,000; (9,60,000 − 60,000) ÷ 6 = ₹1,50,000. ₹1,60,000 ignores the residual value and ₹1,30,000 leaves out the upgrade.","difficulty":"hard","source":"CA Inter level · Big 4"},
  {"id":"mgmt-accounting-277","question":"Machine A was bought on 1 April 2021 for ₹4,00,000 and is depreciated at 20% a year on the written-down value (year ends 31 March, depreciation for part years on a time basis). It is sold on 31 December 2023 for ₹2,30,000. What is the profit or loss on sale?","options":["Loss ₹26,000","Profit ₹12,400","Profit ₹25,200","Profit ₹50,000"],"answer":1,"explanation":"WDV on 1 April 2023 = 4,00,000 × 0.8 × 0.8 = ₹2,56,000; 9 months' depreciation = ₹38,400, so book value ₹2,17,600 and profit ₹12,400. The loss of ₹26,000 skips the current-year charge; ₹25,200 charges a full year.","difficulty":"very-hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-278","question":"A trial balance difference was put to a suspense account. The errors found were: (a) a sales return of ₹3,500 from Mohan was credited to his account as ₹5,300; (b) a credit purchase of ₹8,000 from Ravi was entered in the sales book and posted from there; (c) discount allowed of ₹600 was debited to Discount Received account; (d) the purchase book was overcast by ₹1,000. What was the original balance of the suspense account?","options":["₹800 credit","₹2,800 debit","₹800 debit","₹1,800 debit"],"answer":2,"explanation":"Only one-sided errors touch suspense: (a) extra credit of ₹1,800 needs a ₹1,800 debit in suspense; (d) extra debit of ₹1,000 needs a ₹1,000 credit. Net ₹800 debit. Errors (b) and (c) are two-sided errors of commission/principle and leave the trial balance agreeing.","difficulty":"very-hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-279","question":"Opening stock 200 units at ₹30. 5 Jan: bought 300 at ₹35. 10 Jan: issued 400. 20 Jan: bought 400 at ₹40. 25 Jan: issued 300. What is the closing stock under the perpetual weighted-average method?","options":["₹7,222","₹8,000","₹7,000","₹7,720"],"answer":3,"explanation":"Average after 5 Jan = 16,500/500 = ₹33; 100 units left = ₹3,300. Add 400 at ₹40 → 500 units for ₹19,300 = ₹38.60; 200 units left = ₹7,720. ₹7,222 is the periodic average (32,500/900), ₹8,000 FIFO and ₹7,000 perpetual LIFO.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-280","question":"Under Ind AS 2, fixed production overhead of ₹6,00,000 is allocated on a normal capacity of 20,000 units. Actual production is 15,000 units (variable cost ₹50 a unit) and 3,000 units remain unsold at year end. At what cost is closing inventory carried?","options":["₹2,40,000","₹2,70,000","₹1,50,000","₹3,00,000"],"answer":0,"explanation":"Fixed overhead is absorbed at the normal-capacity rate of ₹30 a unit, so 3,000 × (50 + 30) = ₹2,40,000; the unabsorbed ₹1,50,000 is expensed. ₹2,70,000 wrongly spreads overhead over actual output (₹40); ₹1,50,000 is marginal costing, not allowed under Ind AS 2.","difficulty":"very-hard","source":"CA Inter level · Big 4"},
  {"id":"mgmt-accounting-281","question":"The cash book shows a debit balance of ₹62,400. Bank charges ₹350 and interest credited ₹1,200 are not in the cash book; a cheque of ₹4,800 deposited was dishonoured but not recorded; a customer paid ₹7,000 directly into the bank; a cheque issued for ₹3,600 was recorded as ₹6,300; cheques issued ₹9,000 are unpresented and cheques deposited ₹5,500 are uncleared. What is the pass-book balance?","options":["₹68,150","₹71,650","₹66,250","₹76,450"],"answer":1,"explanation":"Amended cash book = 62,400 − 350 + 1,200 − 4,800 + 7,000 + 2,700 = ₹68,150; then add unpresented ₹9,000 and deduct uncleared ₹5,500 = ₹71,650. ₹66,250 reverses the transposition correction; ₹68,150 stops at the amended cash book.","difficulty":"very-hard","source":"Bank MT · IBPS SO"},
  {"id":"mgmt-accounting-282","question":"Under Ind AS 115, a retailer sells goods for ₹5,00,000 and grants 50,000 loyalty points, each redeemable for ₹1 off future purchases; it expects 80% of points to be redeemed. The goods' stand-alone selling price is ₹5,00,000. How much of the price is deferred as a contract liability for the points?","options":["₹40,000","₹50,000","₹37,037","₹46,296"],"answer":2,"explanation":"Points' stand-alone price = 50,000 × 80% × ₹1 = ₹40,000; allocate 5,00,000 × 40,000/5,40,000 = ₹37,037. ₹40,000 ignores relative allocation, and ₹46,296 uses the face value of all points.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-283","question":"A retailer deferred ₹37,037 for loyalty points under Ind AS 115, expecting 40,000 points to be redeemed in total. By year end 24,000 points have been redeemed and the expectation is unchanged. How much revenue from the points is recognised in the year?","options":["₹24,000","₹17,778","₹37,037","₹22,222"],"answer":3,"explanation":"Revenue = 37,037 × 24,000/40,000 (points redeemed over points expected to be redeemed) = ₹22,222. ₹17,778 divides by all 50,000 points issued; ₹24,000 uses face value instead of the allocated amount.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-284","question":"A firm has contracted to supply 1,000 units at ₹100 each. Rising input prices mean each unit will now cost ₹130 to make; cancelling the contract carries a penalty of ₹25,000. Under Ind AS 37, what provision is needed?","options":["₹25,000","₹30,000","₹55,000","₹1,30,000"],"answer":0,"explanation":"An onerous contract is provided for at the unavoidable cost: the lower of the net cost of fulfilling it (₹30,000 loss) and the penalty for exiting (₹25,000). Adding both (₹55,000) or providing the full fulfilment cost is wrong.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-285","question":"A machine costs ₹10,00,000. Book depreciation is 10% straight-line; tax depreciation is 25% on the written-down value; the tax rate is 30%. What deferred tax is charged to profit and loss in year 2?","options":["₹45,000","₹26,250","₹71,250","₹56,250"],"answer":1,"explanation":"Year-2 extra timing difference = tax depreciation 1,87,500 − book 1,00,000 = 87,500; × 30% = ₹26,250 (DTL rises from ₹45,000 to ₹71,250). ₹71,250 is the closing liability, not the year's charge; ₹56,250 applies the rate to the whole tax depreciation.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-286","question":"A company issues ₹10,00,000 of 8% bonds (annual coupon, redeemable at par in 3 years) at 95%, paying transaction costs of ₹10,000. The effective interest rate is 10.43%. What is the amortised-cost carrying amount of the liability at the end of year 1?","options":["₹9,40,000","₹9,69,085","₹9,58,042","₹10,38,042"],"answer":2,"explanation":"Initial measurement is net proceeds: 9,50,000 − 10,000 = ₹9,40,000. Interest at EIR 98,042 less coupon 80,000 gives ₹9,58,042. ₹9,69,085 ignores the transaction costs; ₹10,38,042 forgets to deduct the coupon paid.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-287","question":"A cash-generating unit carries goodwill ₹1,00,000, plant ₹6,00,000 and an intangible ₹3,00,000 (no item has a determinable recoverable amount). The unit's recoverable amount is ₹7,50,000. Under Ind AS 36, what is the plant's carrying amount after impairment?","options":["₹4,50,000","₹4,33,333","₹5,25,000","₹5,00,000"],"answer":3,"explanation":"Loss = 10,00,000 − 7,50,000 = ₹2,50,000: first ₹1,00,000 to goodwill, then ₹1,50,000 pro rata to plant and intangible (6 : 3), so plant bears ₹1,00,000 → ₹5,00,000. ₹4,50,000 spreads the loss over all assets including goodwill.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-288","question":"A company had 10,00,000 shares and made a 1-for-4 rights issue at ₹50 on 1 October (year ends 31 March); the fair value just before the rights was ₹100. Profit is ₹1,50,00,000. What is basic EPS under Ind AS 33?","options":["₹12.71","₹13.33","₹12.00","₹15.00"],"answer":0,"explanation":"TERP = (4 × 100 + 50)/5 = ₹90, so the bonus factor is 100/90. Weighted shares = 10,00,000 × 100/90 × 6/12 + 12,50,000 × 6/12 = 11,80,556; EPS = ₹12.71. ₹13.33 time-weights without the bonus element.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-289","question":"A, B and C (profit ratio 3 : 1 : 1; fixed capitals before dissolution A ₹80,000, B ₹40,000) dissolve the firm. After the realisation loss, A's capital shows ₹50,000 credit, B's ₹30,000 credit and C's ₹12,000 debit. C is insolvent and pays only ₹3,000. Under Garner v. Murray, how much does B finally receive?","options":["₹25,500","₹27,000","₹27,750","₹26,000"],"answer":1,"explanation":"C's deficiency is ₹9,000, borne by solvent partners in their pre-dissolution capital ratio 80 : 40, not the profit ratio: B bears ₹3,000 and gets ₹27,000. ₹27,750 uses the 3 : 1 profit ratio; ₹26,000 ignores C's ₹3,000 payment.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-290","question":"A, B and C share profits 3 : 2 : 1 with capitals of ₹1,00,000, ₹40,000 and ₹30,000. Under piecemeal distribution by the surplus-capital method, how is the first ₹30,000 available to partners (after outside liabilities) shared?","options":["A ₹15,000, B ₹10,000, C ₹5,000","A ₹30,000 only","A ₹25,000, C ₹5,000","A ₹22,500, C ₹7,500"],"answer":2,"explanation":"Capital per unit of profit share: A 33,333, B 20,000, C 30,000. Surplus over B's base: A ₹40,000, C ₹10,000; over C's base A has a further ₹10,000. So the first ₹10,000 goes to A, then A and C share 3 : 1, giving A ₹25,000 and C ₹5,000.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-291","question":"A partner withdraws ₹10,000 on 1 June, ₹15,000 on 1 October, ₹8,000 on 1 January and ₹12,000 on 1 March. The year ends on 31 March and interest on drawings is 9% a year. What is the interest on drawings?","options":["₹2,032.50","₹4,050","₹2,025","₹1,695"],"answer":3,"explanation":"Product method: months to year end are 10, 6, 3 and 1, so products = 1,00,000 + 90,000 + 24,000 + 12,000 = 2,26,000; × 9%/12 = ₹1,695. ₹2,032.50 counts one extra month each; ₹2,025 assumes average 6 months.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-292","question":"After the accounts were closed, it was found that interest on capital at 10% was omitted. Capitals were A ₹3,00,000, B ₹2,00,000, C ₹1,00,000 and the profit ratio is 2 : 2 : 1. What single adjusting entry is passed?","options":["Dr B ₹4,000, Dr C ₹2,000; Cr A ₹6,000","Dr A ₹6,000; Cr B ₹4,000, Cr C ₹2,000","Dr C ₹2,000; Cr A ₹1,000, Cr B ₹1,000","Dr A ₹24,000, B ₹24,000, C ₹12,000; Cr capitals ₹60,000"],"answer":0,"explanation":"Interest due: A 30,000, B 20,000, C 10,000; recovering ₹60,000 of profit at 2 : 2 : 1 takes 24,000, 24,000, 12,000. Net: A gains ₹6,000, B loses ₹4,000, C loses ₹2,000.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-293","question":"A company has equity capital ₹50,00,000 (shares of ₹10), securities premium ₹10,00,000, general reserve ₹30,00,000, P&L surplus ₹10,00,000 and loans of ₹1,60,00,000. It wants to buy back shares at ₹30 under section 68 (special resolution). What is the maximum number of shares it can buy back?","options":["83,333","1,25,000","66,666","1,00,000"],"answer":2,"explanation":"Share test: 25% of 5,00,000 = 1,25,000. Resources test: 25% of ₹1 crore = ₹25 lakh → 83,333. Debt-equity test: post-buyback funds must be ≥ 1,60,00,000/2, so outflow ≤ ₹20 lakh → 66,666 shares. The lowest governs.","difficulty":"very-hard","source":"CA Inter level · Big 4"},
  {"id":"mgmt-accounting-294","question":"On 1 August a company buys 1,000 of its own 12% debentures of ₹100 (interest due 31 March and 30 September) at ₹98 cum-interest and cancels them. What is the profit on cancellation?","options":["₹2,000","₹4,000","₹10,000","₹6,000"],"answer":3,"explanation":"Cum-interest price ₹98,000 includes 4 months' accrued interest of ₹4,000, so the ex-interest cost is ₹94,000 against a face value of ₹1,00,000: profit ₹6,000. ₹2,000 treats the whole ₹98,000 as capital.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-295","question":"Under Ind AS 102, 100 employees each get 100 share options vesting after 3 years of service; grant-date fair value is ₹30 an option. At the end of year 1 the company expects 10% of employees to leave; at the end of year 2 it revises this to 15%. What is the expense for year 2?","options":["₹80,000","₹85,000","₹1,70,000","₹90,000"],"answer":0,"explanation":"Cumulative to year 2 = 10,000 × 85% × 30 × 2/3 = ₹1,70,000; less year 1's 10,000 × 90% × 30 × 1/3 = ₹90,000 gives ₹80,000. ₹85,000 simply divides the revised total by 3, ignoring the catch-up.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-296","question":"H buys 80% of S on 1 April for ₹10,00,000, when S has share capital ₹6,00,000 and reserves ₹4,00,000 (fair value = book value). NCI is measured at its proportionate share of net assets. S earns ₹2,00,000 in the year. What are goodwill and NCI at year end?","options":["Goodwill ₹2,00,000; NCI ₹2,00,000","Goodwill ₹2,00,000; NCI ₹2,40,000","Goodwill ₹40,000; NCI ₹2,40,000","Goodwill ₹0; NCI ₹2,40,000"],"answer":1,"explanation":"Goodwill uses net assets at acquisition: 10,00,000 − 80% × 10,00,000 = ₹2,00,000. NCI at year end = 20% × (10,00,000 + 2,00,000) = ₹2,40,000, so it picks up its share of post-acquisition profit.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-297","question":"A parent sells goods for ₹2,40,000 to its 75%-owned subsidiary at cost plus 20%; half the goods remain in the subsidiary's stock at year end. By how much is consolidated inventory reduced?","options":["₹24,000","₹15,000","₹20,000","₹40,000"],"answer":2,"explanation":"Unsold goods ₹1,20,000 contain profit of 1,20,000 × 20/120 = ₹20,000, eliminated in full from inventory whatever the holding percentage. ₹24,000 takes 20% of the selling price; ₹15,000 eliminates only 75%.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-298","question":"A registered dealer buys goods intra-state for ₹2,00,000 plus CGST 9% and SGST 9%, and sells goods inter-state for ₹3,00,000 plus IGST 18%. After using input tax credit, how much IGST must be paid in cash?","options":["₹54,000","₹36,000","₹9,000","₹18,000"],"answer":3,"explanation":"Output IGST = ₹54,000. Both CGST credit (₹18,000) and SGST credit (₹18,000) can be set off against IGST, leaving ₹18,000 payable. ₹54,000 wrongly assumes intra-state credits cannot be used.","difficulty":"moderate","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-299","question":"Sales are ₹12,00,000, gross profit is 20% of sales and inventory turnover is 6 times on cost of goods sold. Closing stock is ₹20,000 more than opening stock. What is the closing stock?","options":["₹1,70,000","₹1,50,000","₹2,10,000","₹1,60,000"],"answer":0,"explanation":"COGS = 9,60,000; average stock = 9,60,000/6 = 1,60,000, so opening + closing = 3,20,000 and closing = (3,20,000 + 20,000)/2 = ₹1,70,000. ₹2,10,000 wrongly uses sales for turnover.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-300","question":"In 2024-25 a company finds that depreciation for 2022-23 was understated by a material amount. Its 2024-25 statements show comparatives for 2023-24. How does Ind AS 8 require the error to be corrected?","options":["Charge it in the 2024-25 profit and loss as a prior-period item","Restate the opening balances of assets, liabilities and equity at 1 April 2023","Treat it prospectively as a change in accounting estimate","Withdraw and reissue the 2022-23 statements only"],"answer":1,"explanation":"Material prior-period errors are corrected retrospectively: comparatives are restated and, since the error is before the earliest period presented, the opening balances of that period (1 April 2023) are restated. Charging the current P&L is the old AS 5 approach.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-301","question":"Using the retail inventory method, goods available for sale cost ₹4,20,000 and are marked at ₹6,00,000 retail. Sales during the period are ₹4,50,000 at retail. What is the estimated closing inventory at cost?","options":["₹1,50,000","₹1,15,385","₹1,05,000","₹45,000"],"answer":2,"explanation":"Cost-to-retail ratio = 4,20,000/6,00,000 = 70%; closing retail ₹1,50,000 × 70% = ₹1,05,000. ₹1,15,385 wrongly treats the 30% margin as a mark-up on cost; ₹45,000 is only the margin.","difficulty":"moderate","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-302","question":"An aircraft costs ₹50 crore. Under Ind AS 16's component approach, the engines (₹10 crore) have a 5-year life and the airframe (₹40 crore) a 20-year life; residual values are nil. What is the annual straight-line depreciation?","options":["₹2.5 crore","₹10 crore","₹3 crore","₹4 crore"],"answer":3,"explanation":"Each significant part is depreciated separately: 10/5 + 40/20 = 2 + 2 = ₹4 crore. ₹2.5 crore depreciates the whole aircraft over 20 years, understating the charge for the short-lived engines.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-303","question":"Land costing ₹60 lakh is revalued to ₹48 lakh in year 1 and to ₹66 lakh in year 2 under the revaluation model. How is the year-2 increase of ₹18 lakh recognised?","options":["₹12 lakh in profit and loss and ₹6 lakh in OCI (revaluation surplus)","All ₹18 lakh in OCI","All ₹18 lakh in profit and loss","₹6 lakh in profit and loss and ₹12 lakh in OCI"],"answer":0,"explanation":"An increase is first credited to P&L to the extent it reverses a decrease previously charged there (₹12 lakh); only the excess ₹6 lakh goes to OCI.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-304","question":"Profit before tax ₹5,00,000 is after charging depreciation ₹80,000, loss on sale of machinery ₹12,000 and interest on debentures ₹40,000, and after crediting dividend received ₹25,000. Inventory rose by ₹30,000, trade receivables fell by ₹18,000, trade payables fell by ₹22,000 and outstanding expenses rose by ₹6,000. Tax paid was ₹1,10,000. What is the net cash from operating activities of this manufacturing company?","options":["₹4,29,000","₹4,94,000","₹5,13,000","₹4,69,000"],"answer":3,"explanation":"5,00,000 + 80,000 + 12,000 + 40,000 − 25,000 = 6,07,000; working capital −30,000 + 18,000 − 22,000 + 6,000; less tax 1,10,000 → ₹4,69,000. Interest paid is financing and dividend received investing, so both are reversed; ₹5,13,000 adds the fall in payables instead of deducting it.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-305","question":"How many of these are investing cash flows for a manufacturing company? (1) Buying shares of another company as an investment (2) A loan given to a supplier company (3) Proceeds from issuing debentures (4) Payment for a patent (5) Cash paid to suppliers for raw materials","options":["2","3","4","1"],"answer":1,"explanation":"Items 1, 2 and 4 relate to acquiring long-term assets or making loans to others, so they are investing. Debenture proceeds are financing and payments to suppliers are operating.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-306","question":"Retained earnings were ₹4,00,000 at the start and ₹5,20,000 at the end of the year. Profit for the year was ₹2,60,000 and ₹50,000 was transferred to general reserve. The only other movement was dividend declared and paid. How much dividend was paid?","options":["₹90,000","₹1,40,000","₹40,000","₹1,20,000"],"answer":0,"explanation":"4,00,000 + 2,60,000 − 50,000 − dividend = 5,20,000, so dividend = ₹90,000 (a financing outflow). ₹1,40,000 forgets the reserve transfer.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-307","question":"Investments were ₹3,00,000 at the start and ₹4,50,000 at the end of the year. Investments costing ₹80,000 were sold at a profit of ₹15,000. Considering only investments, what is the net cash flow from investing activities?","options":["₹1,50,000 outflow","₹2,30,000 outflow","₹1,35,000 outflow","₹55,000 outflow"],"answer":2,"explanation":"Purchases = 4,50,000 − 3,00,000 + 80,000 = ₹2,30,000 outflow; sale proceeds = 80,000 + 15,000 = ₹95,000 inflow; net ₹1,35,000 outflow. ₹1,50,000 is just the change in the balance.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-308","question":"A company has ₹10,00,000 of 12% debt and an interest coverage ratio of 5 times. The tax rate is 25% and it has 1,00,000 equity shares (no preference shares). What is its EPS?","options":["₹4.80","₹4.50","₹6.00","₹3.60"],"answer":3,"explanation":"Interest = ₹1,20,000, so EBIT = 5 × 1,20,000 = ₹6,00,000; PAT = (6,00,000 − 1,20,000) × 75% = ₹3,60,000; EPS = ₹3.60. ₹4.80 ignores tax and ₹4.50 skips interest.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-309","question":"Annual credit sales ₹7,30,000; cost of goods sold ₹5,47,500; credit purchases ₹5,84,000; average inventory ₹90,000; average debtors ₹1,00,000; average creditors ₹60,000 (365-day year). What is the cash conversion cycle?","options":["70 days","110 days","72.5 days","147.5 days"],"answer":2,"explanation":"Inventory days 90,000/5,47,500 × 365 = 60; debtor days 1,00,000/7,30,000 × 365 = 50; creditor days 60,000/5,84,000 × 365 = 37.5. Cycle = 60 + 50 − 37.5 = 72.5 days. 70 days measures creditors against COGS instead of purchases.","difficulty":"very-hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-310","question":"A company's debt-equity ratio is 1.5 : 1. How many of these would increase it? (1) Redeeming debentures in cash (2) Buying back equity shares for cash (3) Issuing bonus shares out of reserves (4) Raising a long-term bank loan (5) Converting debentures into equity shares","options":["2","1","3","4"],"answer":0,"explanation":"Only (2), which cuts equity, and (4), which adds debt, raise the ratio. Redemption cuts debt, conversion moves debt to equity, and a bonus issue only reshuffles equity, leaving the ratio unchanged.","difficulty":"hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-311","question":"A share trades at ₹180 cum-rights. The company offers 1 new share for every 4 held at ₹130. What is the theoretical value of the right attached to each existing share?","options":["₹50","₹10","₹40","₹12.50"],"answer":1,"explanation":"Ex-rights price = (4 × 180 + 130)/5 = ₹170, so each existing share's right is worth 180 − 170 = ₹10. ₹40 is the value per new share (170 − 130); ₹12.50 divides the ₹50 discount by 4.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-312","question":"An issue of 1,00,000 shares is underwritten 60% by A and 40% by B. Applications total 80,000: marked forms A 40,000, B 10,000, and 30,000 unmarked. Unmarked applications are credited in the gross liability ratio. What is B's net liability?","options":["8,000 shares","12,000 shares","30,000 shares","18,000 shares"],"answer":3,"explanation":"Gross: A 60,000, B 40,000; less marked: A 20,000, B 30,000; less unmarked in 60 : 40 (18,000 and 12,000): A 2,000, B 18,000. Total 20,000 = the shortfall. 12,000 splits the unmarked forms in the net ratio instead.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-313","question":"Opening finished stock is 2,000 units carrying ₹12 a unit of fixed overhead; 12,000 units are produced with fixed overhead absorbed at ₹15 a unit, and 13,000 are sold (FIFO). How does absorption-costing profit compare with marginal-costing profit?","options":["Lower by ₹9,000","Lower by ₹15,000","Higher by ₹9,000","Lower by ₹3,000"],"answer":0,"explanation":"The gap equals fixed overhead in closing stock minus that in opening stock: 1,000 × 15 − 2,000 × 12 = −₹9,000, so absorption profit is ₹9,000 lower. ₹15,000 values the 1,000-unit fall at the current rate only.","difficulty":"very-hard","source":"CA Inter level · Big 4"},
  {"id":"mgmt-accounting-314","question":"Selling price ₹80 and variable cost ₹50 a unit. Fixed costs are ₹3,60,000 up to 15,000 units and rise by ₹60,000 beyond that. How many units must be sold for a profit of ₹1,50,000?","options":["17,000","19,000","12,000","21,000"],"answer":1,"explanation":"Without the step, (3,60,000 + 1,50,000)/30 = 17,000 units, which exceeds 15,000, so fixed costs become ₹4,20,000: (4,20,000 + 1,50,000)/30 = 19,000 units. 17,000 forgets the step cost.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-315","question":"Standard per unit: 2 skilled hours at ₹60 and 3 unskilled hours at ₹30. For 1,000 units, actual hours were skilled 2,300 at ₹62 and unskilled 2,700 at ₹29. What is the labour mix variance?","options":["₹9,000 favourable","₹1,900 adverse","₹9,000 adverse","₹10,900 adverse"],"answer":2,"explanation":"Actual 5,000 hours in standard mix (2,000 : 3,000) cost ₹2,10,000; actual mix at standard rates costs ₹2,19,000, so mix variance = ₹9,000 A (more costly skilled hours). ₹1,900 A is the rate variance; ₹10,900 A the total cost variance.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-316","question":"Budget: X 2,000 units (contribution ₹20 a unit) and Y 3,000 units (₹10 a unit). Actual sales: X 1,500 units and Y 4,000 units. What is the sales mix variance (contribution basis)?","options":["₹7,000 favourable","Nil","₹14,000 adverse","₹7,000 adverse"],"answer":3,"explanation":"Actual 5,500 units in budget mix (40 : 60) = X 2,200, Y 3,300. Mix variance = (1,500 − 2,200) × 20 + (4,000 − 3,300) × 10 = −₹7,000 (A). The quantity variance is +₹7,000, so total volume variance is nil, which is the trap.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-317","question":"8,000 units enter a process; materials ₹2,40,000 and conversion ₹1,20,000. Normal loss is 5% of input, sold as scrap at ₹10 a unit. Actual output is 7,800 units. At what value is the abnormal gain debited to the process account?","options":["₹9,368","₹7,368","₹9,000","₹9,474"],"answer":0,"explanation":"Normal cost per unit = (3,60,000 − 4,000 scrap)/7,600 = ₹46.84; abnormal gain 200 units × 46.84 = ₹9,368. ₹7,368 is the net gain after lost scrap (credited to costing P&L), not the process-account figure.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-318","question":"Joint product P (5,000 kg) can be sold at split-off for ₹30 a kg, or processed further and sold at ₹46 a kg. Further processing costs ₹70,000 variable plus ₹20,000 of fixed costs that arise only if processing is done. The joint cost apportioned to P is ₹1,10,000. What should be done?","options":["Process further: profit rises by ₹10,000","Sell at split-off: processing would cut profit by ₹10,000","Process further: profit rises by ₹70,000","Sell at split-off because P shows a loss after joint costs"],"answer":1,"explanation":"Incremental revenue 5,000 × 16 = ₹80,000 against incremental cost ₹90,000 (the avoidable fixed cost counts), so processing loses ₹10,000. Joint costs are sunk and irrelevant; ignoring the avoidable ₹20,000 gives the wrong ₹10,000 gain.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-319","question":"A component needed at 8,000 units a year costs ₹55 a unit (variable) to make, plus ₹12 of apportioned fixed overhead that will not change. A supplier quotes ₹62. If bought, the freed space can be rented out for ₹60,000 a year. What should the firm do?","options":["Make, saving ₹56,000","Make, saving ₹4,000","Buy, saving ₹4,000","Buy, saving ₹60,000"],"answer":2,"explanation":"Relevant cost of making = 8,000 × 55 + 60,000 rent forgone = ₹5,00,000; buying costs ₹4,96,000, so buy and save ₹4,000. Ignoring the opportunity cost makes 'make, saving ₹56,000' look right.","difficulty":"hard","source":"Big 4 · Bank MT"},
  {"id":"mgmt-accounting-320","question":"Annual demand is 12,000 units, ordering cost ₹400 an order, price ₹50 a unit and carrying cost 20% of price. The supplier offers a 2% discount on orders of 2,000 units or more. What is the net annual saving from ordering 2,000 units instead of the EOQ?","options":["₹12,000","₹9,398","₹7,200","₹9,598"],"answer":3,"explanation":"At EOQ ≈ 980 units total cost = 6,00,000 + 4,899 + 4,899 = ₹6,09,798. At 2,000: 5,88,000 + 2,400 ordering + 1,000 × 9.80 carrying = ₹6,00,200; saving ≈ ₹9,598. ₹9,398 forgets that carrying cost falls with the discounted price.","difficulty":"very-hard","source":"CA Inter level · Big 4"},
  {"id":"mgmt-accounting-321","question":"Which treatment of overtime premium is correct in cost accounting?","options":["Always charged to the job worked on during overtime","Always written off to costing profit and loss","Charged to the specific job if worked at the customer's request, and to production overheads if due to general pressure of work","Charged to production overheads if worked at the customer's request, and to the job if due to general pressure"],"answer":2,"explanation":"Premium caused by a customer's urgency is a direct cost of that job; premium from general workload is spread through factory overhead. Only abnormal overtime (e.g., due to a breakdown) goes to costing P&L.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-322","question":"Budgeted sales are 10,000 units in January, 12,000 in February and 15,000 in March. Closing finished stock each month must be 20% of the next month's sales; opening stock on 1 January is 1,800 units. What is February's production?","options":["12,600 units","12,000 units","11,400 units","10,600 units"],"answer":0,"explanation":"Production = sales + closing stock − opening stock = 12,000 + 3,000 − 2,400 = 12,600. 10,600 is January's figure; 11,400 reverses the stock adjustments.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-323","question":"Under Ind AS 115, a product is priced at ₹100, but if the customer buys more than 1,000 units in the year the price for all units falls to ₹90. In quarter 1 the customer buys 300 units and the company expects the threshold to be crossed. What is recorded for quarter 1?","options":["Revenue ₹30,000, no liability","Revenue ₹27,000 and refund liability ₹3,000","Revenue ₹30,000 and an expense of ₹3,000","Revenue ₹27,000, no liability"],"answer":1,"explanation":"The rebate is variable consideration: revenue is recognised at the expected price ₹90 (₹27,000), and the ₹3,000 billed in excess is a refund liability. Booking ₹30,000 revenue overstates it.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-324","question":"An online marketplace collects ₹10,00,000 from customers for goods supplied by third-party sellers, keeping a 12% commission. It never controls the goods before transfer. What revenue does the marketplace recognise under Ind AS 115?","options":["₹10,00,000","₹8,80,000","₹11,20,000","₹1,20,000"],"answer":3,"explanation":"Without control of the goods, the platform is an agent and recognises only its net commission (₹1,20,000) as revenue. Recognising ₹10,00,000 gross treats it as principal.","difficulty":"moderate","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-325","question":"A company wins a ₹50 lakh damages claim in a lower court; the defendant has appealed, and the company's lawyers say the inflow is probable but not virtually certain. How does Ind AS 37 treat it?","options":["Disclose a contingent asset; do not recognise it","Recognise a receivable of ₹50 lakh","Recognise a receivable at the probability-weighted amount","Neither recognise nor disclose it"],"answer":0,"explanation":"A contingent asset is recognised only when the inflow is virtually certain; when it is probable it is only disclosed. Recognising it here would break the prudence asymmetry with contingent liabilities.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-326","question":"On dissolution, assets (other than cash) of book value ₹4,00,000 and creditors of ₹1,20,000 are transferred to the realisation account. Partner A takes stock of book value ₹50,000 at ₹45,000; the other assets realise ₹3,80,000; an unrecorded computer realises ₹8,000; creditors are paid ₹1,15,000; realisation expenses of ₹6,000 are paid. What is the realisation profit?","options":["₹24,000","₹27,000","₹38,000","₹32,000"],"answer":3,"explanation":"Credits: 1,20,000 + 45,000 + 3,80,000 + 8,000 = 5,53,000; debits: 4,00,000 + 1,15,000 + 6,000 = 5,21,000; profit ₹32,000. ₹24,000 misses the unrecorded asset and ₹38,000 the expenses.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-327","question":"How many of these statements are correct? (1) FIFO gives the same closing stock whether applied periodically or perpetually. (2) Ind AS 2 permits LIFO. (3) Items that are not ordinarily interchangeable are costed by specific identification. (4) Weighted average gives the same closing stock under periodic and perpetual systems.","options":["1","2","3","4"],"answer":1,"explanation":"(1) and (3) are true. Ind AS 2 bans LIFO, and the perpetual (moving) average re-averages after each receipt, so it generally differs from the periodic average.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-328","question":"Goods of ₹4,000 returned by a customer were received and included in closing stock, but no entry was made in the books. What is the effect on the year's profit?","options":["Understated by ₹4,000","No effect","Overstated by ₹4,000","Overstated by ₹8,000"],"answer":2,"explanation":"Stock is correctly counted, but the sales return is not recorded, so net sales and debtors are ₹4,000 too high and profit is overstated by ₹4,000. The fix is Dr Sales Returns, Cr the customer.","difficulty":"hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-329","question":"A building costing ₹20 lakh (life 20 years, nil residual) is revalued to ₹24 lakh at the end of year 5, with 15 years remaining. What is the annual depreciation from year 6, and how may the revaluation surplus be dealt with?","options":["₹1 lakh to P&L; ₹60,000 credited to OCI each year","₹1.6 lakh to P&L; ₹60,000 recycled from surplus through P&L each year","₹1.2 lakh to P&L; surplus left untouched","₹1.6 lakh to P&L; ₹60,000 transferred each year from revaluation surplus directly to retained earnings"],"answer":3,"explanation":"Depreciation is on the revalued amount: 24/15 = ₹1.6 lakh. The surplus of ₹9 lakh may be released as it is used (9/15 = ₹60,000 a year), directly to retained earnings, never through P&L.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-330","question":"A company redeems 10,000 preference shares of ₹100 at a 10% premium, partly out of a fresh issue of 5,000 equity shares of ₹100 at a 20% premium made for the purpose. What amount must be transferred to the capital redemption reserve?","options":["₹4,00,000","₹10,00,000","₹5,00,000","₹6,00,000"],"answer":2,"explanation":"CRR = nominal value redeemed minus the face value of the fresh issue: 10,00,000 − 5,00,000 = ₹5,00,000. The premium on the fresh issue does not count as proceeds for this purpose, so ₹4,00,000 is the trap.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-331","question":"A company's return on capital employed (pre-tax) is 15%, debt costs 10%, its debt-equity ratio is 1 : 1 and the tax rate is 30%. What is its return on equity?","options":["14%","20%","10.5%","17.5%"],"answer":0,"explanation":"Pre-tax ROE = ROI + (ROI − interest) × D/E = 15 + 5 × 1 = 20%; after tax 20 × 0.7 = 14%. 20% forgets tax and 10.5% ignores the leverage gain.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-332","question":"H acquires 60% of S. At acquisition S's building has a fair value ₹5,00,000 above book value, with 10 years' remaining life. S reports a profit of ₹3,00,000 in the first year. NCI is measured at its share of net assets. What is NCI's share of consolidated profit?","options":["₹1,20,000","₹1,00,000","₹1,50,000","₹1,40,000"],"answer":1,"explanation":"Profit must be adjusted for extra depreciation on the fair-value uplift: 3,00,000 − 50,000 = 2,50,000; NCI 40% = ₹1,00,000. ₹1,20,000 uses S's book profit; ₹1,50,000 is the parent's 60%.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-333","question":"A worker is paid ₹30,000 a month for 25 days of 8 hours; normal idle time is 10% of hours, and the employer also pays PF at 12% of wages. What is the labour cost per productive hour?","options":["₹168.00","₹166.67","₹150.00","₹186.67"],"answer":3,"explanation":"Total cost = 30,000 × 1.12 = ₹33,600; productive hours = 200 × 90% = 180; cost = ₹186.67 an hour. ₹168 spreads cost over all 200 hours and ₹166.67 leaves out PF.","difficulty":"moderate","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-334","question":"B draws a bill of ₹20,000 on A, who accepts it. B endorses the bill to his creditor C. On maturity A dishonours it and C pays noting charges of ₹100. What entry does B pass?","options":["Dr A ₹20,000; Cr Bills Receivable ₹20,000","Dr A ₹20,100; Cr C ₹20,100","Dr C ₹20,100; Cr A ₹20,100","Dr Noting Charges ₹100, Dr A ₹20,000; Cr Bank ₹20,100"],"answer":1,"explanation":"The bill no longer sits with B, so C claims ₹20,100 (bill plus noting) from B, and B in turn recovers it from the drawee A: Dr A, Cr C ₹20,100. Crediting Bills Receivable is wrong because B already credited it on endorsement.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-335","question":"Goods with a list price of ₹50,000 are sold at a 10% trade discount and on terms of 2% cash discount for payment within 10 days. The customer pays half the amount due within 10 days. How much discount allowed is recorded in the books?","options":["₹500","₹900","₹5,450","₹450"],"answer":3,"explanation":"Trade discount is never recorded; the invoice is ₹45,000. Cash discount applies only to the half paid in time: 2% × 22,500 = ₹450. ₹500 applies the 2% to half the list price.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-336","question":"Repairs to a building of ₹15,000 were debited to the Building account, and depreciation of 10% was charged on the closing balance of the Building account. What is the effect on profit?","options":["Overstated by ₹13,500","Overstated by ₹15,000","Understated by ₹13,500","Overstated by ₹16,500"],"answer":0,"explanation":"Revenue expense of ₹15,000 was capitalised (profit up ₹15,000), but extra depreciation of ₹1,500 was charged on it (profit down ₹1,500): net overstatement ₹13,500.","difficulty":"hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-337","question":"Rent received during 2023-24 was ₹1,30,000. It includes ₹10,000 for 2022-23 (shown as accrued last year) and ₹20,000 for 2024-25. Rent of ₹15,000 for March 2024 is still due. What rent income is credited to the 2023-24 profit and loss account?","options":["₹1,45,000","₹1,25,000","₹1,15,000","₹1,05,000"],"answer":2,"explanation":"1,30,000 − 10,000 (earlier year) − 20,000 (advance) + 15,000 (accrued) = ₹1,15,000. ₹1,25,000 forgets the arrears relate to last year; ₹1,45,000 ignores the advance.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-338","question":"The opening provision for doubtful debts was ₹8,000. During the year bad debts of ₹6,000 were written off, and the total charge to profit and loss for bad debts and provision was ₹11,000. Closing debtors (after write-offs) are ₹2,60,000. What percentage provision was made on closing debtors?","options":["4.2%","3%","6.5%","5%"],"answer":3,"explanation":"Charge = bad debts + new provision − old provision: 6,000 + x − 8,000 = 11,000, so x = ₹13,000 = 5% of 2,60,000. 4.2% wrongly treats the whole ₹11,000 charge as the new provision.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-339","question":"A partner's capital was ₹2,00,000 on 1 April. He introduced ₹1,00,000 more on 1 October and withdrew ₹50,000 of capital on 1 January. Interest on capital is 10% a year and the year ends on 31 March. What is his interest on capital?","options":["₹23,750","₹25,000","₹21,250","₹20,000"],"answer":0,"explanation":"20,000 on the opening balance + 1,00,000 × 10% × 6/12 = 5,000 − 50,000 × 10% × 3/12 = 1,250 → ₹23,750. ₹25,000 charges interest on the closing capital for a full year.","difficulty":"moderate","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-340","question":"A and B change their profit ratio from 3 : 2 to 1 : 1. The books show a general reserve of ₹50,000, and a revaluation gain of ₹20,000 is found; both are to be left undisturbed in the books. What single adjusting entry is passed?","options":["Dr A ₹7,000; Cr B ₹7,000","Dr B ₹5,000; Cr A ₹5,000","Dr B ₹7,000; Cr A ₹7,000","Dr B ₹2,000; Cr A ₹2,000"],"answer":2,"explanation":"B gains 1/2 − 2/5 = 1/10 and A sacrifices the same. Combined reserve and gain = ₹70,000, so B compensates A ₹7,000. ₹5,000 adjusts only the reserve and ₹2,000 only the revaluation.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-341","question":"A deceased partner's executor is owed ₹1,20,000, to be paid in three equal annual instalments of principal plus 10% interest on the unpaid balance. What total interest is paid over the three years?","options":["₹36,000","₹24,000","₹12,000","₹20,000"],"answer":1,"explanation":"Interest falls with the balance: 10% × 1,20,000 + 10% × 80,000 + 10% × 40,000 = 12,000 + 8,000 + 4,000 = ₹24,000. ₹36,000 wrongly charges interest on the full amount every year.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-342","question":"A, B and C share profits 5 : 3 : 2. B retires, and A and C continue in the ratio 3 : 2. Goodwill is ₹1,50,000 and is not to appear in the books. How much does each continuing partner pay towards B's share of goodwill?","options":["A ₹27,000, C ₹18,000","A ₹32,143, C ₹12,857","A ₹22,500, C ₹22,500","A ₹15,000, C ₹30,000"],"answer":3,"explanation":"B's share = 3/10 × 1,50,000 = ₹45,000, borne in the gaining ratio: A gains 3/5 − 5/10 = 1/10, C gains 2/5 − 2/10 = 2/10, so 1 : 2 → A ₹15,000, C ₹30,000. Using the new ratio 3 : 2 is the classic trap.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-343","question":"400 shares of ₹10 were issued at ₹13 (premium ₹3 payable with allotment). The holder paid ₹3 on application and ₹5 on allotment but failed to pay the first and final call of ₹5. The shares were forfeited and later reissued at ₹8 each fully paid. What is transferred to capital reserve?","options":["₹2,400","₹2,000","₹800","₹1,200"],"answer":3,"explanation":"Since the premium was received, it stays in securities premium; forfeiture credits only capital paid, 400 × (3 + 2) = ₹2,000. Discount on reissue = 400 × 2 = ₹800, so capital reserve = ₹1,200. ₹2,400 wrongly includes the premium in forfeited money.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-344","question":"Employees exercise 1,000 vested options at an exercise price of ₹50 per share (face value ₹10). The ESOP outstanding account carries ₹30 per option. How much is credited to securities premium?","options":["₹70,000","₹40,000","₹80,000","₹30,000"],"answer":0,"explanation":"Consideration = cash ₹50 + ESOP reserve ₹30 = ₹80 per share; ₹10 goes to share capital and ₹70 to securities premium, so ₹70,000. ₹40,000 forgets to transfer the ESOP reserve.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-345","question":"Under Ind AS 115, goods are delivered today and the customer will pay ₹11,00,000 after two years; the contract has a significant financing component and the discount rate is 10%. What revenue is recognised on delivery, and what interest income in year 1?","options":["₹11,00,000 revenue; no interest","₹10,00,000 revenue; ₹1,00,000 interest","₹9,09,091 revenue; ₹90,909 interest","₹9,90,000 revenue; ₹1,10,000 interest"],"answer":2,"explanation":"Revenue is the cash-equivalent price: 11,00,000/1.1² = ₹9,09,091; the receivable unwinds at 10%, giving interest of ₹90,909 in year 1. Discounting for one year only gives ₹10,00,000.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-346","question":"A company sells a TV with the standard 1-year manufacturer warranty (assurance only) and also sells, for a separate price, an extended 3-year service warranty. How are these treated under Ind AS 115 and Ind AS 37?","options":["Both are separate performance obligations with revenue deferred","Assurance warranty → provision under Ind AS 37; extended warranty → separate performance obligation with revenue deferred","Both are provided for under Ind AS 37","Assurance warranty → separate performance obligation; extended warranty → provision"],"answer":1,"explanation":"An assurance-type warranty only promises the product works as specified, so it is a cost provision. A warranty sold separately provides a service and is a distinct performance obligation whose revenue is recognised over the coverage period.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-347","question":"A machine is bought for a list price of ₹10,00,000 less 5% trade discount, plus recoverable GST ₹1,71,000, non-refundable import duty ₹50,000, site preparation ₹30,000, professional installation fees ₹25,000, staff training ₹20,000, initial operating losses ₹15,000, and a dismantling obligation with present value ₹40,000. What is its cost under Ind AS 16?","options":["₹11,30,000","₹12,66,000","₹10,55,000","₹10,95,000"],"answer":3,"explanation":"Cost = 9,50,000 + 50,000 + 30,000 + 25,000 + 40,000 = ₹10,95,000. Recoverable GST, training and start-up losses are excluded; leaving out the dismantling obligation gives ₹10,55,000.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-348","question":"A company borrows ₹50 lakh at 12% on 1 April specifically to construct a qualifying asset, which is completed on 31 December. Before being spent, part of the loan earned ₹40,000 on temporary investment. Under Ind AS 23, what borrowing cost is capitalised?","options":["₹4,10,000","₹4,50,000","₹6,00,000","₹5,60,000"],"answer":0,"explanation":"Capitalise interest for the 9-month construction period, 50,00,000 × 12% × 9/12 = ₹4,50,000, less income on temporary investment ₹40,000 = ₹4,10,000. Interest after completion is expensed.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-349","question":"An asset with a carrying amount of ₹9,00,000 will generate cash flows of ₹3,00,000, ₹3,00,000 and ₹4,00,000 at the end of the next three years; the discount rate is 10%. Its fair value less costs of disposal is ₹7,80,000. What impairment loss is recognised under Ind AS 36?","options":["₹1,20,000","₹78,813","Nil","₹1,00,000"],"answer":1,"explanation":"Value in use = 2,72,727 + 2,47,934 + 3,00,526 = ₹8,21,187, which exceeds FVLCD, so recoverable amount is ₹8,21,187 and the loss is ₹78,813. ₹1,20,000 uses the lower FVLCD; 'Nil' adds undiscounted flows (₹10 lakh).","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-350","question":"A company's deferred tax liability is ₹3,00,000, measured at a 30% tax rate. A new rate of 25% is enacted for future years, with no other change in temporary differences. What is the effect?","options":["DTL stays at ₹3,00,000 until the differences reverse","DTL falls to ₹2,50,000 and ₹50,000 is credited to OCI","DTL falls to ₹2,50,000 and ₹50,000 is credited to profit and loss","DTL rises to ₹3,60,000"],"answer":2,"explanation":"Deferred tax uses enacted rates, so the temporary difference of ₹10,00,000 is remeasured at 25% = ₹2,50,000, and the ₹50,000 decrease goes to P&L (where the original charge went).","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-351","question":"Profit is ₹50,00,000 and 10,00,000 equity shares are outstanding all year. There are 10,000 convertible debentures of ₹100 with 10% interest, each convertible into 5 equity shares; the tax rate is 25%. What is diluted EPS?","options":["₹4.76","₹4.86","₹5.00","₹4.83"],"answer":3,"explanation":"Add back post-tax interest 1,00,000 × 75% = ₹75,000 and add 50,000 potential shares: 50,75,000/10,50,000 = ₹4.83. ₹4.76 forgets the interest saving; ₹4.86 adds back pre-tax interest.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-352","question":"Gross profit is 25% on cost. 80% of sales are on credit, the debtors collection period is 1.5 months and closing debtors (used for the ratio) are ₹1,20,000. What is the cost of goods sold?","options":["₹9,60,000","₹9,00,000","₹7,68,000","₹7,20,000"],"answer":0,"explanation":"Credit sales = 1,20,000 × 12/1.5 = ₹9,60,000; total sales = 9,60,000/0.8 = ₹12,00,000; COGS = 12,00,000/1.25 = ₹9,60,000. ₹9,00,000 treats 25% as a margin on sales; ₹7,68,000 forgets cash sales.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-353","question":"A company has no long-term debt. Its fixed assets are 0.75 times shareholders' funds, its current ratio is 2 : 1 and its working capital is ₹2,00,000. What are its total assets?","options":["₹8,00,000","₹12,00,000","₹10,00,000","₹6,00,000"],"answer":2,"explanation":"Funds = FA + WC, so WC = 0.25 × funds → funds ₹8,00,000, FA ₹6,00,000. CL = WC = ₹2,00,000 and CA = ₹4,00,000; total assets = 6,00,000 + 4,00,000 = ₹10,00,000. ₹8,00,000 is only the shareholders' funds.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-354","question":"A 50-bed hospital works 365 days a year at 80% average occupancy. Its annual costs are ₹43,80,000. What is the cost per patient-day?","options":["₹240","₹300","₹375","₹250"],"answer":1,"explanation":"Patient-days = 50 × 365 × 0.8 = 14,600; 43,80,000/14,600 = ₹300. ₹240 uses full capacity (18,250 patient-days) instead of actual occupancy.","difficulty":"moderate","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-355","question":"A machine costs ₹10,00,000 with a residual value of ₹1,00,000 and a 10-year life, working 2,000 hours a year. Power is 10 units an hour at ₹8; repairs ₹60,000 a year; an operator paid ₹4,80,000 a year spends half his time on it; rent apportioned ₹48,000. What is the machine hour rate?","options":["₹419","₹219","₹254","₹299"],"answer":3,"explanation":"Standing charges: depreciation 90,000 + repairs 60,000 + half the operator 2,40,000 + rent 48,000 = 4,38,000 / 2,000 = ₹219, plus power ₹80 = ₹299. ₹419 charges the operator's full salary; ₹219 forgets power.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-356","question":"Production overhead is under-absorbed by ₹50,000 because of an incorrect estimate (not abnormal causes), and the amount is material. How is it normally dealt with in cost accounts?","options":["Spread over WIP, finished goods and cost of sales using a supplementary rate","Written off to costing profit and loss","Carried forward to next year","Charged entirely to cost of goods sold"],"answer":0,"explanation":"A material under-absorption arising from estimation errors is corrected by a supplementary rate across WIP, finished stock and cost of sales. Writing it off to costing P&L is for abnormal causes or small amounts.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-357","question":"Standard: 100 kg of input yields 90 kg of output; material costs ₹30 a kg. Actual input 5,000 kg produced 4,400 kg. What is the material yield variance?","options":["₹3,000 adverse","₹3,333 favourable","₹3,333 adverse","₹3,667 adverse"],"answer":2,"explanation":"Standard cost per kg of output = 3,000/90 = ₹33.33. Expected output from 5,000 kg is 4,500; shortfall 100 kg × 33.33 = ₹3,333 A. ₹3,000 values the lost output at the input price.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-358","question":"H acquires 70% of S on 1 October. S's share capital is ₹5,00,000, reserves on 1 April were ₹3,00,000 and its profit of ₹2,40,000 for the year ended 31 March accrued evenly. H paid ₹7,00,000; fair values equal book values. What arises on consolidation?","options":["Goodwill ₹56,000","Goodwill ₹1,40,000","Capital reserve ₹28,000","Goodwill ₹3,50,000"],"answer":0,"explanation":"Half-year profit (₹1,20,000) is pre-acquisition, so net assets acquired = 5,00,000 + 3,00,000 + 1,20,000 = 9,20,000; goodwill = 7,00,000 − 70% × 9,20,000 = ₹56,000. ₹1,40,000 ignores the pre-acquisition profit; the capital reserve treats the whole year's profit as pre-acquisition.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-359","question":"An 80%-owned subsidiary sells goods to its parent at a margin of 25% on the selling price. Goods invoiced at ₹1,60,000 are still in the parent's stock at year end. NCI is measured at its share of net assets. How much of the unrealised profit is charged to NCI?","options":["Nil","₹6,400","₹8,000","₹40,000"],"answer":2,"explanation":"Unrealised profit = 25% × 1,60,000 = ₹40,000; in an upstream sale it is shared, so NCI bears 20% = ₹8,000. 'Nil' would apply to downstream sales; ₹6,400 treats 25% as a mark-up on cost.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-360","question":"An item costing ₹1,00,000 was written down to its NRV of ₹80,000 last year. It is still unsold, and its NRV is now ₹1,10,000. Under Ind AS 2, how is it carried this year?","options":["₹1,10,000, with ₹30,000 credited to P&L","₹80,000, since a write-down cannot be reversed","₹1,00,000, with ₹20,000 credited to OCI","₹1,00,000, with a ₹20,000 reversal credited to P&L"],"answer":3,"explanation":"Ind AS 2 requires reversal of a write-down when NRV recovers, but only up to the original write-down: inventory returns to the lower of cost and NRV, ₹1,00,000, and the ₹20,000 reversal reduces the expense in P&L.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-361","question":"A firm is at full capacity, selling its product at ₹150 (variable cost ₹90). A customer asks for 1,000 units that need special packaging costing ₹5 a unit, and accepting would displace regular sales. What is the minimum acceptable price per unit?","options":["₹95","₹155","₹150","₹125"],"answer":1,"explanation":"Relevant cost = variable cost 90 + packaging 5 + lost contribution 60 = ₹155. ₹95 is only right when there is idle capacity.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-362","question":"Under Ind AS 116, which of these is NOT included in the measurement of a lessee's lease liability?","options":["Payments linked to a consumer price index","Variable payments based on a percentage of the lessee's store sales","A purchase option the lessee is reasonably certain to exercise","Amounts expected to be payable under a residual value guarantee"],"answer":1,"explanation":"Variable payments tied to future sales or usage are expensed when incurred. Index-linked payments, reasonably certain purchase options and expected residual-value guarantee payments all enter the liability.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-363","question":"A and B are partners with no partnership deed. A's capital is ₹3,00,000 and B's ₹1,00,000. A also lent the firm ₹1,00,000 on 1 October; the year ends on 31 March. Profit before any interest is ₹50,000. What is A's total income from the firm?","options":["₹26,500","₹25,000","₹38,250","₹28,000"],"answer":0,"explanation":"With no deed, loan interest is 6% a year: 1,00,000 × 6% × 6/12 = ₹3,000; no interest on capital; the remaining ₹47,000 is shared equally, so A gets 3,000 + 23,500 = ₹26,500. ₹38,250 splits profit in capital ratio.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-364","question":"A machine bought on 1 April 2021 for ₹10,00,000 was depreciated at 20% WDV. From 1 April 2024 the company switches to straight-line over the remaining 4 years with a residual value of ₹52,000, to reflect the changed pattern of benefits. What is the depreciation for 2024-25 under Ind AS?","options":["₹1,28,000","₹1,15,000","₹1,35,429","₹1,02,400"],"answer":1,"explanation":"A change in depreciation method is a change in estimate, applied prospectively: carrying amount 10,00,000 × 0.8³ = ₹5,12,000; (5,12,000 − 52,000)/4 = ₹1,15,000. ₹1,35,429 restarts from cost (retrospective); ₹1,28,000 ignores residual value.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-365","question":"A machine costing ₹3,00,000, bought on 1 April 2021, is depreciated at 15% a year on cost (year ends 31 March), with accumulated depreciation kept in a provision account. It is sold on 1 October 2023 for ₹1,90,000. What is the profit or loss on sale?","options":["Loss ₹20,000","Profit ₹25,000","Loss ₹2,500","Profit ₹2,500"],"answer":3,"explanation":"Depreciation for 2½ years = 45,000 × 2.5 = ₹1,12,500; book value ₹1,87,500; sale at ₹1,90,000 gives a profit of ₹2,500. The ₹20,000 loss forgets the half-year charge to the date of sale.","difficulty":"moderate","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-366","question":"Opening stock 400 units at ₹50; purchases 600 units at ₹55 and then 1,000 units at ₹60; sales 1,500 units at ₹90 (periodic system). How does gross profit under FIFO compare with weighted average?","options":["FIFO higher by ₹1,750","Weighted average higher by ₹1,750","FIFO higher by ₹3,500","FIFO higher by ₹1,250"],"answer":0,"explanation":"FIFO COGS = 20,000 + 33,000 + 30,000 = ₹83,000; average cost = 1,13,000/2,000 = ₹56.50, so COGS = ₹84,750. With rising prices FIFO charges older, cheaper costs: gross profit ₹1,750 higher.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-367","question":"The pass book shows a credit balance of ₹45,000. The bank wrongly debited ₹2,000 of another customer's cheque. Of cheques issued for ₹12,000, ₹7,000 were presented; of cheques deposited for ₹18,000, ₹15,000 were credited. An insurance premium of ₹1,500 paid by standing order and a dividend of ₹3,000 collected by the bank are not in the cash book, and a deposit of ₹2,700 was entered in the cash book as ₹7,200. What was the cash-book balance before correction?","options":["₹45,000","₹44,000","₹39,000","₹48,000"],"answer":3,"explanation":"Correct pass book = 47,000; less unpresented 5,000, plus uncleared 3,000 = amended cash book ₹45,000. Reversing the cash-book corrections (+1,500 premium, −3,000 dividend, +4,500 over-entry) gives the original ₹48,000.","difficulty":"very-hard","source":"Bank MT · IBPS SO"},
  {"id":"mgmt-accounting-368","question":"A company has equity capital ₹10 lakh, reserves ₹5 lakh, 10% preference capital ₹5 lakh, 12% debentures ₹10 lakh and long-term loans ₹5 lakh. What is its capital gearing ratio?","options":["1.00","0.57","1.33","0.75"],"answer":2,"explanation":"Capital gearing = fixed-charge-bearing funds (preference + debentures + loans = ₹20 lakh) ÷ equity shareholders' funds (₹15 lakh) = 1.33, i.e., highly geared. 1.00 leaves out preference capital.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-369","question":"A company's current ratio is 0.8 : 1. Which of these would increase it? (1) Paying a trade creditor in cash (2) Buying stock on credit (3) Collecting cash from a debtor (4) Raising a short-term loan in cash","options":["1 only","1 and 3","2 and 4 only","2 only"],"answer":2,"explanation":"When the ratio is below 1, adding equal amounts to current assets and current liabilities (2 and 4) raises it, e.g., 90/110 > 80/100, while paying a creditor (1) lowers it. Collecting a debtor only swaps one current asset for another.","difficulty":"very-hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-370","question":"Purchases for the year are ₹6,00,000, of which 80% are on credit. Creditors were ₹70,000 at the start and ₹90,000 at the end. Under the direct method, what is the cash paid to suppliers?","options":["₹4,60,000","₹5,80,000","₹6,20,000","₹6,00,000"],"answer":1,"explanation":"Cash purchases ₹1,20,000 + payments to creditors (70,000 + 4,80,000 − 90,000 = 4,60,000) = ₹5,80,000. ₹4,60,000 forgets the cash purchases; ₹6,20,000 adds the rise in creditors.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-371","question":"All sales of ₹12,00,000 are on credit. Gross debtors were ₹1,50,000 at the start and ₹1,80,000 at the end; bad debts of ₹10,000 were written off and the provision for doubtful debts was raised by ₹5,000. What cash was received from customers?","options":["₹11,70,000","₹11,55,000","₹12,30,000","₹11,60,000"],"answer":3,"explanation":"Cash = 1,50,000 + 12,00,000 − 10,000 written off − 1,80,000 = ₹11,60,000. The provision is a non-cash adjustment that does not touch gross debtors, so deducting it (₹11,55,000) is wrong; ignoring the write-off gives ₹11,70,000.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-372","question":"In an amalgamation in the nature of purchase (AS 14, net assets method), T takes over fixed assets at ₹8,00,000, stock ₹2,00,000 and debtors ₹1,50,000 less a 5% provision, and assumes creditors of ₹1,20,000. S's debentures of ₹3,00,000 are discharged by T issuing its own debentures. What is the purchase consideration?","options":["₹7,22,500","₹10,22,500","₹7,30,000","₹8,42,500"],"answer":0,"explanation":"Purchase consideration is what is paid to the transferor's shareholders: 8,00,000 + 2,00,000 + 1,42,500 − 1,20,000 − 3,00,000 = ₹7,22,500. Debenture holders are paid separately, so not deducting them gives ₹10,22,500.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-373","question":"A company issues shares to the public but has received only 85% of the minimum subscription stated in the prospectus within 30 days of the issue closing. What must it do?","options":["Allot shares to applicants and call the rest later","Allot shares and have the underwriters pay only interest","Refund the application money within the prescribed time and not allot","Treat the shortfall as calls in arrears"],"answer":2,"explanation":"Under the Companies Act, 2013 no allotment can be made unless the minimum subscription is received; otherwise the application money must be refunded within the prescribed period, with interest if delayed.","difficulty":"moderate","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-374","question":"A company had 8,00,000 shares on 1 April, issued 2,00,000 shares at full market price for cash on 1 July, and made a 1-for-5 bonus issue on 1 January. Profit for the year to 31 March is ₹1,14,00,000. What is basic EPS?","options":["₹12.00","₹9.50","₹11.40","₹10.00"],"answer":3,"explanation":"Bonus shares are treated as outstanding from the start: 8,00,000 × 1.2 + 2,00,000 × 1.2 × 9/12 = 11,40,000 shares; EPS = ₹10. ₹11.40 adds the bonus only from 1 January; ₹12 ignores the bonus.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-375","question":"For the year ended 31 March, a company's board proposes a dividend of ₹5 a share on 20 May; shareholders approve it at the AGM in August. How is it shown in the 31 March financial statements under Ind AS 10?","options":["Disclosed in the notes; not recognised as a liability at 31 March","Recognised as a liability at 31 March as an adjusting event","Recognised as a provision under Ind AS 37","Recognised directly in equity at 31 March"],"answer":0,"explanation":"Dividends declared after the reporting date are non-adjusting: there was no obligation at 31 March, so no liability is recognised; the proposed amount is disclosed.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-376","question":"A company announces a restructuring with these expected costs: redundancy payments ₹40 lakh, retraining of continuing staff ₹10 lakh, relocating continuing staff ₹6 lakh, lease termination penalties ₹8 lakh and future operating losses ₹5 lakh. What restructuring provision is recognised under Ind AS 37?","options":["₹58 lakh","₹48 lakh","₹69 lakh","₹53 lakh"],"answer":1,"explanation":"Only direct costs that are necessarily entailed and not related to ongoing activities qualify: redundancy ₹40 lakh + lease penalties ₹8 lakh = ₹48 lakh. Retraining and relocation relate to the continuing business, and future operating losses are never provided for.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-377","question":"An asset costing ₹10,00,000 (10-year life, nil residual) was written down at the end of year 2 to its recoverable amount of ₹6,00,000 and then depreciated over the remaining 8 years. At the end of year 4 its recoverable amount is ₹6,50,000. What impairment reversal is recognised?","options":["₹2,00,000","₹50,000","₹1,50,000","₹2,50,000"],"answer":2,"explanation":"Carrying amount at end of year 4 = 6,00,000 − 2 × 75,000 = ₹4,50,000. The reversal is capped at the carrying amount had no impairment occurred (10,00,000 − 4,00,000 = ₹6,00,000), so only ₹1,50,000 is reversed, not ₹2,00,000.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-378","question":"Using a provision matrix for trade receivables under Ind AS 109: not yet due ₹5,00,000 (1% loss rate), 1-30 days past due ₹2,00,000 (3%), 31-60 days ₹1,00,000 (10%), over 60 days ₹50,000 (40%). What is the loss allowance?","options":["₹42,500","₹20,000","₹41,000","₹36,000"],"answer":2,"explanation":"5,000 + 6,000 + 10,000 + 20,000 = ₹41,000 under the simplified lifetime expected-credit-loss approach. ₹42,500 applies a flat 5%; ₹36,000 leaves out the not-yet-due bucket.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-379","question":"A company holds equity shares in a strategic partner, not held for trading, and wants fair-value changes kept out of profit or loss. How can it account for them under Ind AS 109?","options":["At amortised cost","At FVOCI, with gains recycled to P&L on sale","At FVTPL only; no alternative exists","At FVOCI by an irrevocable election on initial recognition, with gains never recycled to P&L"],"answer":3,"explanation":"Equity instruments fail the cash-flow (SPPI) test, so amortised cost is impossible; FVTPL is the default, but an irrevocable FVOCI election is available for non-trading equity, and amounts in OCI are never recycled (only transferable within equity).","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-380","question":"6,000 kg of material are bought at ₹24 a kg against a standard of ₹25; 5,000 kg are used in the period. If the price variance is isolated at the time of purchase, what is it?","options":["₹6,000 favourable","₹5,000 favourable","₹6,000 adverse","₹1,000 favourable"],"answer":0,"explanation":"At the point of purchase the variance covers all quantities bought: 6,000 × (25 − 24) = ₹6,000 F, and stock is then carried at standard. ₹5,000 F is the figure if computed at the point of usage.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-381","question":"Full capacity is 10,000 units. Variable cost is ₹30 a unit and fixed costs ₹1,00,000. A semi-variable cost is ₹1,80,000 at 60% capacity and ₹2,20,000 at 80%. What is the total budgeted cost at 90% capacity?","options":["₹6,40,000","₹6,10,000","₹5,50,000","₹5,80,000"],"answer":1,"explanation":"The semi-variable cost rises ₹40,000 per 20%, i.e., ₹2,000 per 1%, so at 90% it is ₹2,40,000. Total = 2,70,000 variable + 2,40,000 + 1,00,000 = ₹6,10,000. ₹6,40,000 treats the semi-variable cost as wholly variable.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-382","question":"Sales are ₹20 lakh, the P/V ratio 30% and fixed costs ₹4.5 lakh. If sales rise by 10% with no change in prices or costs, by what percentage does profit rise?","options":["10%","30%","25%","40%"],"answer":3,"explanation":"Profit = 6 − 4.5 = ₹1.5 lakh; extra contribution = 30% × 2 lakh = ₹60,000, a 40% rise. Equivalently, margin of safety is 25%, so operating leverage = 1/0.25 = 4 and 4 × 10% = 40%.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-383","question":"Under the Conceptual Framework for Financial Reporting under Ind AS, how many of these are enhancing (not fundamental) qualitative characteristics: comparability, relevance, verifiability, timeliness, faithful representation, understandability?","options":["2","4","3","5"],"answer":1,"explanation":"Relevance and faithful representation are the two fundamental characteristics; comparability, verifiability, timeliness and understandability are the four enhancing ones.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-384","question":"Stock at the date of a fire is ₹3,00,000 and salvage is worth ₹40,000. The stock is insured for ₹2,10,000 under a policy with an average clause. What claim is admissible?","options":["₹1,82,000","₹2,10,000","₹2,60,000","₹1,54,000"],"answer":0,"explanation":"Loss = 3,00,000 − 40,000 = ₹2,60,000; under-insured, so claim = 2,60,000 × 2,10,000/3,00,000 = ₹1,82,000. ₹1,54,000 deducts salvage twice.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-385","question":"A retiring partner (1/4 share) has a capital of ₹1,00,000. The general reserve is ₹60,000, revaluation shows a loss of ₹20,000, goodwill is valued at ₹80,000, his share of profit to the date of retirement is ₹12,000 and his drawings are ₹8,000. How much is due to him?","options":["₹1,44,000","₹1,14,000","₹1,34,000","₹1,42,000"],"answer":2,"explanation":"1,00,000 + 15,000 (reserve) − 5,000 (revaluation loss) + 20,000 (goodwill) + 12,000 − 8,000 = ₹1,34,000. ₹1,44,000 treats the revaluation loss as a gain; ₹1,14,000 leaves out goodwill.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-386","question":"What is the correct order of the five steps of revenue recognition under Ind AS 115?","options":["Identify contract → identify performance obligations → determine price → allocate price → recognise revenue","Identify contract → determine price → identify performance obligations → allocate price → recognise revenue","Identify performance obligations → identify contract → determine price → allocate price → recognise revenue","Determine price → identify contract → allocate price → identify performance obligations → recognise revenue"],"answer":0,"explanation":"The model runs: contract, distinct performance obligations, transaction price, allocation on relative stand-alone selling prices, then recognition as each obligation is satisfied. The obligations must be known before the price can be allocated to them.","difficulty":"moderate","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-387","question":"A major component of a machine is replaced for ₹2,00,000. The old component, with a carrying amount of ₹30,000, is scrapped with no proceeds. How does Ind AS 16 treat this?","options":["Expense ₹2,00,000 as repairs","Capitalise ₹2,00,000 and derecognise the old part, charging ₹30,000 to P&L","Capitalise ₹2,00,000 and keep the old component in the asset","Capitalise ₹1,70,000 net of the old part"],"answer":1,"explanation":"A replacement that meets the recognition criteria is capitalised and the carrying amount of the replaced part is derecognised, with the ₹30,000 loss in P&L. Keeping both would double-count the component.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-388","question":"A machine costing ₹9,00,000 (residual ₹60,000) was expected to produce 1,20,000 units; 30,000 were made in year 1. At the start of year 2 the total expected output is revised to 1,00,000 units (including year 1). Year 2 output is 25,000 units. What is year 2's depreciation?","options":["₹2,10,000","₹1,75,000","₹2,46,429","₹2,25,000"],"answer":3,"explanation":"Year 1 charge = 8,40,000 × 30/120 = ₹2,10,000, leaving ₹6,90,000 with 70,000 units to go; year 2 = (6,90,000 − 60,000) × 25/70 = ₹2,25,000. ₹2,46,429 ignores residual value; ₹2,10,000 re-applies the new estimate to the original cost.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-389","question":"Net profit before these corrections is ₹2,00,000: (a) closing stock was overcast by ₹6,000; (b) a purchase invoice of ₹9,000 was not recorded, though the goods are in closing stock; (c) wages of ₹12,000 for installing a new machine were debited to Wages (machinery depreciated at 10% for a full year); (d) the proprietor's personal life insurance of ₹4,000 was debited to Insurance. What is the corrected profit?","options":["₹2,01,000","₹1,99,800","₹2,08,800","₹1,91,800"],"answer":1,"explanation":"2,00,000 − 6,000 − 9,000 + 12,000 − 1,200 (depreciation on capitalised wages) + 4,000 (drawings, not expense) = ₹1,99,800. Forgetting the depreciation gives ₹2,01,000.","difficulty":"very-hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-390","question":"An investor holds 1,000 shares bought for ₹1,20,000 and receives a 1-for-4 bonus issue. He then sells 500 shares at ₹110 each. Using average cost, what is the profit or loss on sale?","options":["Loss ₹5,000","Profit ₹25,000","Profit ₹7,000","Profit ₹55,000"],"answer":2,"explanation":"Bonus shares cost nothing but lower the average: 1,20,000/1,250 = ₹96 a share; profit = 500 × (110 − 96) = ₹7,000. Using the old ₹120 cost gives a ₹5,000 loss; selling the free shares first is not average cost.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-391","question":"Under Ind AS 8, how many of these are changes in accounting estimates (applied prospectively)? (1) Revising an asset's useful life (2) Changing the depreciation method from WDV to SLM (3) Changing the inventory cost formula from FIFO to weighted average (4) Changing the percentage of the provision for doubtful debts","options":["3","2","4","1"],"answer":0,"explanation":"Useful life, depreciation method (per Ind AS 16) and doubtful-debt percentages are estimates. Changing the cost formula for inventory is a change in accounting policy, applied retrospectively.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-392","question":"Profit after tax is ₹18 lakh and preference dividend ₹3 lakh. Equity capital is ₹50 lakh, reserves ₹25 lakh and preference capital ₹30 lakh. What is the return on equity shareholders' funds?","options":["17.1%","24%","20%","14.3%"],"answer":2,"explanation":"Profit for equity = 18 − 3 = ₹15 lakh over equity funds of 50 + 25 = ₹75 lakh = 20%. 24% forgets the preference dividend; 14.3% wrongly adds preference capital to equity funds.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-393","question":"For a dealer whose business is trading in securities, how are purchases and sales of securities held for dealing classified in the cash-flow statement?","options":["Investing activities","Operating activities","Financing activities","Excluded as non-cash"],"answer":1,"explanation":"Securities held for dealing are like inventory for a dealer, so cash flows from buying and selling them are operating. For other businesses such investments would be investing.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-394","question":"A business has assets of ₹5,00,000 and liabilities of ₹2,00,000. It then (i) sells goods costing ₹40,000 for ₹55,000 on credit, (ii) pays a creditor of ₹30,000 in full settlement with a discount of ₹1,000, (iii) the owner takes goods costing ₹5,000 for personal use, and (iv) interest of ₹2,000 accrues on a loan. What are total assets now?","options":["₹4,80,000","₹4,81,000","₹4,86,000","₹5,10,000"],"answer":1,"explanation":"Assets: 5,00,000 + 55,000 − 40,000 − 29,000 − 5,000 = ₹4,81,000 (accrued interest changes liabilities, not assets). Check: liabilities ₹1,72,000 and capital ₹3,09,000. ₹4,80,000 ignores the discount.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-395","question":"How many of these are capital expenditure? (1) Legal fees paid to acquire land (2) A large advertising campaign for a product launch (3) Interest on a loan taken to build a factory, for the construction period (4) Repairs to a second-hand machine before it is first used (5) Insurance of a machine after it is installed and working","options":["2","4","5","3"],"answer":3,"explanation":"Items 1, 3 (borrowing cost of a qualifying asset) and 4 (needed to make the asset ready for use) are capital. Advertising cannot be capitalised under Ind AS, and insurance after installation is a running cost.","difficulty":"hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-396","question":"Goods costing ₹10,000, on which input GST of ₹1,800 had been claimed, are distributed as free samples. What journal entry is passed?","options":["Dr Advertisement ₹10,000; Cr Purchases ₹10,000","Dr Advertisement ₹11,800; Cr Purchases ₹10,000, Cr Input GST ₹1,800","Dr Drawings ₹11,800; Cr Purchases ₹11,800","Dr Advertisement ₹11,800; Cr Sales ₹11,800"],"answer":1,"explanation":"Input tax credit is blocked on goods given as free samples, so the ₹1,800 credit is reversed and becomes part of the advertisement cost. The goods are removed from purchases at cost, not shown as sales.","difficulty":"hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-397","question":"A firm holds 1,000 units costing ₹70 each. 600 units are covered by a firm sales contract at ₹80; the general market price (NRV) for the rest is ₹60. Selling costs are nil. At what amount is inventory carried under Ind AS 2?","options":["₹66,000","₹70,000","₹60,000","₹72,000"],"answer":0,"explanation":"NRV of stock held for firm contracts is based on the contract price: 600 units at cost ₹70 (below ₹80) and 400 units at NRV ₹60: 42,000 + 24,000 = ₹66,000. Valuing all at the market NRV gives ₹60,000.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-398","question":"A guarantees to the firm that its profit will be at least ₹1,00,000, any shortfall to be borne by him alone. Partners A, B and C share profits 2 : 2 : 1. The actual profit is ₹80,000. How much does A finally get?","options":["₹32,000","₹40,000","₹20,000","₹12,000"],"answer":2,"explanation":"The firm's profit is made up to ₹1,00,000 and shared 40,000 : 40,000 : 20,000; A then bears the ₹20,000 shortfall, so A gets ₹20,000. ₹32,000 is A's share of ₹80,000 without the guarantee.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-399","question":"On dissolution, cash available after realising assets is ₹2,00,000. Creditors are ₹1,20,000, A has given the firm a loan of ₹30,000, and the capitals are A ₹60,000 and B ₹40,000 (profits shared equally; both solvent). How much does B receive in the final settlement?","options":["₹20,000","₹25,000","₹10,000","₹15,000"],"answer":3,"explanation":"Creditors, then A's loan, are paid first, leaving ₹50,000 for capitals of ₹1,00,000. The ₹50,000 loss is shared equally (profit ratio), so B gets 40,000 − 25,000 = ₹15,000. ₹20,000 wrongly splits the loss in capital ratio.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-400","question":"A company must redeem ₹5,00,000 of preference shares at par. It will use ₹2,00,000 of its general reserve and make a fresh issue of equity shares of ₹10 each at ₹12.50 for the rest of the capital requirement. How many equity shares must it issue?","options":["24,000","30,000","40,000","20,000"],"answer":1,"explanation":"Nominal value redeemed must be covered by CRR (₹2,00,000 from reserve) or the face value of a fresh issue, so face value needed is ₹3,00,000 = 30,000 shares. Premium does not count, so dividing by ₹12.50 (24,000) is the trap.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-401","question":"Under Schedule III to the Companies Act, 2013, how many of these are correctly placed? (1) Unpaid dividend — other current liabilities (2) Calls in arrears — deducted from subscribed capital (3) Securities premium — other equity (4) Share application money pending allotment — trade payables","options":["4","2","3","1"],"answer":2,"explanation":"1, 2 and 3 are right. Share application money pending allotment (within the allotment period) is shown as a separate line in equity, not as a trade payable.","difficulty":"hard","source":"CA Inter level · Big 4"},
  {"id":"mgmt-accounting-402","question":"H pays ₹8,00,000 for 75% of S, whose identifiable net assets have a fair value of ₹9,00,000. H measures NCI at its fair value of ₹2,40,000. What goodwill arises under Ind AS 103?","options":["₹1,25,000","₹1,66,667","₹1,40,000","₹3,40,000"],"answer":2,"explanation":"Full-goodwill method: consideration 8,00,000 + NCI 2,40,000 − net assets 9,00,000 = ₹1,40,000. ₹1,25,000 is the proportionate-share method; ₹1,66,667 just grosses it up to 100%.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-403","question":"H's books show ₹50,000 receivable from its subsidiary S, but S's books show only ₹42,000 payable to H because S posted a cheque of ₹8,000 on 30 March that H received on 3 April. What is the consolidation adjustment?","options":["Eliminate ₹50,000 from receivables and ₹42,000 from payables; recognise ₹8,000 cash in transit","Eliminate ₹42,000 from both receivables and payables only","Eliminate ₹50,000 from both receivables and payables","Write off the ₹8,000 difference to consolidated profit"],"answer":0,"explanation":"First bring the cash in transit into the group (Dr Cash ₹8,000, Cr H's receivable), then cancel the matched balances of ₹42,000. Net effect: receivables down ₹50,000, payables down ₹42,000, cash up ₹8,000.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-404","question":"On 1 January a gym signs a member for one year at ₹12,000 plus a non-refundable joining fee of ₹3,000 that gives no separate service. The gym's year ends on 31 March. What revenue does it recognise to 31 March under Ind AS 115?","options":["₹6,000","₹3,000","₹15,000","₹3,750"],"answer":3,"explanation":"The joining fee is not a distinct service, so it is part of the price for the membership and recognised over the membership year: (12,000 + 3,000) × 3/12 = ₹3,750. Taking the fee upfront gives ₹6,000.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-405","question":"A company has a tax loss of ₹10 lakh that can be carried forward; the tax rate is 25%. It is probable that only ₹6 lakh of future taxable profit will be available to use it. What deferred tax asset is recognised under Ind AS 12?","options":["₹2.5 lakh","₹1.5 lakh","Nil","₹1 lakh"],"answer":1,"explanation":"A DTA on unused losses is recognised only to the extent probable future taxable profit is available: 25% × 6 lakh = ₹1.5 lakh. ₹2.5 lakh recognises the full loss.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-406","question":"A company reports a loss from continuing operations and has share options outstanding whose exercise would increase the number of shares. How is diluted loss per share computed under Ind AS 33?","options":["Including the options, which lowers the loss per share","By averaging basic and diluted figures","Diluted equals basic, because the options are anti-dilutive","It is not presented when there is a loss"],"answer":2,"explanation":"Potential shares are dilutive only if they lower EPS or raise loss per share. Adding shares to a loss reduces the loss per share, so they are anti-dilutive and ignored; diluted loss per share equals basic.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-407","question":"A company has total assets of ₹25 lakh, current liabilities of ₹5 lakh and a debt-equity ratio (long-term debt to equity) of 1.5 : 1. What are its shareholders' funds?","options":["₹10 lakh","₹12 lakh","₹13.3 lakh","₹8 lakh"],"answer":3,"explanation":"Long-term funds = 25 − 5 = ₹20 lakh = debt + equity = 2.5 × equity, so equity = ₹8 lakh and debt ₹12 lakh. ₹10 lakh divides total assets by 2.5 without removing current liabilities.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-408","question":"A company's EPS is ₹8, its P/E ratio 15 and its payout ratio 40%. What is its dividend yield?","options":["2.67%","6.67%","40%","4%"],"answer":0,"explanation":"Price = 8 × 15 = ₹120; dividend = 40% × 8 = ₹3.20; yield = 3.20/120 = 2.67%. 6.67% is the earnings yield (8/120).","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-409","question":"In a year with an average workforce of 1,000, 50 workers left; 40 were hired to replace leavers and 30 more for an expansion. What is the labour turnover rate by the flux method (separations plus all accessions)?","options":["12%","9%","5%","4%"],"answer":0,"explanation":"Flux method = (separations + accessions)/average workforce = (50 + 70)/1,000 = 12%. 9% counts only replacement hires; 5% is the separation method and 4% the replacement method.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-410","question":"10,000 kg of material are bought at ₹50 a kg less 10% trade discount, plus GST at 18% (input credit available), freight ₹9,000 and transit insurance ₹1,500. A normal transit loss of 5% occurs. What is the cost per kg of good material received?","options":["₹46.05","₹57.00","₹48.47","₹50.00"],"answer":2,"explanation":"Cost = 4,50,000 + 9,000 + 1,500 = ₹4,60,500 (recoverable GST excluded), spread over 9,500 good kg = ₹48.47. Dividing by 10,000 kg (₹46.05) ignores that normal loss is absorbed by good units.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-411","question":"Budgeted hours are 10,000; actual hours worked 9,000; standard hours for actual output 9,900. What is the activity (production volume) ratio?","options":["110%","90%","91%","99%"],"answer":3,"explanation":"Activity ratio = standard hours for actual output / budgeted hours = 9,900/10,000 = 99%. Efficiency ratio is 9,900/9,000 = 110% and capacity ratio 9,000/10,000 = 90%.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-412","question":"Product Z shows a loss of ₹20,000 after charging ₹60,000 of apportioned fixed costs, of which only ₹15,000 would be saved if Z were dropped. What is the effect on total profit of dropping Z?","options":["Profit falls by ₹25,000","Profit rises by ₹20,000","Profit falls by ₹40,000","Profit rises by ₹15,000"],"answer":0,"explanation":"Z's contribution = −20,000 + 60,000 = ₹40,000; dropping it loses that and saves ₹15,000, so profit falls by ₹25,000. 'Rises by ₹20,000' trusts the full-cost loss figure.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-413","question":"Fixed costs are ₹5,00,000 a year, including depreciation of ₹1,00,000. Contribution is ₹40 a unit. What is the cash break-even point?","options":["12,500 units","15,000 units","10,000 units","2,500 units"],"answer":2,"explanation":"Cash break-even ignores non-cash fixed costs: (5,00,000 − 1,00,000)/40 = 10,000 units. 12,500 units is the ordinary break-even point.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-414","question":"The cash book shows an overdraft of ₹25,000. Cheques issued ₹6,000 are unpresented, cheques deposited ₹4,000 are uncleared and the bank has debited overdraft interest of ₹1,200 not in the cash book. What is the overdraft per the pass book?","options":["₹28,200","₹24,200","₹21,800","₹26,200"],"answer":1,"explanation":"Starting from the overdraft: unpresented cheques make the bank overdraft smaller (−6,000), uncleared deposits make it larger (+4,000), and interest makes it larger (+1,200): ₹24,200. ₹28,200 reverses the cheque adjustments.","difficulty":"hard","source":"Bank MT · IBPS SO"},
  {"id":"mgmt-accounting-415","question":"A company spends ₹5 lakh on research, ₹3 lakh on development before the Ind AS 38 recognition criteria are met, and ₹7 lakh on development after they are met. What is capitalised as an intangible asset?","options":["₹7 lakh","₹10 lakh","₹15 lakh","Nil"],"answer":0,"explanation":"Research is always expensed, and development costs are capitalised only from the date all the criteria (feasibility, intention, ability, future benefits, resources, measurability) are met; earlier development spending cannot be reinstated. So ₹7 lakh.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-416","question":"Under Ind AS 38, an intangible asset with an indefinite useful life (such as a perpetual licence) is:","options":["Not amortised, but tested for impairment annually and whenever there is an indication","Amortised over a maximum of 10 years","Amortised over 20 years and tested for impairment","Written off immediately on acquisition"],"answer":0,"explanation":"Indefinite does not mean infinite, but no foreseeable limit exists, so no amortisation is charged; instead the asset is tested for impairment each year and its indefinite-life assessment is reviewed.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-417","question":"A government grant of 20% is received towards a ₹10,00,000 machine with a 5-year life and nil residual value. Under Ind AS 20, using the deferred-income approach, what is the net annual effect on profit?","options":["₹2,00,000 charge","₹40,000 credit","₹2,40,000 charge","₹1,60,000 charge"],"answer":3,"explanation":"Depreciation ₹2,00,000 is charged and ₹40,000 of deferred grant income is released each year, a net ₹1,60,000 charge, the same net effect as deducting the grant from the asset.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-418","question":"Operating expenses in the P&L are ₹3,00,000, including depreciation of ₹40,000. Prepaid expenses rose by ₹5,000 and outstanding expenses rose by ₹8,000. Under the direct method, what cash was paid for operating expenses?","options":["₹2,63,000","₹2,97,000","₹2,57,000","₹2,73,000"],"answer":2,"explanation":"Cash = 3,00,000 − 40,000 (non-cash) + 5,000 (paid in advance) − 8,000 (not yet paid) = ₹2,57,000. ₹2,63,000 reverses the two working-capital adjustments.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-419","question":"Tax expense in the P&L is ₹1,50,000: current tax ₹1,20,000 and deferred tax ₹30,000. The current tax payable was ₹40,000 at the start of the year and ₹25,000 at the end. How much income tax was paid?","options":["₹1,65,000","₹1,05,000","₹1,50,000","₹1,35,000"],"answer":3,"explanation":"Only current tax is settled in cash: 40,000 + 1,20,000 − 25,000 = ₹1,35,000. Deferred tax is a non-cash item, so using total expense gives the wrong ₹1,65,000.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-420","question":"Partner A has a fixed capital of ₹2,00,000 and a current account opening credit of ₹15,000. For the year: interest on capital 10%, salary ₹24,000, share of profit ₹36,000, drawings ₹30,000 and interest on drawings ₹1,500. What is the closing balance of A's current account?","options":["₹2,63,500","₹66,500","₹33,500","₹63,500"],"answer":3,"explanation":"15,000 + 20,000 + 24,000 + 36,000 − 30,000 − 1,500 = ₹63,500 credit. Under fixed capitals all these items go to the current account; ₹2,63,500 merges it with capital, as under fluctuating capitals.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-421","question":"A company gives an employee an interest-free loan of ₹1,00,000, repayable in one sum after 2 years; the market rate is 10%. Under Ind AS 109, at what amount is the loan initially recognised, and how is the difference treated?","options":["₹1,00,000; no difference arises","₹82,645; ₹17,355 treated as an employee benefit (prepaid)","₹90,909; ₹9,091 charged to interest expense","₹82,645; ₹17,355 credited to income"],"answer":1,"explanation":"Financial assets start at fair value: 1,00,000/1.1² = ₹82,645. The ₹17,355 given up is a benefit to the employee, recognised as a prepaid employee cost and expensed over the loan term, while interest income unwinds on the loan.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-422","question":"A physical count on 31 March values stock at ₹4,00,000. It excludes goods costing ₹30,000 lying with a consignee and goods costing ₹20,000 bought FOB shipping point that are still in transit. It includes ₹15,000 of goods sold whose control has passed to the customer (held for him) and ₹10,000 of goods received on consignment from another firm. What is the correct closing stock?","options":["₹4,05,000","₹4,25,000","₹4,40,000","₹4,35,000"],"answer":1,"explanation":"Add goods owned but not counted (30,000 + 20,000) and remove goods counted but not owned (15,000 + 10,000): ₹4,25,000. ₹4,05,000 forgets the FOB shipping-point goods, which belong to the buyer once shipped.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-423","question":"Under Ind AS 116, a contract gives a customer the use of 'any 10 trucks' from a supplier's fleet; the supplier can substitute trucks at any time without the customer's approval and benefits economically from doing so. Does the contract contain a lease?","options":["Yes, because the customer uses the trucks for the whole term","Yes, but only if the term exceeds 12 months","No, because trucks are low-value assets","No, because there is no identified asset when the supplier has a substantive substitution right"],"answer":3,"explanation":"A lease needs an identified asset; a substantive substitution right (practical ability to swap and economic benefit from doing so) means the customer does not control a specific asset, so it is a service contract.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-424","question":"Machinery of ₹50,000 bought on credit from X on 1 October was entered in the purchases book. The year ends on 31 March and machinery is depreciated at 15% a year. What is the effect of the error on the year's profit?","options":["Understated by ₹50,000","Overstated by ₹46,250","Understated by ₹46,250","Understated by ₹53,750"],"answer":2,"explanation":"₹50,000 of capital spending was charged as purchases, understating profit by ₹50,000, but half a year's depreciation (₹3,750) was also missed, so the net understatement is ₹46,250.","difficulty":"hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-425","question":"Machinery had a WDV of ₹5,00,000 on 1 April 2023. A new machine costing ₹2,00,000 was bought on 1 October 2023, and on 1 January 2024 a machine whose WDV on 1 April 2023 was ₹80,000 was sold. Depreciation is 10% WDV, on a time basis. What is the total depreciation for 2023-24?","options":["₹68,000","₹58,000","₹52,000","₹70,000"],"answer":1,"explanation":"Remaining old machines 4,20,000 × 10% = 42,000; new machine 2,00,000 × 10% × 6/12 = 10,000; sold machine 80,000 × 10% × 9/12 = 6,000; total ₹58,000. ₹52,000 forgets depreciation on the machine sold.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-426","question":"Closing stock on 31 March 2024 was overstated by ₹20,000, and the error was never corrected. Which statement is correct?","options":["2023-24 profit is overstated and 2024-25 profit is also overstated by ₹20,000","Only 2023-24 profit is affected; 2024-25 is unaffected","Retained earnings at 31 March 2025 are overstated by ₹40,000","2023-24 profit is overstated and 2024-25 profit understated by ₹20,000; retained earnings at 31 March 2025 are correct"],"answer":3,"explanation":"The overstated closing stock becomes next year's overstated opening stock, raising next year's COGS. The error reverses itself, so cumulative profit (retained earnings) is right by the end of the second year.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-427","question":"A loan of ₹2,00,000 at 12% a year was taken on 1 July. Interest of ₹12,000 has been paid by the year end on 31 March. What is the interest charged to profit and loss and the interest outstanding?","options":["P&L ₹18,000; outstanding ₹6,000","P&L ₹24,000; outstanding ₹12,000","P&L ₹12,000; outstanding nil","P&L ₹18,000; outstanding ₹18,000"],"answer":0,"explanation":"Interest accrues only for 9 months: 2,00,000 × 12% × 9/12 = ₹18,000, of which ₹12,000 is paid, leaving ₹6,000 outstanding. ₹24,000 charges a full year.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-428","question":"A and B share profits 3 : 2. C is admitted for a 1/5 share, taken from A and B in their old ratio. Firm goodwill is ₹1,00,000. C brings capital of ₹1,00,000 and only ₹10,000 of his goodwill share in cash; the rest is debited to his current account. What total amount is credited to A for goodwill?","options":["₹6,000","₹12,000","₹10,000","₹20,000"],"answer":1,"explanation":"C's goodwill share = 1/5 × 1,00,000 = ₹20,000 (₹10,000 in cash + ₹10,000 to his current account), shared by A and B 3 : 2, so A gets ₹12,000. ₹6,000 counts only the cash part.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-429","question":"A partner with a 1/4 share dies on 30 September. Last year the firm's sales were ₹20 lakh and profit ₹3 lakh. Sales from 1 April to 30 September this year are ₹12 lakh. His share of profit to the date of death is computed on the sales basis. What is it?","options":["₹37,500","₹75,000","₹45,000","₹1,80,000"],"answer":2,"explanation":"Last year's profit rate = 3/20 = 15% of sales; profit to death = 15% × 12 lakh = ₹1,80,000; his 1/4 = ₹45,000. ₹37,500 is the time basis (half of last year's profit × 1/4).","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-430","question":"A, B and C (ratio 2 : 2 : 1) have capitals of ₹40,000, ₹30,000 and ₹10,000. In piecemeal distribution by the maximum-loss method, the first ₹30,000 available to partners is distributed. How much does B receive?","options":["₹11,250","₹12,000","₹15,000","₹10,000"],"answer":3,"explanation":"Maximum possible loss = 80,000 − 30,000 = ₹50,000, borne 20,000 : 20,000 : 10,000, leaving A ₹20,000, B ₹10,000, C nil (total ₹30,000). ₹12,000 shares the cash in profit ratio; ₹11,250 in capital ratio.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-431","question":"A company has 1,00,000 equity shares of ₹10 each, ₹8 paid up, with general reserve ₹5,00,000 and securities premium ₹3,00,000 (collected in cash). It wants to make the shares fully paid and then issue fully paid bonus shares 1 for 4. Which use of reserves is permitted?","options":["Partly paid shares made fully paid from securities premium ₹2,00,000; bonus from general reserve ₹2,50,000","Partly paid shares made fully paid from general reserve ₹2,00,000; bonus from securities premium ₹2,50,000","Both made from securities premium ₹4,50,000","Neither can use reserves; a fresh call is required"],"answer":1,"explanation":"Securities premium may be used only for issuing fully paid bonus shares, not for paying up partly paid shares, which needs free reserves such as general reserve. So general reserve covers the ₹2 call (₹2,00,000) and premium funds the bonus (₹2,50,000).","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-432","question":"10% debentures of ₹5,00,000 are issued on 1 July, with interest payable on 31 December and 30 June. The year ends on 31 March. What is the interest expense for the year and the interest accrued at year end?","options":["₹50,000 expense; ₹12,500 accrued","₹25,000 expense; ₹12,500 accrued","₹37,500 expense; ₹12,500 accrued","₹37,500 expense; ₹25,000 accrued"],"answer":2,"explanation":"Expense is for 9 months: 5,00,000 × 10% × 9/12 = ₹37,500. ₹25,000 is paid on 31 December, so January-March interest of ₹12,500 is accrued.","difficulty":"moderate","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-433","question":"A company using the cost model wants to revalue one of its office buildings, which has risen sharply in value. Under Ind AS 16, what must it do?","options":["Revalue that building only","Revalue the entire class of office buildings and keep revaluations regular","Revalue all property, plant and equipment of every class","Revalue it only if it plans to sell it within a year"],"answer":1,"explanation":"Revaluation is applied to an entire class of assets to avoid selective revaluation, and must be done regularly enough that carrying amounts do not differ materially from fair value. Other classes may stay on the cost model.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-434","question":"An asset's decommissioning obligation was recognised at its present value of ₹1,00,000 using an 8% discount rate. Ignoring changes in estimates, what is the finance cost (unwinding of discount) in year 2?","options":["₹8,000","₹16,000","₹9,331","₹8,640"],"answer":3,"explanation":"Year 1 unwinding = ₹8,000, taking the provision to ₹1,08,000; year 2 = 8% × 1,08,000 = ₹8,640, charged as finance cost. Repeating ₹8,000 forgets that the discount compounds.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-435","question":"A manufacturer delivers cars to a dealer under an arrangement where the dealer can return unsold cars at any time and the manufacturer can require their return or transfer to another dealer. Under Ind AS 115, when is revenue recognised?","options":["When the dealer sells the cars to end customers","On delivery to the dealer","When the dealer pays a deposit","At the end of the agreement period"],"answer":0,"explanation":"This is a consignment arrangement: control has not passed to the dealer, who does not have to pay and can return the cars. Revenue is recognised only when the cars are sold to third parties.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-436","question":"Products A, B and C, with stand-alone selling prices of ₹40,000, ₹35,000 and ₹25,000, are sold together for ₹90,000. No evidence links the discount to any one product. Under Ind AS 115, how much revenue is allocated to B?","options":["₹35,000","₹31,500","₹25,000","₹31,667"],"answer":1,"explanation":"The ₹10,000 discount is allocated in proportion to stand-alone prices: 90,000 × 35,000/1,00,000 = ₹31,500. Splitting the discount equally gives ₹31,667.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-437","question":"A company had 10,00,000 shares on 1 April. It bought back 1,00,000 shares on 1 October and issued 2,00,000 new shares for cash on 1 January. Profit for the year to 31 March is ₹75,00,000. What is basic EPS?","options":["₹6.82","₹8.33","₹7.50","₹7.89"],"answer":2,"explanation":"Weighted shares = 10,00,000 − 1,00,000 × 6/12 + 2,00,000 × 3/12 = 10,00,000 (the two effects cancel), so EPS = ₹7.50. Using year-end shares (11,00,000) gives ₹6.82.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-438","question":"How many of these give rise to a deferred tax ASSET? (1) A warranty provision, tax-deductible only when paid (2) Tax depreciation higher than book depreciation (3) Bonus payable, deductible only when paid (4) An upward revaluation of land, taxed only on sale (5) Unused tax losses expected to be used","options":["2","4","3","1"],"answer":2,"explanation":"1, 3 and 5 mean less tax in future (deductible temporary differences or losses), creating DTAs. Faster tax depreciation and untaxed revaluation gains are taxable temporary differences, creating DTLs.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-439","question":"A company buys a 3-year bond with face value ₹5,00,000 and a 6% annual coupon for ₹4,74,229, to hold to collect cash flows; the effective interest rate is 8%. What is its amortised cost at the end of year 1?","options":["₹4,82,167","₹4,74,229","₹5,00,000","₹5,12,167"],"answer":0,"explanation":"Interest income at EIR = 8% × 4,74,229 = 37,938; less coupon received 30,000 = carrying amount ₹4,82,167. The discount unwinds towards face value; ₹5,12,167 forgets to deduct the coupon.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-440","question":"Sales are ₹18 lakh with gross profit 20% of sales. Opening stock is ₹1.5 lakh and inventory turnover (on COGS and average stock) is 8 times. What are the purchases for the year?","options":["₹13.8 lakh","₹14.4 lakh","₹15.9 lakh","₹15.0 lakh"],"answer":3,"explanation":"COGS = ₹14.4 lakh; average stock = 1.8 lakh, so closing = 2.1 lakh; purchases = COGS + closing − opening = 14.4 + 2.1 − 1.5 = ₹15.0 lakh. ₹13.8 lakh reverses the stock adjustment; ₹15.9 lakh uses sales for turnover.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-441","question":"Under Ind AS 7, for a non-financial company, how many of these are investing cash flows? (1) Purchase of a subsidiary, net of cash acquired (2) Dividend received from a subsidiary (3) Principal portion of lease payments (4) Interest portion of lease payments (5) Purchase of software licences","options":["2","3","4","1"],"answer":1,"explanation":"1, 2 and 5 are investing (Ind AS 7 classifies dividends received as investing for non-financial entities). Lease principal and lease interest paid are financing.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-442","question":"A job uses materials ₹8,000 and 40 labour hours at ₹50. Factory overheads are 150% of direct labour, administration overheads 20% of works cost, and the firm wants a profit of 25% on the selling price. What is the selling price?","options":["₹19,500","₹17,333","₹15,600","₹20,800"],"answer":3,"explanation":"Works cost = 8,000 + 2,000 + 3,000 = 13,000; total cost = 15,600; 25% on selling price means cost is 75%: 15,600/0.75 = ₹20,800. ₹19,500 adds 25% on cost instead.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-443","question":"Credit sales in January are ₹2,00,000. 40% is collected in February with a 2% cash discount, 55% in March, and 5% proves bad. How much cash does the February cash budget show from January sales?","options":["₹78,400","₹80,000","₹1,10,000","₹76,000"],"answer":0,"explanation":"40% × 2,00,000 = ₹80,000 less the 2% discount = ₹78,400 received. Cash budgets record only cash actually expected, so the discount is deducted.","difficulty":"moderate","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-444","question":"12,000 kg of material costing ₹2,64,000 are used. The standard price is ₹20 a kg and the standard quantity for the actual output is 11,500 kg. What is the material cost variance?","options":["₹14,000 adverse","₹24,000 adverse","₹34,000 adverse","₹10,000 adverse"],"answer":2,"explanation":"Standard cost = 11,500 × 20 = 2,30,000; actual 2,64,000; MCV = ₹34,000 A, made up of price ₹24,000 A (paid ₹22 a kg) and usage ₹10,000 A.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-445","question":"Product P earns ₹60 contribution and uses 4 kg of material; Q earns ₹50 and uses 2 kg. Only 10,000 kg are available; maximum demand is 2,000 units of P and 3,000 of Q. What is the maximum total contribution?","options":["₹1,70,000","₹2,50,000","₹2,10,000","₹2,70,000"],"answer":2,"explanation":"Contribution per kg: P ₹15, Q ₹25, so make Q first: 3,000 units use 6,000 kg (₹1,50,000); the remaining 4,000 kg make 1,000 P (₹60,000): ₹2,10,000. Ranking by contribution per unit gives ₹1,70,000.","difficulty":"very-hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-446","question":"A firm's sales are ₹8,00,000, its profit ₹60,000 and its margin of safety ₹2,00,000. What are its fixed costs?","options":["₹2,40,000","₹1,80,000","₹1,20,000","₹60,000"],"answer":1,"explanation":"P/V ratio = profit/MoS = 60,000/2,00,000 = 30%. Break-even sales = 6,00,000, so fixed costs = 30% × 6,00,000 = ₹1,80,000 (check: 2,40,000 − 1,80,000 = 60,000).","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-447","question":"Opening WIP: 1,000 units, 60% converted (materials ₹10,000, conversion ₹6,000). 9,000 units are started (materials ₹1,00,000, conversion ₹74,000). Closing WIP: 2,000 units, 50% converted; materials are added at the start; no losses. Using weighted average, what is the value of closing WIP?","options":["₹31,032","₹39,778","₹22,000","₹30,889"],"answer":3,"explanation":"Equivalent units: materials 10,000, conversion 8,000 + 1,000 = 9,000. Rates: ₹11 and 80,000/9,000 = ₹8.889. WIP = 2,000 × 11 + 1,000 × 8.889 = ₹30,889. ₹31,032 is the FIFO answer; ₹39,778 treats WIP as fully converted.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-448","question":"A company incorporated on 1 August took over a business from 1 April; its first accounts run to 31 March. Gross profit is ₹6,00,000, with sales before and after incorporation in the ratio 1 : 3. Salaries of ₹1,20,000 accrued evenly. Ignoring other items, what is the pre-incorporation profit?","options":["₹1,10,000","₹1,60,000","₹1,20,000","₹1,50,000"],"answer":0,"explanation":"Gross profit splits on sales (1/4 = ₹1,50,000) and salaries on time (4/12 = ₹40,000): ₹1,10,000, a capital profit. Splitting gross profit by time gives ₹1,60,000.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-449","question":"Under Ind AS 2, how should a company choose cost formulas for its inventories?","options":["Any formula for each item, changed yearly to suit profit","FIFO for raw materials and LIFO for finished goods","The same cost formula for all inventories of similar nature and use; a different formula may be justified for inventories of different nature or use","Weighted average only"],"answer":2,"explanation":"Ind AS 2 requires the same formula for inventories of similar nature and use, though different formulas may suit different kinds. LIFO is not permitted at all.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-450","question":"A lessee's lease payments have a present value of ₹5,00,000. It also paid ₹20,000 before commencement, incurred initial direct costs of ₹10,000, received a lease incentive of ₹15,000 and must restore the site (present value ₹25,000). What is the initial right-of-use asset under Ind AS 116?","options":["₹5,70,000","₹5,15,000","₹5,00,000","₹5,40,000"],"answer":3,"explanation":"ROU asset = 5,00,000 + 20,000 + 10,000 − 15,000 + 25,000 = ₹5,40,000. Adding the incentive instead of deducting it gives ₹5,70,000; leaving out restoration gives ₹5,15,000.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-451","question":"Under Ind AS 36, which of these must be tested for impairment every year even when there is no indication of impairment?","options":["Goodwill and intangibles with indefinite lives or not yet available for use","All property, plant and equipment","Only assets held for sale","Inventories and receivables"],"answer":0,"explanation":"Goodwill, indefinite-life intangibles and intangibles not yet in use need an annual test; other assets are tested only when an indicator exists. Inventories fall under Ind AS 2 and receivables under Ind AS 109.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-452","question":"H holds 80% of S. H's own reserves are ₹10 lakh. S's reserves were ₹4 lakh at acquisition and are ₹7 lakh now. What are consolidated reserves?","options":["₹15.6 lakh","₹12.4 lakh","₹17 lakh","₹13 lakh"],"answer":1,"explanation":"Only the parent's share of post-acquisition reserves is added: 10 + 80% × (7 − 4) = ₹12.4 lakh. Pre-acquisition reserves go into goodwill and the NCI's 20% to NCI.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-453","question":"Match each practice with the concept it reflects. P. Creating a provision for doubtful debts  Q. Showing an annual premium paid in advance as prepaid  R. Not recording the value of a firm's skilled workforce  S. Treating the owner's capital as a claim against the business. Concepts: 1. Money measurement  2. Business entity  3. Prudence  4. Accrual/matching","options":["P-3, Q-4, R-1, S-2","P-4, Q-3, R-1, S-2","P-3, Q-4, R-2, S-1","P-3, Q-1, R-4, S-2"],"answer":0,"explanation":"Doubtful-debt provisions are prudence; prepaid expenses carry cost to the period it benefits (accrual/matching); unmeasurable human skills are excluded by money measurement; and the business is separate from its owner (entity), so capital is owed to him.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-454","question":"X underwrites an entire issue of 1,00,000 shares, including a firm underwriting of 10,000 shares. The public applies for 70,000 shares. Treating the firm underwriting like marked applications, how many shares in total does X take up?","options":["20,000","40,000","30,000","10,000"],"answer":2,"explanation":"Firm-underwritten shares count as applications, so the shortfall is 1,00,000 − (70,000 + 10,000) = 20,000; X takes those plus its firm 10,000 = 30,000 shares. 20,000 forgets the firm commitment.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-455","question":"A company buys 1,000 of its own ₹100 debentures in the market at ₹96 ex-interest and later cancels them. Where does the ₹4,000 gain on cancellation go?","options":["Credited to profit and loss as operating income","Credited to securities premium","Deducted from debenture interest","Transferred to capital reserve"],"answer":3,"explanation":"Profit on cancellation of own debentures is a capital profit and is transferred to capital reserve, not to the statement of profit and loss as trading income.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-456","question":"A machine was installed and ready for use on 1 October, but the company started using it in production only on 1 January. Under Ind AS 16, depreciation begins on:","options":["1 January, when production started","1 October, when it was available for use","The first day of the next financial year","The date the invoice was paid"],"answer":1,"explanation":"Depreciation starts when the asset is available for use, i.e., in the location and condition needed to operate as intended, even if it is not yet used. It does not stop merely because the asset is idle.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-457","question":"A building with a carrying amount of ₹8,00,000 is classified as held for sale under Ind AS 105. Its fair value less costs to sell is ₹7,20,000. What is the accounting?","options":["Recognise an impairment loss of ₹80,000 and stop depreciating it","Keep it at ₹8,00,000 and continue depreciating it","Write it down to ₹7,20,000 through OCI and keep depreciating","Recognise an impairment of ₹80,000 and continue depreciating"],"answer":0,"explanation":"Held-for-sale assets are measured at the lower of carrying amount and fair value less costs to sell, so ₹80,000 is charged to P&L; depreciation stops from the date of classification.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-458","question":"Gross profit is 25% of sales and stock turnover (on COGS and average stock) is 5 times. Closing stock is ₹1,00,000 and opening stock is 20% less than closing stock. What are the sales?","options":["₹5,62,500","₹6,66,667","₹4,50,000","₹6,00,000"],"answer":3,"explanation":"Opening = ₹80,000, so average = ₹90,000 and COGS = 5 × 90,000 = ₹4,50,000. With GP at 25% of sales, sales = 4,50,000/0.75 = ₹6,00,000. ₹5,62,500 treats 25% as a mark-up on cost.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-459","question":"Opening cash and cash equivalents are ₹50,000. Cash from operations is ₹3,20,000 and net investing outflow ₹2,40,000. During the year the company issued shares for ₹1,00,000, redeemed debentures of ₹80,000 at a 5% premium, paid interest of ₹30,000 and dividends of ₹60,000. What is the closing cash balance?","options":["₹60,000","₹56,000","₹86,000","₹1,16,000"],"answer":1,"explanation":"Financing = 1,00,000 − 84,000 − 30,000 − 60,000 = −₹74,000; closing = 50,000 + 3,20,000 − 2,40,000 − 74,000 = ₹56,000. ₹60,000 ignores the redemption premium.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-460","question":"A truck carries 6 tonnes for 100 km to town A, unloads 2 tonnes, carries 4 tonnes a further 50 km to town B, and returns empty over 150 km. How many commercial tonne-km are there?","options":["800","1,500","1,200","1,000"],"answer":3,"explanation":"Commercial tonne-km = average load × total distance = (6 + 4 + 0)/3 × 300 = 1,000. Absolute tonne-km sums each leg's load × distance: 600 + 200 = 800.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-461","question":"A joint cost of ₹1,20,000 yields 2,000 units of A, sold at ₹50 after further processing costing ₹20,000, and 3,000 units of B, sold at ₹30 after further processing costing ₹30,000. Using the net realisable value method, how much joint cost goes to A?","options":["₹63,158","₹68,571","₹48,000","₹60,000"],"answer":1,"explanation":"NRVs: A = 1,00,000 − 20,000 = 80,000; B = 90,000 − 30,000 = 60,000. A's share = 1,20,000 × 80/140 = ₹68,571. ₹63,158 uses final sales values; ₹48,000 uses physical units.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-462","question":"A material's reorder level is 6,000 units and its reorder quantity 5,000 units. Minimum usage is 400 units a day and the minimum lead time is 8 days. What is the maximum stock level?","options":["11,000 units","7,800 units","8,200 units","14,200 units"],"answer":1,"explanation":"Maximum level = reorder level + reorder quantity − (minimum usage × minimum lead time) = 6,000 + 5,000 − 3,200 = 7,800 units. 11,000 forgets the usage during the lead time.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-463","question":"Budgeted sales were 1,000 units at ₹100; actual sales were 1,100 units at ₹95. What is the sales volume variance (on sales value)?","options":["₹4,500 favourable","₹5,500 adverse","₹10,000 favourable","₹9,500 favourable"],"answer":2,"explanation":"Volume variance = (actual − budgeted quantity) × budgeted price = 100 × 100 = ₹10,000 F. The price variance is ₹5,500 A and the total sales value variance ₹4,500 F.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-464","question":"A firm has spare capacity of 3,000 units. An export order for 4,000 units at ₹70 (variable cost ₹55) needs extra fixed costs of ₹20,000, and 1,000 units of domestic sales at ₹90 would be given up. What is the effect of accepting it?","options":["Accept: profit rises by ₹40,000","Accept: profit rises by ₹25,000","Reject: profit falls by ₹50,000","Accept: profit rises by ₹5,000"],"answer":3,"explanation":"Contribution 4,000 × 15 = 60,000 − extra fixed 20,000 − lost domestic contribution 1,000 × 35 = ₹5,000 gain. Deducting lost domestic revenue instead of contribution gives the false ₹50,000 loss.","difficulty":"very-hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-465","question":"A company has 10,00,000 fully paid equity shares of ₹10 and 2,00,000 shares of ₹10 on which ₹5 is paid; partly paid shares share in dividends in proportion to the amount paid. Profit is ₹55,00,000. What is basic EPS under Ind AS 33?","options":["₹4.58","₹5.00","₹5.50","₹4.80"],"answer":1,"explanation":"Partly paid shares count as fractions to the extent they share in dividends: 2,00,000 × 5/10 = 1,00,000 equivalent shares; 55,00,000/11,00,000 = ₹5.00. Counting them in full gives ₹4.58.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-466","question":"A company guarantees a bank loan taken by an unrelated company. At year end the borrower is solvent and an outflow under the guarantee is possible but not probable. How is it treated under Ind AS 37?","options":["Recognise a provision for the full loan","Recognise a provision at 50% of the loan","Disclose it as a contingent liability","Ignore it completely"],"answer":2,"explanation":"A possible (not probable) obligation is a contingent liability: disclosed, not recognised. A provision would need a probable outflow and a reliable estimate; only remote outflows need no disclosure.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-467","question":"A company changes its inventory cost formula from FIFO to weighted average. At the start of the earliest period presented, inventory was ₹2,00,000 under FIFO and would have been ₹1,85,000 under weighted average. Ignoring tax, how does Ind AS 8 require this to be shown?","options":["Charge ₹15,000 in the current year's profit and loss","Apply weighted average prospectively with no adjustment","Credit ₹15,000 to OCI","Reduce opening retained earnings of the earliest period presented by ₹15,000 and restate comparatives"],"answer":3,"explanation":"A voluntary change in accounting policy is applied retrospectively: opening balances of the earliest period presented are adjusted (retained earnings down ₹15,000) and comparatives restated, as if weighted average had always been used.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-468","question":"A sole trader's car costing ₹5,00,000 is depreciated at 20% WDV; one-quarter of its use is private. What is charged to the business profit and loss account for the first year?","options":["₹75,000, with ₹25,000 treated as drawings","₹1,00,000","₹25,000, with ₹75,000 treated as drawings","₹75,000, with ₹25,000 written off to capital reserve"],"answer":0,"explanation":"Depreciation of ₹1,00,000 is split by use: 75% (₹75,000) is a business expense and 25% (₹25,000) is the proprietor's personal benefit, debited to drawings.","difficulty":"moderate","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-469","question":"In the current year it is found that last year's closing stock (this year's opening stock) was undercast by ₹5,000; the books for last year are closed. What is the effect on the current year's profit if not corrected?","options":["Understated by ₹5,000","No effect","Overstated by ₹5,000","Overstated by ₹10,000"],"answer":2,"explanation":"Opening stock is too low, so this year's cost of goods sold is too low and profit is overstated by ₹5,000 (last year's profit was understated by the same amount).","difficulty":"hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-470","question":"Opening stock 200 units at ₹10; purchases 800 units at ₹12.50; 100 of these units are returned to the supplier; 600 units are issued. Using periodic weighted average, what is the closing stock?","options":["₹3,750","₹3,583","₹4,000","₹3,600"],"answer":1,"explanation":"Net goods available: 900 units costing 2,000 + 700 × 12.50 = ₹10,750, average ₹11.944; closing 300 units = ₹3,583. ₹4,000 forgets to remove the cost of the returns; ₹3,750 is FIFO.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-471","question":"H acquired 75% of S, measuring NCI at its fair value of ₹2,40,000 at acquisition. Since then S has earned post-acquisition profits of ₹1,60,000 with no dividends. What is NCI in the consolidated balance sheet?","options":["₹2,40,000","₹3,60,000","₹2,80,000","₹4,00,000"],"answer":2,"explanation":"NCI = its value at acquisition + its share of post-acquisition changes: 2,40,000 + 25% × 1,60,000 = ₹2,80,000. ₹4,00,000 credits all post-acquisition profit to NCI.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-472","question":"An 80%-owned subsidiary pays a dividend of ₹1,00,000, which the parent records as income of ₹80,000. How is this treated on consolidation?","options":["Both the ₹80,000 income and ₹1,00,000 dividend stay in the consolidated statements","The ₹80,000 is eliminated against the subsidiary's dividend; the ₹20,000 paid to NCI reduces NCI","The full ₹1,00,000 is shown as a group dividend to the parent's shareholders","The ₹80,000 is transferred to capital reserve"],"answer":1,"explanation":"Intra-group dividends cancel: the parent's dividend income is eliminated against the subsidiary's distribution. Only the ₹20,000 paid outside the group remains, as a reduction of NCI.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-473","question":"Land is revalued upward by ₹10 lakh under Ind AS 16; the gain will be taxed only on sale and the tax rate is 25%. How is the deferred tax recorded?","options":["DTL ₹2.5 lakh charged to profit and loss; surplus ₹10 lakh","No deferred tax, since the land is not depreciated","DTA ₹2.5 lakh credited to OCI","DTL ₹2.5 lakh charged to OCI; revaluation surplus ₹7.5 lakh net"],"answer":3,"explanation":"The revaluation creates a taxable temporary difference, so a DTL of ₹2.5 lakh arises; deferred tax follows the item it relates to, so it is charged in OCI, leaving a net surplus of ₹7.5 lakh.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-474","question":"The head office's Branch account shows a debit balance of ₹2,00,000. At year end, ₹10,000 of cash sent by the branch and ₹15,000 of goods sent by the head office are in transit. Before any adjustment, what balance should the branch's Head Office account show?","options":["₹1,75,000 credit","₹2,25,000 credit","₹1,90,000 credit","₹1,85,000 credit"],"answer":0,"explanation":"Cash sent by the branch has already reduced its HO account, and goods in transit have not yet been credited there, so the branch shows 2,00,000 − 10,000 − 15,000 = ₹1,75,000. ₹2,25,000 adds the items instead.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-475","question":"A machine is bought on hire purchase with ₹20,000 down and four annual instalments of ₹30,000 at each year end; interest is 10% a year. What is the cash price?","options":["₹1,40,000","₹1,24,606","₹1,15,096","₹1,20,000"],"answer":2,"explanation":"Cash price = down payment + present value of instalments = 20,000 + 30,000 × 3.1699 = ₹1,15,096. ₹1,24,606 discounts the instalments as if paid at the start of each year; ₹1,40,000 is the total paid.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-476","question":"A lessor grants a 3-year operating lease with the first year rent-free and rent of ₹1,20,000 in each of years 2 and 3. What lease income does the lessor recognise in year 1?","options":["Nil","₹1,20,000","₹60,000","₹80,000"],"answer":3,"explanation":"Operating-lease income is recognised on a straight-line basis over the term, spreading the incentive: 2,40,000/3 = ₹80,000 each year, even in the rent-free year.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-477","question":"Under Taylor's differential piece-rate system, the standard is 40 units a day and the normal rate ₹5 a unit; output below standard is paid at 80% of the rate and at or above standard at 120%. A worker produces 42 units. What does he earn?","options":["₹210","₹252","₹168","₹201.60"],"answer":1,"explanation":"At or above standard he gets 120% of ₹5 = ₹6 a unit on all units: 42 × 6 = ₹252. ₹168 applies the low rate (₹4) to the full 42 units.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-478","question":"A purchase of ₹4,500 from Mohan was entered in the purchases book as ₹5,400 and posted from there. What is the effect, and what is the rectifying entry?","options":["Trial balance disagrees by ₹900; Dr Suspense, Cr Purchases ₹900","Profit overstated by ₹900; Dr Purchases, Cr Mohan ₹900","No effect on profit; Dr Mohan, Cr Purchases ₹900","Profit understated by ₹900; Dr Mohan, Cr Purchases ₹900"],"answer":3,"explanation":"Wrong in the original book, so both Purchases and Mohan carry ₹5,400 and the trial balance still agrees. Purchases are ₹900 too high, so profit is understated by ₹900; reverse the excess with Dr Mohan, Cr Purchases.","difficulty":"hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-479","question":"A machine costing ₹5,00,000 is bought by issuing equity shares worth ₹3,00,000 and paying ₹2,00,000 in cash. What appears in the cash-flow statement?","options":["Investing outflow ₹5,00,000 and financing inflow ₹3,00,000","Investing outflow ₹2,00,000; the share issue is disclosed as a non-cash transaction","Investing outflow ₹5,00,000 only","Nothing, because shares were issued"],"answer":1,"explanation":"Only the cash paid (₹2,00,000) is an investing outflow. Issuing shares for the asset involves no cash, so it is excluded and disclosed in the notes; grossing up both sides is wrong.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-480","question":"A firm's average profit before tax is ₹3,00,000; the tax rate is 25%; capital employed is ₹15,00,000 and the normal rate of return (after tax) is 12%. What is goodwill at three years' purchase of super profit?","options":["₹3,60,000","₹1,80,000","₹1,35,000","₹6,75,000"],"answer":2,"explanation":"Post-tax profit = ₹2,25,000; normal profit = 12% × 15,00,000 = ₹1,80,000; super profit ₹45,000 × 3 = ₹1,35,000. Using pre-tax profit against a post-tax normal return gives ₹3,60,000.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-481","question":"After the year end but before the financial statements are approved, management decides to liquidate the company because its main customer has collapsed. How does Ind AS 10 affect the statements?","options":["They must not be prepared on a going-concern basis","Only a disclosure note is needed; going-concern basis continues","The decision is ignored as it occurred after the year end","Only the next year's statements are affected"],"answer":0,"explanation":"Ind AS 10 makes going-concern deterioration an exception: if management intends to liquidate after the reporting date, the statements are not prepared on a going-concern basis.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-482","question":"A, B and C change their profit ratio from 5 : 3 : 2 to 4 : 3 : 3. Goodwill is valued at ₹2,00,000 and is not to appear in the books. What adjusting entry is passed?","options":["Dr A ₹20,000; Cr C ₹20,000","Dr C ₹20,000; Cr A ₹20,000","Dr B and C ₹10,000 each; Cr A ₹20,000","Dr C ₹40,000; Cr A ₹40,000"],"answer":1,"explanation":"A sacrifices 5/10 − 4/10 = 1/10, B is unchanged and C gains 1/10. C compensates A for 1/10 of ₹2,00,000 = ₹20,000.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-483","question":"An asset costing ₹3,10,000 (residual ₹10,000, life 5 years) is bought on 1 October 2022 and depreciated by the sum-of-the-years'-digits method based on asset years. The financial year ends on 31 March. What is the depreciation for 2023-24?","options":["₹90,000","₹80,000","₹1,00,000","₹93,333"],"answer":0,"explanation":"Asset year 1 (Oct 2022-Sep 2023) = 3,00,000 × 5/15 = 1,00,000; asset year 2 = 80,000. FY 2023-24 takes 6 months of each: 50,000 + 40,000 = ₹90,000. Charging asset year 2 in full gives ₹80,000.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-484","question":"Perpetual FIFO: opening 100 units at ₹40; bought 200 at ₹45; sold 250; a customer returned 30 of those units (restored at their issue cost of ₹45); bought 100 at ₹50; sold 120. What is the closing stock?","options":["₹2,700","₹3,000","₹2,400","₹3,150"],"answer":1,"explanation":"After the first sale 50 units at ₹45 remain; the return adds 30 at ₹45 (80 units); after buying 100 at ₹50, the sale of 120 takes 80 at ₹45 and 40 at ₹50, leaving 60 at ₹50 = ₹3,000. ₹2,700 values the remainder at ₹45.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-485","question":"Current ratio 2.5; liquid ratio 1.5 (stock is the only non-liquid current asset); working capital ₹3,00,000; stock turnover 6 times on cost of goods sold (using closing stock); gross profit 20% of sales; fixed-asset turnover 2 times on sales. What are the fixed assets?","options":["₹6,00,000","₹10,00,000","₹7,50,000","₹5,00,000"],"answer":2,"explanation":"CL = 3,00,000/1.5 = 2,00,000; CA = 5,00,000; stock = 1.0 × CL = 2,00,000; COGS = 12,00,000; sales = 12,00,000/0.8 = 15,00,000; FA = 15,00,000/2 = ₹7,50,000. ₹6,00,000 uses COGS instead of sales.","difficulty":"very-hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-486","question":"Land was ₹10 lakh at the start of the year and ₹18 lakh at the end. During the year land was revalued upward by ₹5 lakh, and land costing ₹2 lakh was sold for ₹3 lakh. Considering only land, what is the net cash flow from investing activities?","options":["₹7 lakh outflow","₹5 lakh outflow","₹1 lakh outflow","₹2 lakh outflow"],"answer":3,"explanation":"Purchases = 18 − 10 − 5 (non-cash revaluation) + 2 (cost of land sold) = ₹5 lakh; sale proceeds ₹3 lakh; net ₹2 lakh outflow. Forgetting the revaluation inflates purchases to ₹10 lakh and gives a ₹7 lakh outflow.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-487","question":"Profit after tax is ₹4,20,000 after a tax charge of ₹1,80,000; tax actually paid was ₹1,50,000. Depreciation ₹60,000, interest paid ₹40,000 and a gain on sale of plant of ₹15,000 are in the P&L. The provision for doubtful debts rose by ₹5,000, gross debtors rose by ₹30,000 and creditors fell by ₹20,000. What is the cash from operating activities?","options":["₹4,90,000","₹4,60,000","₹4,85,000","₹4,50,000"],"answer":0,"explanation":"PBT 6,00,000 + 60,000 + 40,000 − 15,000 + 5,000 = 6,90,000; − 30,000 − 20,000 = 6,40,000; − tax paid 1,50,000 = ₹4,90,000. ₹4,60,000 deducts the tax charge instead of tax paid; ₹4,50,000 forgets to add back interest.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-488","question":"A and B share profits 3 : 2 with capitals (after adjustments) of ₹1,80,000 and ₹1,40,000. C is admitted for 1/5, taken from A and B in their old ratio, and brings capital equal to his share of the total capital of the new firm based on the old partners' combined capital. The old partners' capitals are then adjusted to the new ratio by cash. What happens?","options":["A withdraws ₹12,000 and B brings ₹12,000","A brings ₹12,000 and B withdraws ₹12,000","A brings ₹6,000 and B withdraws ₹6,000","No adjustment is needed"],"answer":1,"explanation":"Combined capital 3,20,000 is 4/5 of the total, so total = 4,00,000 and C brings ₹80,000. New ratio 12 : 8 : 5 gives A ₹1,92,000 and B ₹1,28,000, so A brings ₹12,000 and B withdraws ₹12,000.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-489","question":"After all adjustments, A, B and C have capitals of ₹2,40,000, ₹1,60,000 and ₹1,20,000. C retires and is paid in full. A and B will share 3 : 2, and the new firm's total capital is to be ₹5,00,000 in that ratio, any surplus or deficit being settled in cash. How much cash does A bring in?","options":["₹72,000","₹36,000","₹60,000","₹1,00,000"],"answer":2,"explanation":"A's required capital = 3/5 × 5,00,000 = ₹3,00,000 against his ₹2,40,000, so he brings ₹60,000 (and B brings ₹40,000). ₹72,000 just splits C's ₹1,20,000 in the new ratio.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-490","question":"A company buys back 20,000 of its ₹10 shares at ₹25. It has securities premium ₹5,00,000 and general reserve ₹8,00,000; the premium on buyback is charged to securities premium and the capital redemption reserve is created out of general reserve. What is the general reserve after the buyback?","options":["₹6,00,000","₹3,00,000","₹8,00,000","₹5,00,000"],"answer":0,"explanation":"Premium ₹3,00,000 is charged to securities premium (5,00,000 → 2,00,000); CRR equal to the nominal value bought back, ₹2,00,000, comes from general reserve (8,00,000 → 6,00,000). ₹3,00,000 charges both to the general reserve.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-491","question":"H pays ₹11,00,000 for 90% of S. S's net assets have a book value of ₹10,00,000; its land is worth ₹2,00,000 more than book value, and a contingent liability with a fair value of ₹50,000 is identified. NCI is measured at its proportionate share. Ignoring deferred tax, what goodwill arises under Ind AS 103?","options":["₹2,00,000","₹20,000","₹1,10,000","₹65,000"],"answer":3,"explanation":"Identifiable net assets at fair value = 10,00,000 + 2,00,000 − 50,000 = 11,50,000 (Ind AS 103 recognises contingent liabilities that are present obligations). Goodwill = 11,00,000 − 90% × 11,50,000 = ₹65,000. Ignoring the contingent liability gives ₹20,000.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-492","question":"At the start of the year a parent sells a machine to its wholly owned subsidiary for ₹6,00,000; its carrying amount was ₹4,00,000 and remaining life 5 years. By how much must consolidated PPE be reduced at the end of that year?","options":["₹2,00,000","₹1,60,000","₹40,000","₹2,40,000"],"answer":1,"explanation":"The ₹2,00,000 intra-group profit is eliminated, but the subsidiary's extra depreciation on it (2,00,000/5 = ₹40,000) is also reversed, so PPE is reduced by ₹1,60,000 at year end.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-493","question":"A salesperson earns a commission of ₹1,20,000 for winning a 3-year service contract; the company expects to recover it from the contract. How is it treated under Ind AS 115?","options":["Expensed immediately as selling cost","Deducted from contract revenue","Capitalised as a contract cost asset and amortised, about ₹40,000 a year","Capitalised and tested for impairment only, never amortised"],"answer":2,"explanation":"Incremental costs of obtaining a contract that are expected to be recovered are capitalised and amortised on a basis consistent with the transfer of services (₹40,000 a year here). The practical expedient to expense applies only when the amortisation period is one year or less.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-494","question":"A 3-year lease requires ₹1,00,000 at the START of each year; the discount rate is 10%. What is the lease liability at the end of year 1, before the second payment?","options":["₹1,73,554","₹2,73,554","₹1,90,909","₹2,00,909"],"answer":2,"explanation":"PV at commencement = 1,00,000 × (1 + 0.9091 + 0.8264) = 2,73,554; the first payment is made at once, leaving 1,73,554, which accrues 10% interest to ₹1,90,909 by the end of year 1. ₹1,73,554 forgets the interest.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-495","question":"A company issues ₹10,00,000 of 3-year convertible debentures with a 6% annual coupon. Similar debentures without the conversion option yield 10%. How is the instrument split on initial recognition under Ind AS 32?","options":["Liability ₹10,00,000; equity nil","Liability ₹9,00,526; equity ₹99,474","Liability ₹7,51,315; equity ₹2,48,685","Liability ₹9,50,000; equity ₹50,000"],"answer":1,"explanation":"The liability is the present value of coupons and principal at 10%: 60,000 × 2.4869 + 10,00,000/1.331 = ₹9,00,526; the residual ₹99,474 is the equity (conversion option). Discounting only the principal gives ₹7,51,315.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-496","question":"Profit is ₹1 crore and 50 lakh shares are outstanding. There are options over 10 lakh shares at an exercise price of ₹60; the average market price is ₹80. What is diluted EPS under Ind AS 33?","options":["₹1.67","₹2.00","₹1.74","₹1.90"],"answer":3,"explanation":"Treasury-share method: exercise proceeds buy back 10 lakh × 60/80 = 7.5 lakh shares, so 2.5 lakh shares are issued for nothing; 1 crore/52.5 lakh = ₹1.90. Adding all 10 lakh shares gives ₹1.67.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-497","question":"Standard mix: 70 kg of X at ₹15 and 30 kg of Y at ₹40, yielding 80 kg of output. Actual input was 1,500 kg of X and 500 kg of Y, producing 1,560 kg. What is the material yield variance?","options":["₹1,125 adverse","₹2,500 favourable","₹1,200 adverse","₹1,375 favourable"],"answer":0,"explanation":"Standard cost per kg of output = (1,050 + 1,200)/80 = ₹28.125. Expected output from 2,000 kg = 1,600 kg; shortfall 40 × 28.125 = ₹1,125 A. ₹2,500 F is the mix variance.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-498","question":"A firm sells 20,000 units at ₹50 with variable cost ₹30 and fixed costs ₹2,50,000. Variable cost will rise by ₹5 a unit and fixed costs by ₹20,000. At the same volume, what selling price keeps profit unchanged?","options":["₹55","₹56","₹51","₹57"],"answer":1,"explanation":"Present profit = 20,000 × 20 − 2,50,000 = ₹1,50,000. Needed contribution = 1,50,000 + 2,70,000 = 4,20,000, i.e., ₹21 a unit, so price = 35 + 21 = ₹56. ₹55 passes on only the variable-cost increase.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-499","question":"A club's subscription income for the year is ₹2,40,000. Subscriptions outstanding were ₹12,000 at the start and ₹18,000 at the end; subscriptions received in advance were ₹9,000 at the start and ₹6,000 at the end. How much cash was received for subscriptions?","options":["₹2,49,000","₹2,37,000","₹2,31,000","₹2,43,000"],"answer":2,"explanation":"Cash = income + opening outstanding − closing outstanding − opening advance + closing advance = 2,40,000 + 12,000 − 18,000 − 9,000 + 6,000 = ₹2,31,000. Reversing the advance adjustments gives ₹2,37,000.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-500","question":"Stock on 1 April was ₹1,00,000; purchases to the date of a fire ₹5,00,000; sales ₹6,00,000. Sales include slow-moving goods costing ₹60,000 that were sold for ₹50,000; the normal gross profit on other sales is 25% of sales. What was the stock at the date of the fire?","options":["₹1,50,000","₹1,37,500","₹1,20,000","₹1,27,500"],"answer":3,"explanation":"Normal sales ₹5,50,000 cost 75% = 4,12,500; add the slow-moving goods at cost ₹60,000; COGS = 4,72,500; stock = 6,00,000 − 4,72,500 = ₹1,27,500. Applying 25% to all sales gives ₹1,50,000.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-501","question":"An old machine with a book value of ₹60,000 is traded in at ₹75,000 against a new machine priced at ₹3,00,000, the balance ₹2,25,000 being paid in cash. What are the cost of the new machine and the result on the old one?","options":["Cost ₹2,25,000; no profit","Cost ₹2,85,000; profit nil","Cost ₹3,00,000; profit ₹15,000","Cost ₹3,00,000; loss ₹15,000"],"answer":2,"explanation":"The new machine is recorded at its full price of ₹3,00,000 (cash + trade-in allowance), and the old machine's disposal at ₹75,000 against a book value of ₹60,000 gives a profit of ₹15,000.","difficulty":"hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-502","question":"Net profit before corrections is ₹50,000. A suspense account was opened. Errors: (a) the sales book was overcast by ₹1,000; (b) purchase returns of ₹360 were posted to the debit of Purchases account; (c) rent of ₹2,000 was posted to Rent account as ₹200. What is the corrected net profit?","options":["₹47,920","₹47,560","₹52,080","₹49,000"],"answer":0,"explanation":"(a) cuts sales by ₹1,000; (b) reduces purchases by ₹360 and adds purchase returns of ₹360, raising profit by ₹720; (c) adds rent of ₹1,800. 50,000 − 1,000 + 720 − 1,800 = ₹47,920. Taking (b) as only ₹360 gives ₹47,560.","difficulty":"very-hard","source":"Bank MT · Big 4"},
  {"id":"mgmt-accounting-503","question":"During the year a qualifying asset absorbed weighted average expenditure of ₹50 lakh, funded from general borrowings: ₹40 lakh at 10% and ₹60 lakh at 12.5%, outstanding all year. Under Ind AS 23, what borrowing cost is capitalised?","options":["₹5.625 lakh","₹6.25 lakh","₹5.75 lakh","₹5.00 lakh"],"answer":2,"explanation":"Capitalisation rate = weighted average cost of general borrowings = (4 + 7.5)/100 = 11.5%; 11.5% × 50 lakh = ₹5.75 lakh. A simple average of the two rates (11.25%) gives ₹5.625 lakh.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-504","question":"Employee share options vested last year. This year some vested options lapse unexercised. Under Ind AS 102, what happens to the expense previously recognised for them?","options":["It is reversed through profit and loss","It is not reversed; the related equity balance may be transferred within equity, e.g., to general reserve","It is transferred to a liability","It is credited to securities premium automatically"],"answer":1,"explanation":"After vesting, no adjustment is made to total equity-settled expense for options that later lapse; the ESOP outstanding balance for them may be moved within equity (often to general reserve). Reversal applies only to forfeiture before vesting due to service conditions.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-505","question":"A company sells an asset to a bank for ₹10 crore and must buy it back after one year for ₹10.8 crore. Under Ind AS 115, how is the transaction treated?","options":["As a sale, with ₹10 crore revenue","As a sale, with a ₹0.8 crore loss provision","As a lease of the asset to the bank","As a financing arrangement: the asset stays on the books and ₹10 crore is a liability, with ₹0.8 crore as interest"],"answer":3,"explanation":"A forward obligation to repurchase at a price at or above the original price means control never passes; the company records a financial liability and recognises the difference as interest expense over the year.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-506","question":"Under Ind AS 109's general model, when a loan's credit risk has increased significantly since initial recognition (but it is not credit-impaired), the loss allowance is measured at:","options":["Lifetime expected credit losses","12-month expected credit losses","Incurred losses only","Nil until default"],"answer":0,"explanation":"Stage 1 assets carry 12-month ECL; once credit risk increases significantly (stage 2) the allowance moves to lifetime ECL, with interest still on the gross carrying amount. Incurred-loss models were replaced by ECL.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-507","question":"Book profit before tax is ₹10,00,000. It includes a donation of ₹50,000 that is never tax-deductible, book depreciation of ₹2,00,000 against tax depreciation of ₹3,00,000, and a gratuity provision of ₹1,00,000 deductible only when paid. The tax rate is 25%. What is the current tax?","options":["₹2,50,000","₹2,37,500","₹2,87,500","₹2,62,500"],"answer":3,"explanation":"Taxable income = 10,00,000 + 50,000 + 2,00,000 − 3,00,000 + 1,00,000 = ₹10,50,000; current tax = ₹2,62,500. The DTL (₹25,000) and DTA (₹25,000) offset, so total tax expense is also ₹2,62,500.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-508","question":"H's revenue for the year is ₹50 lakh. It acquires S on 1 January; S's revenue for the full year to 31 March is ₹24 lakh, earned evenly. After acquisition S sold ₹2 lakh of goods to H. What is consolidated revenue?","options":["₹54 lakh","₹72 lakh","₹56 lakh","₹74 lakh"],"answer":0,"explanation":"Only S's post-acquisition revenue is included: 24 × 3/12 = ₹6 lakh; less intra-group sales of ₹2 lakh: 50 + 6 − 2 = ₹54 lakh. Including S's full-year revenue gives ₹72 lakh.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-509","question":"Under Ind AS 2, may a manufacturer measure its inventories using standard costs?","options":["No, only actual cost is allowed","Yes, always, whatever the variances","Yes, if the results approximate actual cost, with standards reviewed regularly","Only for finished goods, never for WIP"],"answer":2,"explanation":"Standard cost (and the retail method) are allowed as measurement conveniences if the results approximate cost; standards must reflect normal levels of materials, labour, efficiency and capacity utilisation, and be reviewed regularly.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-510","question":"Construction of a qualifying asset is halted for four months because of a labour dispute (not a normal part of the process). Under Ind AS 23, what happens to borrowing costs during the halt?","options":["They continue to be capitalised","Capitalisation is suspended; they are expensed","They are deferred and capitalised when work resumes","They are capitalised at half the rate"],"answer":1,"explanation":"Capitalisation is suspended during extended periods in which active development is interrupted. It is not suspended for temporary delays that are a necessary part of getting the asset ready.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-511","question":"Sales ₹50 lakh, variable costs ₹30 lakh, fixed costs ₹10 lakh and interest ₹4 lakh. If sales rise by 12% with the cost structure unchanged, by what percentage do earnings per share rise?","options":["24%","40%","20%","12%"],"answer":1,"explanation":"DOL = contribution/EBIT = 20/10 = 2; DFL = EBIT/EBT = 10/6 = 1.667; combined leverage 3.33, so EPS rises 3.33 × 12% = 40%. 24% applies only operating leverage.","difficulty":"very-hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-512","question":"Under Ind AS 16, an asset's estimated residual value is revised upward so that it now exceeds the asset's carrying amount. What is the depreciation charge?","options":["Nil, until the residual value falls below the carrying amount","Continue the old charge","Negative depreciation is credited to P&L","Depreciate down to the old residual value"],"answer":0,"explanation":"When residual value equals or exceeds carrying amount, depreciation is zero until it again falls below the carrying amount. Residual value cannot create a gain through 'negative depreciation'.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-513","question":"A company treats its bank overdraft (repayable on demand and part of cash management) as a cash equivalent. Cash was ₹40,000 and overdraft ₹25,000 at the start of the year; cash was ₹30,000 and overdraft ₹60,000 at the end. What net change in cash and cash equivalents does the cash-flow statement show?","options":["Decrease of ₹45,000","Decrease of ₹10,000","Increase of ₹25,000","Decrease of ₹35,000"],"answer":0,"explanation":"Net cash and equivalents moved from +15,000 (40,000 − 25,000) to −30,000 (30,000 − 60,000), a decrease of ₹45,000. ₹10,000 looks only at the cash balance.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-514","question":"A and B share profits 3 : 2. On C's admission the books show a workmen compensation reserve of ₹30,000 against which a claim of ₹12,000 is admitted, and an investment fluctuation reserve of ₹20,000; investments of book value ₹1,00,000 are worth ₹92,000. The balances of both reserves are distributed to the old partners. How much is credited to A?","options":["₹30,000","₹22,800","₹18,000","₹25,200"],"answer":2,"explanation":"Workmen compensation reserve: 30,000 − 12,000 claim = 18,000 free. Investment fluctuation reserve: 20,000 − 8,000 fall in value = 12,000 free. A gets 3/5 × 30,000 = ₹18,000. Distributing both reserves in full gives ₹30,000.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-515","question":"A subsidiary issues bonus shares to all its shareholders out of reserves that existed when the parent acquired it. What is the effect on goodwill in the consolidated statements?","options":["Goodwill increases by the parent's share of the bonus","Goodwill decreases by the parent's share of the bonus","No effect, since pre-acquisition reserves are merely converted into share capital","Goodwill is recalculated using the new share capital at market value"],"answer":2,"explanation":"A bonus issue from pre-acquisition reserves only reclassifies the subsidiary's equity at acquisition (reserves into capital); the parent's share of net assets at acquisition is unchanged, so goodwill is unchanged.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-516","question":"A contract carries a performance bonus: the company estimates a 60% chance of earning ₹1,00,000, a 30% chance of ₹50,000 and a 10% chance of nothing, and has many similar contracts. Using the expected-value method under Ind AS 115 (no constraint applies), what variable consideration is included?","options":["₹1,00,000","₹50,000","₹60,000","₹75,000"],"answer":3,"explanation":"Expected value = 0.6 × 1,00,000 + 0.3 × 50,000 + 0.1 × 0 = ₹75,000. ₹1,00,000 is the most likely amount, which suits binary outcomes rather than a range like this.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-517","question":"A ₹1 crore contract is recognised over time on a cost-to-cost basis. In year 1 costs were ₹30 lakh with total costs estimated at ₹75 lakh. By the end of year 2 cumulative costs are ₹60 lakh and the estimate of total costs is revised to ₹80 lakh. What revenue is recognised in year 2?","options":["₹40 lakh","₹37.5 lakh","₹35 lakh","₹30 lakh"],"answer":2,"explanation":"Year 1 = 30/75 × 1 crore = ₹40 lakh. By year 2 progress is 60/80 = 75%, so cumulative revenue ₹75 lakh, giving ₹35 lakh in year 2 (cumulative catch-up). ₹37.5 lakh divides only year 2's cost by the new total.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-518","question":"A fixed-price contract for ₹50 lakh has incurred costs of ₹20 lakh, and further costs of ₹35 lakh are expected. What total loss is recognised in the current year?","options":["₹1.82 lakh","₹5 lakh","Nil until completion","₹3.18 lakh"],"answer":1,"explanation":"Total costs (₹55 lakh) exceed the price, so the whole expected loss of ₹5 lakh is recognised at once: ₹1.82 lakh comes through cost-to-cost revenue (18.18 − 20) and the remaining ₹3.18 lakh as an onerous-contract provision.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-519","question":"Under Ind AS 116, over what period does a lessee depreciate a right-of-use asset when the lease does NOT transfer ownership and there is no purchase option reasonably certain to be exercised?","options":["The asset's full useful life","The shorter of the lease term and the asset's useful life","The longer of the lease term and the useful life","A fixed 5 years"],"answer":1,"explanation":"If ownership passes or a purchase option is reasonably certain, the ROU asset is depreciated over the underlying asset's useful life; otherwise over the shorter of the lease term and useful life.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-520","question":"Under Ind AS 12, why is no deferred tax liability recognised on goodwill arising in a business combination when goodwill is not tax-deductible?","options":["Because goodwill is amortised for tax","Because goodwill is a monetary item","Because the initial-recognition exemption prohibits it, as recognising a DTL would itself increase goodwill","Because deferred tax applies only to tangible assets"],"answer":2,"explanation":"Ind AS 12 prohibits a DTL on the initial recognition of goodwill: goodwill is a residual, so a DTL would raise goodwill, which would raise the DTL, in a circle. Taxable differences on goodwill after initial recognition are treated differently.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-521","question":"Last year a company reported basic EPS of ₹12. This year it issued bonus shares 1 for 2. At what figure is last year's EPS shown as the comparative this year?","options":["₹12","₹6","₹18","₹8"],"answer":3,"explanation":"Bonus issues are adjusted retrospectively: every old share became 1.5 shares, so restated EPS = 12/1.5 = ₹8. ₹6 assumes a 1-for-1 bonus.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-522","question":"A company expects to pay ₹10,00,000 in 3 years to settle a present obligation; the pre-tax discount rate reflecting the time value of money is 8%, and the effect of discounting is material. At what amount is the provision first recognised under Ind AS 37?","options":["₹10,00,000","₹7,93,832","₹7,60,000","₹9,25,926"],"answer":1,"explanation":"Where the time value is material, a provision is the present value of expected outflows: 10,00,000/1.08³ = ₹7,93,832; the discount unwinds as finance cost. ₹9,25,926 discounts for one year only.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-523","question":"Shares classified at FVTPL are bought for ₹1,00,000 plus brokerage of ₹1,000. At year end their fair value is ₹1,08,000. What is the net effect on profit for the year under Ind AS 109?","options":["₹7,000 credit: ₹8,000 fair-value gain less ₹1,000 transaction cost expensed","₹8,000 credit","₹7,000 credited to OCI","₹1,000 debit only"],"answer":0,"explanation":"For FVTPL assets, transaction costs are expensed immediately and the asset starts at ₹1,00,000; the ₹8,000 gain goes to P&L, so the net effect is ₹7,000. For other classes the brokerage would be added to cost.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-524","question":"A job takes 10 hours in Department X (overhead rate ₹50 an hour) and 2 hours in Department Y (₹200 an hour). The factory-wide blanket rate is ₹90 an hour. How much overhead is charged to the job under departmental rates, and by how much would a blanket rate distort it?","options":["₹900; blanket rate overcharges by ₹180","₹1,080; blanket rate undercharges by ₹180","₹900; blanket rate undercharges by ₹180","₹500; blanket rate overcharges by ₹580"],"answer":0,"explanation":"Departmental: 10 × 50 + 2 × 200 = ₹900. Blanket: 12 × 90 = ₹1,080, overcharging this job by ₹180 because it spends most time in the cheap department.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-525","question":"In cost accounting, how are normal and abnormal spoilage treated?","options":["Both charged to costing profit and loss","Normal spoilage absorbed by good units; abnormal spoilage charged to costing profit and loss","Normal spoilage charged to costing profit and loss; abnormal absorbed by good units","Both absorbed by good units"],"answer":1,"explanation":"Normal spoilage is an inherent cost of production and raises the cost of good units; abnormal spoilage is avoidable and written off so that it does not distort product costs.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-526","question":"The standard labour rate is ₹30 an hour. Actual hours worked were 2,200. The labour efficiency variance is ₹3,000 adverse and the rate variance ₹2,200 favourable. What were the standard hours for actual output and the actual rate?","options":["2,300 hours; ₹31","2,100 hours; ₹31","2,300 hours; ₹29","2,100 hours; ₹29"],"answer":3,"explanation":"Efficiency: 30 × (SH − 2,200) = −3,000, so SH = 2,100. Rate: 2,200 × (30 − AR) = +2,200, so AR = ₹29. Mixing up the signs gives 2,300 hours or ₹31.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-527","question":"12,000 units are to be produced, each needing 2.5 standard labour hours. Idle time is expected to be 20% of paid hours, and the wage rate is ₹40 an hour. What is the direct labour cost budget?","options":["₹12,00,000","₹14,40,000","₹15,00,000","₹9,60,000"],"answer":2,"explanation":"Productive hours = 30,000, which are 80% of paid hours, so paid hours = 37,500 × ₹40 = ₹15,00,000. Adding 20% to productive hours (36,000 hours, ₹14,40,000) understates the paid hours.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-528","question":"Product A makes up 60% of sales value with a P/V ratio of 40%; product B makes up 40% with a P/V ratio of 25%. Fixed costs are ₹3,40,000. What is the break-even sales value at this mix?","options":["₹10,00,000","₹10,46,154","₹8,50,000","₹13,60,000"],"answer":0,"explanation":"Composite P/V = 0.6 × 40% + 0.4 × 25% = 34%; break-even = 3,40,000/0.34 = ₹10,00,000. A simple average of the two ratios (32.5%) gives ₹10,46,154.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-529","question":"A joint process costs ₹2,00,000. Its by-product (1,000 kg) sells at ₹30 a kg after packing costs of ₹5 a kg, and selling expenses are 10% of its sales value. Its net realisable value is credited to the joint process. What joint cost remains for the main products?","options":["₹1,70,000","₹1,75,000","₹1,73,000","₹1,78,000"],"answer":3,"explanation":"By-product NRV = 30,000 − 5,000 packing − 3,000 selling = ₹22,000; 2,00,000 − 22,000 = ₹1,78,000. Crediting gross sales gives ₹1,70,000; ignoring selling expenses gives ₹1,75,000.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-530","question":"Annual demand is 24,000 units, ordering cost ₹150 an order and unit price ₹40. Carrying cost is 15% of price (interest) plus ₹2 a unit a year for storage. What is the EOQ?","options":["1,095 units","949 units","600 units","1,342 units"],"answer":1,"explanation":"Carrying cost = 6 + 2 = ₹8 a unit; EOQ = √(2 × 24,000 × 150/8) = √9,00,000 ≈ 949 units. Leaving out the storage cost gives 1,095 units.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-531","question":"On dissolution, machinery (book value ₹70,000) and other assets (book value ₹2,30,000) go to the realisation account along with creditors of ₹80,000. The creditors accept the machinery in full settlement; the other assets realise ₹2,50,000 and realisation expenses are ₹5,000. What is the realisation profit?","options":["₹15,000","₹35,000","₹25,000","₹20,000"],"answer":2,"explanation":"Credits: creditors 80,000 + cash 2,50,000 = 3,30,000; debits: assets 3,00,000 + expenses 5,000 = 3,05,000; profit ₹25,000. Settling ₹80,000 of creditors with a ₹70,000 machine is itself a ₹10,000 gain, which ₹15,000 misses.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-532","question":"At the start of the year taxable temporary differences were ₹4,00,000 with a DTL of ₹1,20,000 at 30%. During the year a further ₹1,00,000 of taxable temporary difference arises, and the enacted rate falls to 25%. What deferred tax is charged to profit and loss?","options":["₹5,000 charge","₹25,000 charge","₹30,000 charge","₹20,000 credit"],"answer":0,"explanation":"Closing DTL = 5,00,000 × 25% = ₹1,25,000; movement = 1,25,000 − 1,20,000 = ₹5,000 charge (a ₹25,000 charge on the new difference offset by a ₹20,000 credit from the rate cut).","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-533","question":"A lessor's finance lease has lease payments with a present value of ₹4,00,000 at the interest rate implicit in the lease, and an unguaranteed residual value with a present value of ₹50,000. At what amount does the lessor recognise its receivable (net investment in the lease)?","options":["₹4,00,000","₹4,50,000","₹3,50,000","₹4,00,000, with the residual shown as PPE"],"answer":1,"explanation":"Net investment = present value of lease payments plus any unguaranteed residual value accruing to the lessor: 4,00,000 + 50,000 = ₹4,50,000. The underlying asset is derecognised, so it is not kept as PPE.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-534","question":"Interest expense in the P&L is ₹1,00,000. Interest payable was ₹15,000 at the start and ₹25,000 at the end of the year, and interest of ₹30,000 paid on a construction loan was capitalised. Under Ind AS 7, what total interest paid is shown?","options":["₹90,000","₹1,40,000","₹1,30,000","₹1,20,000"],"answer":3,"explanation":"Interest paid on the expensed portion = 15,000 + 1,00,000 − 25,000 = 90,000, plus capitalised interest paid ₹30,000; Ind AS 7 requires total interest paid to be disclosed whether expensed or capitalised: ₹1,20,000.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-535","question":"Annual sales are ₹24 lakh, all on credit. Costs are materials 50%, labour 20% and overheads 10% of sales. Holding periods: raw materials 1 month of material cost; WIP 0.5 month of total cost; finished goods 1 month of total cost; debtors 2 months at cost; creditors 1 month of materials. What working capital is required?","options":["₹6.6 lakh","₹6.4 lakh","₹4.6 lakh","₹5.6 lakh"],"answer":3,"explanation":"Monthly material ₹1 lakh; monthly total cost ₹1.6 lakh. RM 1 + WIP 0.8 + FG 1.6 + debtors 3.2 = 6.6 lakh, less creditors 1 lakh = ₹5.6 lakh. Valuing debtors at selling price gives ₹6.4 lakh.","difficulty":"very-hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-536","question":"H holds 80% of S and measures NCI at fair value (full goodwill). Goodwill of ₹2,00,000 is impaired by ₹40,000. How is the impairment shared?","options":["All ₹40,000 against the parent's retained earnings","Parent ₹32,000 and NCI ₹8,000, in the profit-sharing ratio","All ₹40,000 against NCI","Not recognised because goodwill is never impaired"],"answer":1,"explanation":"With NCI at fair value, goodwill includes the NCI's share, so an impairment loss is allocated between parent and NCI in the ratio in which they share profits (80 : 20). Under the proportionate method it would fall only on the parent.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-537","question":"Under Ind AS 105, how are the results of a discontinued operation presented in the statement of profit and loss?","options":["Line by line with continuing operations","Only in the notes","As a single amount: post-tax profit or loss of the discontinued operation plus any post-tax gain or loss on remeasurement or disposal","Directly in retained earnings"],"answer":2,"explanation":"Discontinued operations are shown as one amount after tax, separately from continuing operations, with an analysis in the notes; comparatives are re-presented.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-538","question":"How many of these statements about the revaluation model under Ind AS 16 are correct? (1) On revaluation, accumulated depreciation may be eliminated against the gross carrying amount. (2) The revaluation surplus is recycled to profit and loss when the asset is sold. (3) A revaluation decrease beyond any existing surplus for that asset is charged to profit and loss. (4) Depreciation after revaluation is based on the revalued amount.","options":["3","2","4","1"],"answer":0,"explanation":"1, 3 and 4 are correct. The surplus is never recycled through P&L; on disposal it may be transferred directly to retained earnings.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-539","question":"Profit per financial accounts is ₹3,20,000. Dividend received of ₹12,000 and preliminary expenses written off of ₹8,000 appear only in the financial accounts. Overheads were over-absorbed by ₹15,000 in the cost accounts. The cost accounts value closing stock ₹5,000 higher and opening stock ₹3,000 lower than the financial accounts. What is the profit per cost accounts?","options":["₹3,39,000","₹3,09,000","₹3,03,000","₹3,17,000"],"answer":1,"explanation":"Start from financial profit: − 12,000 dividend + 8,000 preliminary expenses − 15,000 (over-absorption charged extra cost in cost books) + 5,000 (higher closing stock) + 3,000 (lower opening stock) = ₹3,09,000. Treating over-absorption as raising cost profit gives ₹3,39,000.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-540","question":"A special order needs material already in stock, bought for ₹20,000 (replacement cost ₹25,000, scrap value ₹8,000). The material is not used regularly; if not used on this order it would replace another material that would otherwise cost ₹12,000 to buy. What is its relevant cost for the order?","options":["₹20,000","₹25,000","₹12,000","₹8,000"],"answer":2,"explanation":"Relevant cost is the best alternative forgone: substituting for material costing ₹12,000 beats scrapping at ₹8,000, so ₹12,000. Historical cost is sunk, and replacement cost matters only if the material is regularly used and would be replaced.","difficulty":"hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-541","question":"Under Ind AS 116, how is a lease judged to be of a 'low-value' asset?","options":["On the value of the asset when new, regardless of the lessee's size or materiality","On the total lease payments compared with the lessee's revenue","On the asset's current second-hand value","On whether the lease term is under 12 months"],"answer":0,"explanation":"Low value is assessed on an absolute basis by reference to the underlying asset when new (e.g., a tablet or small office furniture); it does not depend on materiality to the lessee. A car can never qualify, since a new car is not low-value.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-542","question":"A company holds a portfolio of bonds both to collect contractual cash flows and to sell when liquidity is needed; the cash flows are solely payments of principal and interest. How are the bonds classified under Ind AS 109?","options":["Amortised cost","FVTPL only","FVOCI, with cumulative gains recycled to P&L on sale","FVOCI, with gains never recycled"],"answer":2,"explanation":"A 'hold to collect and sell' business model with SPPI cash flows leads to FVOCI for debt; interest, impairment and FX go to P&L, and cumulative OCI gains are recycled on derecognition. No-recycling FVOCI applies only to the equity election.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-543","question":"A machine costing ₹6,00,000 bought on 1 April 2020 is depreciated straight-line over 6 years (nil residual). On 1 April 2022 it is impaired to ₹3,00,000, with the remaining life unchanged. On 1 April 2023 the remaining life is revised to 5 years from that date. What is the depreciation for 2023-24?","options":["₹45,000","₹56,250","₹75,000","₹60,000"],"answer":0,"explanation":"After impairment, ₹3,00,000 is spread over 4 years: ₹75,000 for 2022-23, leaving ₹2,25,000. The revised 5-year life applies prospectively: ₹45,000. ₹60,000 forgets the 2022-23 charge.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-544","question":"Stock was counted on 10 April at ₹2,40,000 (cost); the year ended on 31 March. Between 1 and 10 April: sales ₹60,000 (gross profit 20% on cost); purchases ₹35,000, of which goods worth ₹5,000 had not yet arrived; sales returns ₹6,000 at selling price. What was the stock on 31 March?","options":["₹2,50,000","₹2,53,200","₹2,65,000","₹2,55,000"],"answer":3,"explanation":"Work back: add cost of sales 60,000/1.2 = 50,000; deduct purchases actually received 30,000; deduct cost of returns 6,000/1.2 = 5,000: ₹2,55,000. ₹2,53,200 treats 20% as a margin on sales; ₹2,50,000 deducts goods not yet received.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-545","question":"H holds 75% of S. H's retained earnings are ₹20 lakh. S's retained earnings were ₹5 lakh at acquisition and ₹9 lakh now. Cumulative extra depreciation on fair-value uplifts of S's assets is ₹0.4 lakh, and H's closing stock includes ₹0.6 lakh of unrealised profit on goods bought from S. NCI is measured at its share of net assets. What are consolidated retained earnings?","options":["₹23 lakh","₹22.25 lakh","₹22.7 lakh","₹22.1 lakh"],"answer":1,"explanation":"S's adjusted post-acquisition profit = 4 − 0.4 − 0.6 = ₹3 lakh (upstream unrealised profit is shared with NCI); group share 75% = 2.25, so 20 + 2.25 = ₹22.25 lakh. Charging the unrealised profit wholly to H gives ₹22.1 lakh.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-546","question":"A customer buys a product for ₹1,00,000 and receives a voucher for 40% off future purchases of up to ₹50,000. All customers get a 10% seasonal discount anyway, and 80% of vouchers are expected to be used. Under Ind AS 115, how much of the ₹1,00,000 is allocated to the voucher?","options":["₹12,000","₹16,000","₹10,714","₹20,000"],"answer":2,"explanation":"Only the incremental 30% discount is a material right: SSP = 50,000 × 30% × 80% = ₹12,000. Relative allocation: 1,00,000 × 12,000/1,12,000 = ₹10,714. ₹16,000 ignores the discount everyone gets.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-547","question":"A company exchanges an old machine (carrying amount ₹3,00,000, fair value ₹3,50,000) plus ₹50,000 in cash for a new machine. The exchange has commercial substance. Under Ind AS 16, what is the new machine's cost and the result on the old machine?","options":["Cost ₹4,00,000; gain ₹50,000","Cost ₹3,50,000; no gain","Cost ₹3,50,000; gain ₹50,000","Cost ₹4,50,000; gain ₹1,00,000"],"answer":0,"explanation":"With commercial substance, the new asset is measured at the fair value given up: 3,50,000 + 50,000 cash = ₹4,00,000, and the old machine's disposal gives a ₹50,000 gain. Without commercial substance it would be carried at ₹3,50,000 with no gain.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-548","question":"A CGU holds asset A (carrying ₹4 lakh, fair value less costs of disposal ₹3.5 lakh), asset B (₹6 lakh, no separate recoverable amount) and goodwill ₹1 lakh. The CGU's recoverable amount is ₹8 lakh. Under Ind AS 36, what is B's carrying amount after impairment?","options":["₹4.8 lakh","₹5.0 lakh","₹4.2 lakh","₹4.5 lakh"],"answer":3,"explanation":"Loss ₹3 lakh: goodwill takes ₹1 lakh; ₹2 lakh pro rata (4 : 6) would cut A by 0.8 to 3.2, below its floor of 3.5, so A takes only 0.5 and B takes 1.2 + 0.3 = 1.5, leaving ₹4.5 lakh. ₹4.8 lakh ignores the floor.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-549","question":"Profit after tax is ₹80 lakh. Dividend on convertible preference shares is ₹8 lakh; the preference shares convert into 4 lakh equity shares. There are 20 lakh equity shares. What are basic and diluted EPS?","options":["Basic ₹4.00; diluted ₹3.33","Basic ₹3.60; diluted ₹3.00","Basic ₹3.60; diluted ₹3.33","Basic ₹3.60; diluted ₹3.60"],"answer":2,"explanation":"Basic = (80 − 8)/20 = ₹3.60. Diluted adds back the preference dividend and the 4 lakh shares: 80/24 = ₹3.33 (dilutive, as it is below 3.60). ₹3.00 deducts the dividend but adds the shares.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-550","question":"A company buys a subsidiary for ₹50 lakh paid in cash; the subsidiary held cash of ₹8 lakh at acquisition. How is this shown in the consolidated cash-flow statement?","options":["Investing outflow of ₹50 lakh","Investing outflow of ₹42 lakh (net of cash acquired)","Financing outflow of ₹42 lakh","Operating outflow of ₹50 lakh"],"answer":1,"explanation":"Ind AS 7 shows the aggregate cash paid for obtaining control, net of cash and cash equivalents acquired, as a single investing item: 50 − 8 = ₹42 lakh.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-551","question":"In 2024-25 a company finds that 2023-24 depreciation was overstated by ₹2 lakh (material). The tax rate is 25% and deferred tax applies. How are the 1 April 2024 opening balances restated?","options":["PPE +₹2 lakh, DTL +₹0.5 lakh, retained earnings +₹1.5 lakh","PPE +₹2 lakh, retained earnings +₹2 lakh","Credit ₹2 lakh to 2024-25 profit and loss","PPE +₹1.5 lakh, retained earnings +₹1.5 lakh"],"answer":0,"explanation":"Retrospective correction restores the asset (+2 lakh); the higher carrying amount creates extra deferred tax (25% = 0.5 lakh); the net 1.5 lakh goes to opening retained earnings, and the 2023-24 comparatives are restated.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-552","question":"10,000 units enter a process; normal loss is 5% of input (detected at the end). 9,000 units are transferred out and 600 units remain in closing WIP, 50% converted. What are the equivalent units for conversion cost?","options":["9,300","9,700","9,200","9,400"],"answer":2,"explanation":"Units accounted for: 9,000 + 600 + normal loss 500 = 10,100, so there is an abnormal gain of 100. Conversion EU = 9,000 + 300 − 100 = 9,200. Ignoring the abnormal gain gives 9,300.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-553","question":"A component needs 2 machine hours. Those hours are otherwise used for product P, which earns ₹60 of contribution an hour. The component's variable cost to make is ₹40; a supplier offers it at ₹150. What should be done?","options":["Make, saving ₹110 a unit","Make, saving ₹10 a unit","Buy, saving ₹50 a unit","Buy, saving ₹10 a unit"],"answer":3,"explanation":"Relevant cost of making = 40 + 2 × 60 (contribution forgone on P) = ₹160 > ₹150, so buy and save ₹10 a unit. Ignoring the scarce hours makes 'make' look ₹110 cheaper.","difficulty":"very-hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-554","question":"Average usage is 300 units a day, the lead time is 10 days and the safety stock is 1,200 units. What is the reorder level?","options":["3,000 units","4,200 units","1,800 units","3,600 units"],"answer":1,"explanation":"Reorder level = average usage × lead time + safety stock = 3,000 + 1,200 = 4,200 units. 3,000 leaves no buffer against demand or delivery variations.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-555","question":"A company issues 1,00,000 equity shares of ₹10 at a premium of ₹10. Under the Companies Act, 2013 and its rules, what is the maximum underwriting commission payable?","options":["₹50,000","₹25,000","₹1,00,000","₹2,00,000"],"answer":2,"explanation":"Commission on shares may not exceed 5% of the issue price (including premium): 5% × 20 × 1,00,000 = ₹1,00,000 (for debentures the cap is 2.5%). Calculating on face value alone gives ₹50,000.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-556","question":"T takes over S in an amalgamation. S has 1,00,000 shares with an intrinsic value of ₹30 each; T's shares have an intrinsic value of ₹40. Purchase consideration is settled in T's shares on the basis of intrinsic values. How many shares does T issue?","options":["1,33,333","1,00,000","1,20,000","75,000"],"answer":3,"explanation":"Value to be paid = 1,00,000 × 30 = ₹30 lakh; at ₹40 each, T issues 75,000 shares (3 for every 4 of S). 1,33,333 inverts the ratio.","difficulty":"hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-557","question":"An investor holds 2,000 shares costing ₹2,40,000. A rights issue of 1 for 4 at ₹100 is offered and he subscribes in full. What is the average cost per share afterwards?","options":["₹116","₹120","₹100","₹96"],"answer":0,"explanation":"He gets 500 shares for ₹50,000, so 2,500 shares cost ₹2,90,000, an average of ₹116. ₹96 would apply if the new shares were free (a bonus issue).","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-558","question":"Partners A, B and C share profits 2 : 2 : 1. C retires. Premiums on a joint life policy have been charged to profit and loss each year; its surrender value is ₹50,000, and the policy is to be brought into the books. How much is credited to C?","options":["₹10,000","₹20,000","₹16,667","Nil"],"answer":0,"explanation":"Bringing the policy in at its surrender value creates ₹50,000 of hidden profit, shared in the old ratio: C gets 1/5 = ₹10,000. 'Nil' ignores that premiums charged to profit belonged to all partners.","difficulty":"moderate","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-559","question":"Under Ind AS 115, which of these points to an entity being a principal rather than an agent?","options":["It earns a fixed commission per sale","It does not hold inventory risk before the customer orders","It is primarily responsible for fulfilling the promise and has discretion over the price","The goods are shipped directly by the supplier, who bears returns"],"answer":2,"explanation":"A principal controls the good or service before transfer; indicators are primary responsibility for fulfilment, inventory risk and pricing discretion. A fixed commission and no inventory risk point to an agent.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-560","question":"Profit before tax includes an unrealised exchange loss of ₹40,000 on restating a foreign-currency term loan. How is it handled in the cash-flow statement (indirect method)?","options":["Deducted from profit in operating activities","Shown as a financing outflow","Added back to profit as a non-cash item; the loan has no cash movement from it","Shown as an investing outflow"],"answer":2,"explanation":"Unrealised exchange differences are not cash flows. The loss reduced profit without any cash leaving, so it is added back; no financing flow arises until the loan is repaid.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-561","question":"After the reporting date (31 March), which event is an ADJUSTING event under Ind AS 10?","options":["A fall in the market value of investments in April","A major customer, already in financial difficulty at 31 March, is declared bankrupt in April","Issue of new shares in May","Destruction of a factory by flood in April"],"answer":1,"explanation":"Bankruptcy after year end usually confirms the receivable was impaired at the reporting date, so it is adjusting. Market falls, share issues and floods reflect conditions arising after the reporting date.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-562","question":"A retailer sells gift cards worth ₹10 lakh and expects 10% to go unredeemed (breakage), based on reliable history. During the year cards worth ₹6 lakh are redeemed. What revenue is recognised under Ind AS 115?","options":["₹6 lakh","₹7 lakh","₹10 lakh","₹6.67 lakh"],"answer":3,"explanation":"Expected breakage is recognised in proportion to redemptions: 6 lakh redeemed out of 9 lakh expected, so breakage of 1 × 6/9 = 0.67 lakh is added: ₹6.67 lakh. Recognising all breakage at once gives ₹7 lakh.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-563","question":"A company had 10 lakh shares of ₹10 and split each into two shares of ₹5 on 1 January (year ends 31 March). Profit is ₹1.2 crore. What is basic EPS?","options":["₹6.00","₹9.60","₹12.00","₹8.00"],"answer":0,"explanation":"A share split changes the number of shares without any resources, so it is treated as if it happened at the start: 20 lakh shares, EPS = ₹6. Time-weighting the split (12.5 lakh shares) gives the wrong ₹9.60.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-564","question":"A provision of ₹5 lakh is recognised for a claim, and the company is virtually certain to recover ₹3 lakh from its insurer. Under Ind AS 37, how is this presented?","options":["Provision ₹2 lakh net","Provision ₹5 lakh and a separate asset ₹3 lakh; the P&L expense may be shown net at ₹2 lakh","Provision ₹5 lakh; the reimbursement is only disclosed","Provision ₹5 lakh and a contingent asset of ₹3 lakh disclosed"],"answer":1,"explanation":"A virtually certain reimbursement is a separate asset (not more than the provision) and cannot be netted in the balance sheet; in profit or loss the expense may be presented net of the reimbursement.","difficulty":"hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-565","question":"Fixed costs are ₹3,00,000 and the P/V ratio is 40%. What sales are needed to earn a profit equal to 20% of sales?","options":["₹7,50,000","₹10,00,000","₹15,00,000","₹12,00,000"],"answer":2,"explanation":"Contribution 40% of sales must cover fixed costs plus profit of 20% of sales, so 20% of sales = ₹3,00,000 and sales = ₹15,00,000. ₹7,50,000 is the break-even point.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-566","question":"A firm sells 10,000 units at ₹100 with variable cost ₹60. If it cuts the price by 10%, how many units must it sell to keep the same total contribution?","options":["11,000","12,000","13,000","13,334"],"answer":3,"explanation":"Present contribution = 10,000 × 40 = ₹4,00,000; the new unit contribution is 90 − 60 = ₹30, so 4,00,000/30 = 13,333.3, i.e., 13,334 units. A 10% price cut cuts contribution per unit by 25%, which 11,000 units ignores.","difficulty":"hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-567","question":"Under Ind AS 16, how are major spare parts and standby equipment that the company expects to use for more than one period treated?","options":["Always as inventory","Expensed when bought","As intangible assets","As property, plant and equipment"],"answer":3,"explanation":"Spare parts, standby and servicing equipment are PPE when they meet the definition of PPE (held for use and expected to be used over more than one period); otherwise they are inventory.","difficulty":"moderate","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-568","question":"A machine bought on 1 July 2021 for ₹8,00,000 is depreciated at 25% WDV on a time basis (year ends 31 March). It is sold on 1 October 2024 for ₹2,90,000. What is the profit or loss on sale?","options":["Loss ₹29,922","Loss ₹75,625","Loss ₹5,313","Loss ₹47,500"],"answer":0,"explanation":"2021-22: 9 months' charge ₹1,50,000 → 6,50,000; then 4,87,500 and 3,65,625 at 1 April 2024; 6 months' charge ₹45,703 → book value ₹3,19,922; loss ₹29,922. Charging a full year in 2021-22 gives ₹5,313; skipping the final half-year gives ₹75,625.","difficulty":"very-hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-569","question":"A factory with normal capacity of 10,000 units produces an abnormally high 12,000 units. Costs: materials ₹5,00,000 (including abnormal wastage ₹20,000), labour ₹3,00,000, variable overheads ₹1,00,000, fixed production overheads ₹2,00,000, administration ₹50,000, selling ₹40,000 and storage of finished goods ₹10,000. What is the cost per unit for inventory under Ind AS 2?","options":["₹91.67","₹90.00","₹93.33","₹94.17"],"answer":1,"explanation":"Include materials net of abnormal wastage (4,80,000), labour, variable overhead and fixed overhead; in abnormally high production fixed overhead is spread over actual output so inventory is not above cost: 10,80,000/12,000 = ₹90. Using the normal-capacity rate (₹20) gives ₹93.33.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-570","question":"Sales are ₹30 lakh with gross profit 25% on sales. Stock turnover is 6 times on cost (stock unchanged during the year), debtors turnover 10 times on sales (closing debtors), current ratio 2 and quick ratio 1. Current assets are stock, debtors and cash only. What is the cash balance?","options":["₹3,75,000","₹1,50,000","₹75,000","Nil"],"answer":2,"explanation":"COGS = 22.5 lakh, so stock = ₹3.75 lakh. With CR 2 and QR 1, stock equals current liabilities, so CL = 3.75 lakh and quick assets = 3.75 lakh. Debtors = 30/10 = 3 lakh, so cash = ₹75,000.","difficulty":"very-hard","source":"Bank MT · MBA finance placement"},
  {"id":"mgmt-accounting-571","question":"Debentures were ₹5 lakh at the start and ₹7 lakh at the end of the year. During the year debentures of ₹2 lakh were redeemed at a 5% premium, and new debentures were issued at a 2% discount. What is the net financing cash flow from debentures?","options":["+₹2.00 lakh","+₹1.90 lakh","+₹1.92 lakh","+₹1.82 lakh"],"answer":3,"explanation":"New issue (face) = 7 − 5 + 2 = ₹4 lakh, raising 3.92 lakh; redemption paid 2.10 lakh; net +₹1.82 lakh. Ignoring the discount gives 1.90; ignoring the premium gives 1.92.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-572","question":"Profit before appropriations is ₹2,64,000. A gets a salary of ₹24,000; B gets a commission of 10% of profit after A's salary but before the commission; interest on capital is 6% on A ₹2,00,000 and B ₹1,00,000; the balance is shared 3 : 2. What is B's total income from the firm?","options":["₹1,07,891","₹1,10,640","₹1,09,200","₹1,10,400"],"answer":2,"explanation":"Commission = 10% × 2,40,000 = 24,000; interest A 12,000, B 6,000; balance 2,64,000 − 24,000 − 24,000 − 18,000 = 1,98,000, B's 2/5 = 79,200. B total = 24,000 + 6,000 + 79,200 = ₹1,09,200. ₹1,07,891 computes commission after charging itself.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-573","question":"300 shares of ₹10 were issued at ₹12, the premium being payable with allotment. The holder paid only the application money of ₹3 and failed to pay allotment (₹5 including premium) and the call (₹4). The shares were forfeited and reissued at ₹9 each fully paid. What is transferred to capital reserve?","options":["₹600","₹900","₹300","₹1,200"],"answer":0,"explanation":"Since the premium was never received, securities premium is debited (reversed) on forfeiture, and only the ₹3 a share received is forfeited: ₹900. Reissue discount ₹1 × 300 = ₹300, leaving ₹600 for capital reserve. ₹1,200 wrongly treats the unpaid premium as forfeited money.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-574","question":"H pays ₹9 lakh for 80% of S. S's net assets have a book value of ₹8 lakh; its assets have a fair-value uplift of ₹2 lakh that is not taxable, creating a deferred tax liability at 25%. NCI is measured at its proportionate share. What goodwill arises?","options":["₹1.4 lakh","₹1.0 lakh","₹2.6 lakh","₹1.5 lakh"],"answer":0,"explanation":"Identifiable net assets = 8 + 2 − 0.5 DTL = ₹9.5 lakh; goodwill = 9 − 80% × 9.5 = ₹1.4 lakh. Ignoring the DTL on the uplift gives ₹1.0 lakh; using book values gives ₹2.6 lakh.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-575","question":"A manufacturer sells goods worth ₹10 lakh to a retailer and pays the retailer ₹50,000 for prominent shelf display; the display is not a distinct service the manufacturer could buy separately at fair value. What revenue does the manufacturer recognise under Ind AS 115?","options":["₹10 lakh, with ₹50,000 as advertising expense","₹9.5 lakh","₹10.5 lakh","₹10 lakh, with ₹50,000 as a prepaid asset"],"answer":1,"explanation":"Consideration payable to a customer that is not for a distinct good or service reduces the transaction price, so revenue is ₹9.5 lakh. Treating it as advertising would only be right if a distinct service at fair value were received.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-576","question":"A lessee pays ₹2,00,000 at the end of each year for 4 years; the discount rate is 10%, so the lease liability and ROU asset start at ₹6,33,973. The ROU asset is depreciated straight-line over 4 years. What is the total year-1 charge to profit and loss?","options":["₹2,00,000","₹1,58,493","₹2,63,397","₹2,21,891"],"answer":3,"explanation":"Depreciation 6,33,973/4 = 1,58,493 plus interest 10% × 6,33,973 = 63,397 gives ₹2,21,891, more than the cash rent in early years (front-loading). ₹2,00,000 is the old operating-lease charge.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-577","question":"A company had 30 lakh shares on 1 April. On 1 December it issued 6 lakh shares as consideration for acquiring a subsidiary, and on 1 March it made a 1-for-5 bonus issue. Profit for the year to 31 March is ₹1.92 crore. What is basic EPS?","options":["₹5.00","₹6.00","₹4.44","₹5.89"],"answer":0,"explanation":"Acquisition shares count from 1 December: 30 + 6 × 4/12 = 32 lakh; the bonus applies retrospectively to all, ×1.2 = 38.4 lakh; EPS = ₹5.00. ₹5.89 time-weights the bonus; ₹4.44 uses year-end shares.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-578","question":"Accounting profit is ₹20 lakh. It includes expenses of ₹2 lakh that are permanently disallowed for tax and income of ₹4 lakh that is permanently tax-free. There are no temporary differences and the tax rate is 25%. What is the effective tax rate?","options":["25%","22.5%","27.5%","20%"],"answer":1,"explanation":"Taxable income = 20 + 2 − 4 = ₹18 lakh; tax = 4.5 lakh; effective rate = 4.5/20 = 22.5%. Permanent differences change the effective rate, whereas temporary differences would be absorbed by deferred tax.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-579","question":"A company issues ₹10 lakh of debentures at par with an 8% annual coupon, redeemable after 2 years at a 10% premium. The effective interest rate is 12.70%. What is the amortised-cost carrying amount at the end of year 1?","options":["₹10,00,000","₹10,50,000","₹11,27,014","₹10,47,014"],"answer":3,"explanation":"Interest at EIR = 12.70% × 10,00,000 = 1,27,014; less coupon 80,000 gives ₹10,47,014, accreting towards ₹11 lakh by redemption. ₹10,50,000 spreads the premium straight-line; ₹11,27,014 forgets the coupon paid.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-580","question":"Department Z earns contribution of ₹60,000. If it is closed, ₹40,000 of fixed costs can be avoided, but sales of Department Y would fall, cutting Y's contribution by ₹30,000. What is the effect on total profit of closing Z?","options":["Falls by ₹50,000","Falls by ₹20,000","Rises by ₹10,000","Falls by ₹90,000"],"answer":0,"explanation":"Lost contribution 60,000 + knock-on loss 30,000 − fixed costs saved 40,000 = profit falls by ₹50,000. ₹20,000 ignores the effect on Department Y.","difficulty":"very-hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-581","question":"On dissolution, partner A owes the firm ₹20,000 (debit capital balance). His private assets are ₹50,000 and his private liabilities ₹70,000. Under section 49 of the Indian Partnership Act, how much does the firm recover from his private estate?","options":["₹20,000","₹50,000","Nil","₹10,000"],"answer":2,"explanation":"Private property is applied first to private debts and only the surplus goes to the firm. Private debts (₹70,000) exceed private assets (₹50,000), so nothing is left for the firm.","difficulty":"hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-582","question":"A club sells old furniture with a book value of ₹10,000 for ₹7,000. How does it appear in the club's accounts?","options":["₹7,000 in Receipts and Payments; ₹3,000 loss in Income and Expenditure","₹7,000 as income in Income and Expenditure","₹10,000 in Receipts and Payments; ₹3,000 loss in the balance sheet","₹3,000 in Receipts and Payments only"],"answer":0,"explanation":"Receipts and Payments records the cash received (₹7,000); Income and Expenditure shows only the loss on sale (₹3,000), and the furniture is removed from the balance sheet.","difficulty":"moderate","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-583","question":"Opening debtors ₹60,000; closing debtors ₹75,000. Cash received from debtors ₹4,20,000; bills receivable received ₹50,000; discount allowed ₹8,000; sales returns ₹12,000; bad debts ₹5,000; a bill receivable of ₹6,000 was dishonoured during the year. What were the credit sales?","options":["₹5,16,000","₹4,54,000","₹4,92,000","₹5,04,000"],"answer":3,"explanation":"Debtors account: debits = opening 60,000 + credit sales + dishonoured bill 6,000; credits = 4,20,000 + 50,000 + 8,000 + 12,000 + 5,000 + closing 75,000 = 5,70,000. Credit sales = 5,70,000 − 66,000 = ₹5,04,000. Adding the dishonoured bill to the credits gives ₹5,16,000.","difficulty":"very-hard","source":"Bank MT · CA Inter level"},
  {"id":"mgmt-accounting-584","question":"On 1 January an investor buys 1,000 9% debentures of ₹100 at ₹98 ex-interest; interest is paid on 31 March and 30 September. On 1 August he sells them at ₹102 cum-interest. What is the profit on sale of the investment?","options":["₹4,000","₹1,000","₹3,000","₹2,000"],"answer":1,"explanation":"The cum-interest price includes 4 months' interest (1,00,000 × 9% × 4/12 = ₹3,000), so the capital proceeds are ₹99,000 against cost of ₹98,000: profit ₹1,000. Treating the whole ₹1,02,000 as capital gives ₹4,000.","difficulty":"very-hard","source":"CA Inter level"},
  {"id":"mgmt-accounting-585","question":"A 3-year lease has annual end-of-year payments of ₹1,00,000, with an option to extend for 2 more years at ₹1,20,000 a year that the lessee is reasonably certain to exercise. The discount rate is 10%. What is the initial lease liability?","options":["₹2,48,685","₹3,79,079","₹4,05,157","₹5,40,000"],"answer":2,"explanation":"The lease term includes periods covered by an extension option reasonably certain to be exercised: 1,00,000 × 2.4869 + 1,20,000 × (0.6830 + 0.6209) = ₹4,05,157. ₹2,48,685 ignores the option; ₹3,79,079 uses ₹1,00,000 for all 5 years.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-586","question":"An investor buys 30% of an associate for ₹5 lakh. The associate earns ₹4 lakh in the year and pays a dividend of ₹1 lakh. Under the equity method (Ind AS 28), what is the carrying amount of the investment at year end?","options":["₹6.2 lakh","₹5.9 lakh","₹5.3 lakh","₹5.0 lakh"],"answer":1,"explanation":"Carrying amount = cost + share of profit − share of dividends = 5 + 1.2 − 0.3 = ₹5.9 lakh. Dividends reduce the investment rather than being income; ignoring that gives ₹6.2 lakh.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-587","question":"During the year a company bought PPE for ₹6 lakh, of which ₹1 lakh is still unpaid at year end; sold investments for ₹2 lakh (a profit of ₹0.3 lakh is in the P&L); received interest of ₹0.4 lakh and dividends of ₹0.2 lakh; and lent ₹1 lakh to an associate. What is the net cash flow from investing activities of this manufacturing company?","options":["₹4.4 lakh outflow","₹3.7 lakh outflow","₹3.4 lakh outflow","₹4.0 lakh outflow"],"answer":2,"explanation":"−5 (cash actually paid for PPE) + 2 (full sale proceeds) + 0.4 + 0.2 (investing for non-financial entities under Ind AS 7) − 1 = −₹3.4 lakh. Including the unpaid ₹1 lakh gives ₹4.4 lakh.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-588","question":"A customer pays ₹10 lakh two years before delivery, and the contract has a significant financing component at 8%. Under Ind AS 115, what revenue is recognised on delivery?","options":["₹10 lakh","₹11.6 lakh","₹8.573 lakh","₹11.664 lakh"],"answer":3,"explanation":"The company is financed by the customer, so it accrues interest expense on the contract liability: 10 × 1.08² = ₹11.664 lakh becomes revenue on delivery. Simple interest gives 11.6; discounting the advance gives the wrong 8.573.","difficulty":"very-hard","source":"Big 4 · CA Inter level"},
  {"id":"mgmt-accounting-589","question":"How does a 'capital reserve' differ from 'reserve capital' in company accounts?","options":["They are the same thing","Capital reserve is built from capital profits; reserve capital is uncalled capital that, by special resolution, can be called only on winding up","Reserve capital is built from capital profits; capital reserve is uncalled capital","Capital reserve can be freely distributed as dividend; reserve capital cannot"],"answer":1,"explanation":"Capital reserve arises from capital profits (e.g., forfeited share reissue gains, bargain purchases) and is not available for dividend. Reserve capital is part of uncalled capital that the company resolves to call only on winding up; it does not appear in the books.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-590","question":"A cash budget shows an opening balance of ₹20,000, receipts of ₹1,50,000 and payments of ₹1,82,000. The firm must keep a minimum balance of ₹25,000 and can borrow only in multiples of ₹10,000. What are the borrowing and the closing balance?","options":["Borrow ₹40,000; closing ₹28,000","Borrow ₹37,000; closing ₹25,000","Borrow ₹30,000; closing ₹18,000","Borrow ₹20,000; closing ₹8,000"],"answer":0,"explanation":"Before financing the balance is −₹12,000; reaching ₹25,000 needs ₹37,000, rounded up to ₹40,000, giving a closing balance of ₹28,000. ₹37,000 ignores the multiple-of-₹10,000 rule.","difficulty":"very-hard","source":"CA Inter level · Bank MT"},
  {"id":"mgmt-accounting-591","question":"Variable cost is ₹60 a unit and fixed costs ₹2,00,000; capacity is 10,000 units, and going beyond it needs ₹50,000 of extra fixed cost. Expected demand: 8,000 units at ₹100, 9,500 units at ₹95 or 11,000 units at ₹90. Which price maximises profit?","options":["₹100","₹90","₹95","Indifferent between ₹95 and ₹100"],"answer":2,"explanation":"Contributions: ₹100 → 8,000 × 40 = 3,20,000; ₹95 → 9,500 × 35 = 3,32,500; ₹90 → 11,000 × 30 = 3,30,000 less ₹50,000 extra fixed cost = 2,80,000. ₹95 is best; ignoring the step cost makes ₹90 look close.","difficulty":"very-hard","source":"Big 4 · MBA finance placement"},
  {"id":"mgmt-accounting-592","question":"A firm's cash book shows a bank debit balance of ₹48,500. On comparing it with the bank statement you find: cheques issued but not yet presented ₹12,000; cheques deposited but not yet credited by the bank ₹7,500; bank charges ₹400 and an insurance direct debit ₹1,800 not yet entered in the cash book; interest ₹950 credited by the bank but not in the cash book. What balance does the bank statement show?","options":["₹42,750 in favour of the firm","₹51,750 in favour of the firm","₹53,000 in favour of the firm","₹47,250 in favour of the firm"],"answer":1,"explanation":"Adjust the cash book first: 48,500 - 400 - 1,800 + 950 = 47,250. Then move to the statement: add cheques issued but unpresented (12,000) and deduct cheques deposited but uncredited (7,500) to get 51,750.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-593","question":"A machine costing ₹10,00,000 with a residual value of ₹1,00,000 was being depreciated straight-line over 9 years. At the end of year 3 management revises its estimates: the machine will last 4 more years and the residual value will be ₹60,000. What is the depreciation charge for year 4?","options":["₹1,34,286","₹1,60,000","₹1,75,000","₹1,50,000"],"answer":1,"explanation":"A change in estimate is applied prospectively: carrying amount after 3 years = 1,000,000 - 3 x 100,000 = 700,000; charge = (700,000 - 60,000) / 4 = 160,000. Restating earlier years or ignoring the new residual value is wrong.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-594","question":"A company had 10,00,000 equity shares all year. On 1 October it made a 1-for-5 rights issue at ₹40 per share; the cum-rights market price just before the issue was ₹50. The year ends 31 March (a 12-month year from 1 April) and profit available to equity holders is ₹20,00,000. What is the basic EPS, correctly adjusted for the bonus element of the rights issue?","options":["₹1.82","₹1.67","₹2.00","₹1.79"],"answer":3,"explanation":"TERP = (5 x 50 + 40)/6 = 48.33; bonus factor = 50/48.33 = 1.0345. Weighted shares = 1,000,000 x 1.0345 x 6/12 + 1,200,000 x 6/12 = 1,117,241, so EPS = 1.79. Time-weighting alone ignores the bonus element.","difficulty":"very-hard","source":"CA Intermediate · CFA Level I"},
  {"id":"mgmt-accounting-595","question":"A company reports profit before tax of ₹5,00,000 after charging depreciation ₹80,000, interest expense ₹40,000 and a loss on sale of machinery ₹15,000. During the year debtors rose by ₹60,000, inventory fell by ₹30,000 and creditors rose by ₹20,000. Using the indirect method, what is cash generated from operations before interest and tax paid?","options":["₹5,45,000","₹6,45,000","₹6,25,000","₹5,95,000"],"answer":2,"explanation":"Start from PBT and add back non-cash and financing items (depreciation, loss on sale, interest): 500,000+80,000+15,000+40,000 = 635,000. Then -60,000 for the debtor rise, +30,000 for the inventory fall and +20,000 for the creditor rise = 625,000.","difficulty":"hard","source":"Big 4 · MBA placement"},
  {"id":"mgmt-accounting-596","question":"P Ltd bought 80% of S Ltd when S's share capital was ₹3,00,000 and reserves ₹1,50,000. At the reporting date S's reserves are ₹2,10,000. During the year S sold goods to P at a profit, and ₹20,000 of that profit is unrealised in P's closing inventory. Using the proportionate method for NCI, what is the non-controlling interest in the consolidated balance sheet?","options":["₹98,000","₹1,02,000","₹38,000","₹1,06,000"],"answer":0,"explanation":"The sale is upstream (subsidiary is the seller), so the unrealised profit reduces S's net assets and is shared with NCI: 20% x (300,000 + 210,000 - 20,000) = 98,000. A downstream sale would be eliminated wholly against the parent.","difficulty":"very-hard","source":"CA Intermediate · Big 4"},
  {"id":"mgmt-accounting-597","question":"P Ltd pays ₹7,20,000 for 60% of S Ltd. The fair value of the 40% non-controlling interest at that date is ₹4,60,000 and the fair value of S's identifiable net assets is ₹9,00,000. Under the full-goodwill method, what goodwill is recognised?","options":["₹2,80,000","₹1,80,000","₹1,00,000","₹6,40,000"],"answer":0,"explanation":"Full goodwill = consideration + fair value of NCI - net assets = 720,000 + 460,000 - 900,000 = 280,000. The proportionate method would give 180,000; 100,000 is only the NCI's share.","difficulty":"very-hard","source":"CFA Level I · Big 4"},
  {"id":"mgmt-accounting-598","question":"In a process, opening WIP of 1,000 units is 60% complete for conversion; 9,000 units are started; 8,000 units are completed and transferred; closing WIP of 2,000 units is 50% complete for conversion. Materials are added at the start. Under the FIFO method, what are the equivalent units for conversion cost?","options":["9,000","9,400","7,400","8,400"],"answer":3,"explanation":"FIFO counts only this period's work: completing opening WIP 1000 x 40% = 400, started and finished 7,000, closing WIP 2000 x 50% = 1,000, total 8,400. 9,000 is the weighted-average figure and 9,400 wrongly counts all 8,000 completed units plus the 400.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-599","question":"A process takes in 10,000 kg of material and conversion costing ₹3,02,000 in total. Normal loss is 10% of input and its scrap sells at ₹5 per kg. Actual output is 8,700 kg, so some of the loss is abnormal. What net amount is charged to the profit and loss account for the abnormal loss, after crediting its scrap value?","options":["₹9,900","₹11,400","₹7,560","₹8,400"],"answer":3,"explanation":"Cost per good kg = (302,000 - 1,000 x 5)/9,000 = 33. Abnormal loss = 300 kg x 33 = 9,900; its scrap value 300 x 5 = 1,500 is credited, leaving 8,400. Normal-loss scrap is netted off from the cost pool, not the abnormal loss account.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-600","question":"A firm uses FIFO. Opening stock is 1,000 units carrying fixed overhead of ₹18 per unit; production is 10,000 units at ₹20 fixed overhead per unit; closing stock is 1,500 units. By how much does profit under absorption costing differ from marginal costing?","options":["₹12,000 higher under absorption costing","₹30,000 higher under absorption costing","₹10,000 higher under absorption costing","₹12,000 lower under absorption costing"],"answer":0,"explanation":"Absorption profit = marginal profit + fixed overhead in closing stock - fixed overhead in opening stock = 30,000 - 18,000 = 12,000 (higher, since stock rose).","difficulty":"hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-601","question":"Standard mix per 100 kg of input is 60 kg of A at ₹10 per kg and 40 kg of B at ₹20 per kg. In a period the plant used 700 kg of A and 300 kg of B (total 1,000 kg). What is the material mix variance?","options":["₹1,000 favourable","₹1,000 adverse","₹2,000 favourable","Nil, because total input equals the standard total"],"answer":0,"explanation":"Standard mix of 1,000 kg is 600 kg A and 400 kg B costing 14,000; the actual mix costs 7,000 + 6,000 = 13,000. Cheaper A was over-used, so the variance is 1,000 favourable.","difficulty":"hard","source":"CMA · CA Intermediate"},
  {"id":"mgmt-accounting-602","question":"A and B share profits 5 : 3. C is admitted for a 1/4 share, taking 1/6 from A and 1/12 from B. C pays ₹60,000 as his share of goodwill in cash. How much of this premium goes to A's capital account?","options":["₹37,500","₹30,000","₹40,000","₹27,500"],"answer":2,"explanation":"Premium is shared in the sacrificing ratio, not the old ratio: A gives 1/6 = 4/24 and B 1/12 = 2/24, so 2 : 1. A receives 60,000 x 2/3 = 40,000.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-603","question":"Shares of ₹10 are issued at a premium of ₹2, payable: application ₹3, allotment ₹5 (including the premium) and first call ₹4. A holder of 100 shares pays application and allotment but not the call; the shares are forfeited and then re-issued as fully paid at ₹9 per share. What is credited to capital reserve?","options":["₹800","₹600","₹500","₹700"],"answer":2,"explanation":"The premium was received and stays in the premium account, so the forfeited amount is 100 x (3 + 3) = 600 (application plus the share-capital part of allotment). Subtract the 100 discount on re-issue: capital reserve = 500.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-604","question":"A firm has a return on equity of 21%, a net profit margin of 5% and a debt-to-equity ratio of 0.4. All liabilities are treated as debt. What is its total asset turnover?","options":["3.0 times","10.5 times","4.2 times","2.1 times"],"answer":0,"explanation":"DuPont: ROE = margin x asset turnover x equity multiplier, and the multiplier is assets/equity = 1 + D/E = 1.4. So turnover = 0.21/(0.05 x 1.4) = 3.0; using D/E itself as the multiplier gives 10.5.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-accounting-605","question":"A trader records: opening 200 units at ₹50; purchase of 300 units at ₹60 on the 5th; issue of 250 units on the 8th; purchase of 150 units at ₹66 on the 15th; issue of 300 units on the 20th. Using the perpetual (moving) weighted-average method, what is the value of closing stock of 100 units?","options":["₹6,600","₹5,831","₹5,000","₹5,975"],"answer":3,"explanation":"After the 5th: 500 units, avg 56; after the 8th issue 250 units at 56 = 14,000; add 9,900 for 150 units gives 23,900/400 = 59.75; after issuing 300 the 100 units left are 5,975. FIFO would give 6,600 and the periodic average 5,831.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-606","question":"A building costing ₹60 lakh has three components with no residual value: structure ₹40 lakh (life 40 years), lifts ₹12 lakh (life 15 years) and air-conditioning plant ₹8 lakh (life 10 years). Under the component approach of Ind AS 16, what is the annual depreciation charge?","options":["₹1.5 lakh","₹2.6 lakh","₹2.77 lakh","₹4.0 lakh"],"answer":1,"explanation":"Each significant component is depreciated over its own life: 40/40 + 12/15 + 8/10 = 1.0 + 0.8 + 0.8 = 2.6 lakh. Using the structure's 40-year life for everything gives 1.5 lakh and understates the charge.","difficulty":"moderate","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-607","question":"A company sold 10,000 units under warranty. Past experience shows 90% will need no repair, 7% will need a minor repair costing ₹200 and 3% a major repair costing ₹1,000. What warranty provision should be recognised under Ind AS 37?","options":["₹4,40,000","₹3,00,000","₹1,40,000","₹60,00,000"],"answer":0,"explanation":"For a large population of similar items, use the expected value: 10,000 x (0.07 x 200 + 0.03 x 1,000) = 440,000. The most likely outcome (no repair) or the worst case alone does not give the best estimate.","difficulty":"moderate","source":"Big 4 · CA Intermediate"},
  {"id":"mgmt-accounting-608","question":"For a year, book depreciation is ₹1,00,000 and tax depreciation ₹1,60,000. A warranty provision of ₹40,000 was made in the books but is deductible for tax only when paid. The tax rate is 25% and there are no earlier temporary differences. What is the net deferred tax effect for the year?","options":["₹15,000 charge (net DTL increase)","₹25,000 charge (net DTL increase)","₹5,000 credit (net DTA increase)","₹5,000 charge (net DTL increase)"],"answer":3,"explanation":"Accelerated tax depreciation creates a taxable temporary difference of 60,000 (DTL 15,000). The warranty provision is a deductible temporary difference of 40,000 (DTA 10,000). Net charge = 15,000 - 10,000 = 5,000.","difficulty":"hard","source":"Big 4 · CA Intermediate"},
  {"id":"mgmt-accounting-609","question":"A software vendor sells a licence, installation and one year of support for a bundled price of ₹7,20,000. Their standalone selling prices are licence ₹6,00,000, installation ₹1,00,000 and support ₹2,00,000. How much of the transaction price is allocated to the licence under Ind AS 115?","options":["₹6,00,000","₹4,80,000","₹4,20,000","₹5,40,000"],"answer":1,"explanation":"The discount of 180,000 (900,000 - 720,000) is spread in proportion to standalone prices: 720,000 x 6/9 = 480,000. Giving the whole discount to the licence (420,000) or ignoring it (600,000) breaches the relative-price rule.","difficulty":"hard","source":"Big 4 · CA Intermediate"},
  {"id":"mgmt-accounting-610","question":"An Indian importer buys goods worth USD 10,000 on credit when the rate is ₹82/USD. The year-end rate is ₹83/USD and the payable is settled in the next year at ₹85.5/USD. What exchange loss is recognised in profit or loss in the first year (the year of purchase), and how does the entity treat the rest?","options":["₹35,000 in year 1; nil later","₹10,000 in year 1; ₹25,000 in the settlement year","Nil in year 1; ₹35,000 on settlement","₹10,000 added to inventory cost; ₹25,000 on settlement"],"answer":1,"explanation":"Monetary items are retranslated at the closing rate and the difference goes to profit or loss: year 1 = 10,000 x (83 - 82) = 10,000; on settlement 10,000 x (85.5 - 83) = 25,000. It is not capitalised into inventory.","difficulty":"moderate","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-611","question":"A partner draws ₹20,000 at the start of every quarter of the calendar year. Interest on drawings is charged at 6% per annum. What is the interest chargeable for the year?","options":["₹1,800","₹2,400","₹3,000","₹4,800"],"answer":2,"explanation":"Drawings at the start of each quarter stay out for 12, 9, 6 and 3 months, i.e. 30 months in all: 20,000 x 6% x 30/12 = 3,000. Drawings at quarter-ends would give 1,800.","difficulty":"moderate","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-612","question":"From incomplete records, a trader's capital is ₹4,20,000 at the start and ₹5,40,000 at the end of the year. During the year he withdrew ₹90,000 for personal use and brought in additional capital of ₹30,000. What profit did the business earn?","options":["₹1,20,000","₹2,40,000","₹1,80,000","₹1,50,000"],"answer":2,"explanation":"Closing capital = opening capital + capital introduced + profit - drawings, so profit = 540,000 - 420,000 - 30,000 + 90,000 = 180,000.","difficulty":"moderate","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-613","question":"A lessee agrees to pay ₹1,50,000 at the start of each of 4 years; the rate implicit in the lease is 12%. What interest expense is recognised in year 1?","options":["₹43,233","₹61,233","₹72,000","₹54,672"],"answer":0,"explanation":"Payments are in advance, so PV = 150,000 x (1 + 1/1.12 + 1/1.12^2 + 1/1.12^3) = 510,275. The first payment is made at once, so interest runs only on 360,275: 43,233.","difficulty":"very-hard","source":"CFA Level I · Big 4"},
  {"id":"mgmt-accounting-614","question":"Overheads: setup cost ₹6,00,000 (driver: number of setups) and machine cost ₹9,00,000 (driver: machine hours). Product P needs 40 of the 60 setups and 3,000 of the 9,000 machine hours, and 10,000 units of P are made. What is the activity-based overhead per unit of P?","options":["₹50","₹40","₹30","₹70"],"answer":3,"explanation":"Setup pool: 600,000 x 40/60 = 400,000; machine pool: 900,000 x 3,000/9,000 = 300,000; total 700,000/10,000 = 70 per unit. Spreading all overhead on machine hours alone gives 50; using only one pool gives 40 or 30.","difficulty":"hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-615","question":"A firm sells products A and B in the fixed ratio 3 : 1. A sells at ₹50 with variable cost ₹30; B sells at ₹80 with variable cost ₹50. Fixed costs are ₹4,50,000. How many units in total (A and B together) must be sold to break even?","options":["18,000","20,000","22,500","15,000"],"answer":1,"explanation":"Each pack of 4 units earns 3 x 20 + 1 x 30 = 90, so break-even needs 450,000/90 = 5,000 packs = 20,000 units. The equal-mix average (25 per unit) would give 18,000.","difficulty":"hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-616","question":"A head office sends goods to its branch at cost plus 25% on cost. Closing stock at the branch is valued at invoice price ₹70,000, and the opening stock reserve was ₹10,000. What stock reserve (unrealised profit) must be carried at the year end?","options":["₹17,500","₹14,000","₹10,000","₹4,000"],"answer":1,"explanation":"Loading is 25% on cost = 20% of invoice price (25/125), so reserve = 70,000 x 20% = 14,000; the P&L charge for the year is only the 4,000 increase. Taking 25% of invoice price (17,500) overstates it.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-617","question":"Using a 360-day year: average inventory ₹6,00,000, cost of goods sold ₹36,00,000, average debtors ₹9,00,000, credit sales ₹54,00,000, average creditors ₹3,00,000, credit purchases ₹30,00,000. What is the operating cycle's net cash conversion period?","options":["120 days","90 days","84 days","156 days"],"answer":2,"explanation":"Inventory days = 60, receivable days = 60 and payable days = 3/30 x 360 = 36 (payables are measured on purchases, not COGS). Cash conversion = 60 + 60 - 36 = 84 days.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-accounting-618","question":"A company issues 2,000 debentures of ₹100 each at a 4% discount, redeemable after 4 years at a premium of 8%. The total loss on issue is written off in equal annual instalments. What balance of 'loss on issue of debentures' remains at the end of year 2?","options":["₹24,000","₹8,000","₹12,000","₹18,000"],"answer":2,"explanation":"Total loss = discount 4 + redemption premium 8 = 12 per debenture, i.e. 24,000 on 2,000 debentures. Written off over 4 years, half remains after 2 years: 12,000.","difficulty":"moderate","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-619","question":"A company redeems ₹5,00,000 of preference shares at a 10% premium. It issues fresh equity shares of ₹2,00,000 at par for the purpose, and distributable profits are ample. What amount must be transferred to Capital Redemption Reserve?","options":["₹5,00,000","₹3,50,000","₹3,00,000","₹2,00,000"],"answer":2,"explanation":"CRR equals the nominal value redeemed out of profits, i.e. 5,00,000 - 2,00,000 of fresh issue = 3,00,000. The 50,000 redemption premium is paid out of profits or securities premium and does not enter CRR.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-620","question":"A company buys back 20,000 fully paid shares of ₹10 at ₹25 each, without a fresh issue. Securities premium stands at ₹1,50,000 and the buy-back is financed entirely from reserves. By how much does the general reserve fall in total, including the transfer to Capital Redemption Reserve (the premium may be adjusted against securities premium)?","options":["₹1,50,000","₹5,00,000","₹3,50,000","₹2,00,000"],"answer":2,"explanation":"Total payout = 500,000. Premium of 300,000 is met first from securities premium (150,000); the other 150,000 comes from general reserve. A further 200,000 is moved from general reserve to CRR, so the reserve falls by 350,000.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-621","question":"Under the purchase method, T Ltd's business is acquired. Assets taken over (agreed values) are ₹12,50,000; liabilities taken over are ₹3,40,000. The purchase consideration is ₹8,50,000. How is the difference recorded?","options":["Goodwill of ₹60,000","Capital reserve of ₹60,000","Capital reserve of ₹4,00,000","Goodwill of ₹4,00,000"],"answer":1,"explanation":"Net assets acquired = 1,250,000 - 340,000 = 910,000, which exceeds the purchase consideration of 850,000, so the 60,000 excess is capital reserve (a bargain). Forgetting the liabilities gives 4,00,000.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-622","question":"A firm has current assets of ₹5,00,000 (inventory ₹2,00,000, the rest are quick assets) and current liabilities of ₹2,50,000. It then sells inventory costing ₹80,000 on credit for ₹1,00,000 and repays a ₹50,000 short-term bank loan out of cash. What is its quick ratio afterwards?","options":["1.40","1.75","2.00","1.65"],"answer":1,"explanation":"Quick assets rise by the credit sale at selling price (+1,00,000 debtors) and fall by the cash repayment (-50,000): 3,50,000. Current liabilities fall to 2,00,000, so 3.5/2 = 1.75. Valuing the sale at cost gives 1.65.","difficulty":"hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-accounting-623","question":"Annual demand is 30,000 units; ordering cost is ₹60 per order; holding cost is 20% of unit price. The normal price is ₹50 per unit, but the supplier offers ₹49 per unit if orders are placed in lots of 1,500 units. By how much does the annual total cost (purchase, ordering and holding) fall if the firm accepts the discount instead of ordering the EOQ?","options":["₹30,000","₹25,500","₹27,450","₹25,650"],"answer":2,"explanation":"EOQ = sqrt(2 x 30,000 x 60/10) = 600, giving a total of 1,506,000. At 1,500 units: purchase 1,470,000, ordering 1,200, holding 7,350 = 1,478,550. Saving = 27,450, well below the raw price saving of 30,000 once extra holding cost is counted.","difficulty":"very-hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-624","question":"A joint process costing ₹3,00,000 yields X (1,000 kg) and Y (2,000 kg). X needs further processing of ₹20 per kg after split-off and then sells at ₹150 per kg; Y is sold at split-off for ₹80 per kg. Using the net realisable value method, how much of the joint cost is allocated to X?","options":["₹1,45,161","₹1,34,483","₹1,00,000","₹1,50,000"],"answer":1,"explanation":"NRV of X = (150 - 20) x 1,000 = 130,000 and of Y = 160,000, total 290,000. X bears 3,00,000 x 130/290 = 134,483. Using final sales value without deducting further processing gives 1,45,161.","difficulty":"hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-625","question":"A firm makes a part at a variable cost of ₹40 per unit and absorbs fixed overhead of ₹15 per unit, of which only 60% would be avoided if production stopped. A supplier offers the part at ₹52. The firm needs 20,000 units a year. What is the best decision and its annual effect?","options":["Buy; saves ₹60,000","Make; saves ₹60,000","Make; saves ₹2,40,000","Make; saves ₹1,20,000"],"answer":1,"explanation":"Relevant cost of making = 40 + 60% x 15 = 49 per unit, against 52 to buy, so making saves 3 x 20,000 = 60,000. Comparing the full absorbed cost (55) with 52 wrongly says buy.","difficulty":"hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-626","question":"Standard labour is 4 hours per unit at ₹50 per hour. In a month 2,000 units are made. Workers are paid for 8,400 hours (wages ₹4,41,000), of which 300 hours were idle because of a power failure. What is the labour efficiency variance?","options":["₹5,000 adverse","₹20,000 adverse","₹15,000 adverse","₹21,000 adverse"],"answer":0,"explanation":"Efficiency variance is measured on hours actually worked: (8,000 - 8,100) x 50 = 5,000 adverse. Idle time (300 x 50 = 15,000) and the rate variance (441,000 - 8,400 x 50 = 21,000) are separate; together they total the 41,000 adverse labour cost variance.","difficulty":"very-hard","source":"CMA · CA Intermediate"},
  {"id":"mgmt-accounting-627","question":"Service departments S1 and S2 have primary costs of ₹40,000 and ₹20,000. S1's output is used 20% by S2 and 80% by production; S2's output is used 10% by S1 and 90% by production. Using the simultaneous (reciprocal) method, what is S1's total cost to be apportioned?","options":["₹42,000","₹40,000","₹44,000","₹42,857"],"answer":3,"explanation":"S1 = 40,000 + 0.10 S2 and S2 = 20,000 + 0.20 S1. Substituting gives S1 = 42,000 + 0.02 S1, so S1 = 42,857. A single round of iteration (42,000) stops short; 40,000 ignores S2's service entirely.","difficulty":"very-hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-628","question":"A construction contract with a fixed price of ₹40 lakh is recognised over time using the cost-to-cost method. At year end, costs incurred are ₹30 lakh and further costs to complete are estimated at ₹20 lakh. What total loss is recognised in profit or loss for the year, including any provision for the onerous contract?","options":["₹6 lakh","₹10 lakh","₹4 lakh","₹20 lakh"],"answer":1,"explanation":"Stage of completion = 30/50 = 60%, so revenue = 24 lakh and cost 30 lakh gives a 6 lakh loss to date. The expected total loss of 10 lakh must be recognised at once, so the remaining 4 lakh goes into a provision; total = 10 lakh.","difficulty":"very-hard","source":"Big 4 · CA Intermediate"},
  {"id":"mgmt-accounting-629","question":"A firm's credit sales for January, February and March are ₹2,00,000, ₹3,00,000 and ₹4,00,000. Customers pay 30% in the month of sale (taking a 2% discount), 50% in the following month and 18% in the second month after sale; the remaining 2% is never collected. What is the cash collected in March?","options":["₹3,06,000","₹3,07,600","₹3,21,600","₹3,03,600"],"answer":3,"explanation":"March cash = 30% x 98% x 4,00,000 + 50% x 3,00,000 + 18% x 2,00,000 = 1,17,600 + 1,50,000 + 36,000 = 303,600. The 2% bad-debt portion is never received, and the discount applies only to the same-month receipts.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-630","question":"Average annual profit of a firm is ₹3,60,000, which includes a non-recurring gain of ₹60,000 and is stated after an abnormal loss of ₹30,000. Capital employed is ₹20,00,000 and the normal rate of return is 12%. What is goodwill by capitalisation of super profits?","options":["₹10,00,000","₹2,70,000","₹7,50,000","₹27,50,000"],"answer":2,"explanation":"Adjusted profit = 3,60,000 - 60,000 + 30,000 = 3,30,000; normal profit = 2,40,000; super profit = 90,000; capitalised at 12% gives 750,000. Skipping the adjustments gives 10,00,000.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-631","question":"A firm's godown is damaged by fire. Stock at the date of the fire, computed from the trading records, is ₹1,00,000, of which salvage is ₹20,000. The stock was insured under a policy of ₹75,000 with an average clause. What insurance claim is payable?","options":["₹75,000","₹80,000","₹60,000","₹55,000"],"answer":2,"explanation":"Net loss = 1,00,000 - 20,000 = 80,000. With the average clause, claim = loss x policy/value at risk = 80,000 x 75,000/1,00,000 = 60,000, which is below the policy limit.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-632","question":"A and B share profits 3 : 2. C is admitted for a 1/5 share, with a guarantee that his share of profit will not be below ₹1,00,000; A and B will bear any shortfall equally. If the year's profit is ₹4,00,000, what is A's final share of profit?","options":["₹1,72,000","₹1,80,000","₹1,92,000","₹1,82,000"],"answer":3,"explanation":"C's 1/5 = 80,000, so the shortfall is 20,000, borne equally. A's normal share = 4,00,000 x 4/5 x 3/5 = 1,92,000, less 10,000 = 182,000. Bearing it in the 3 : 2 ratio would give 1,80,000.","difficulty":"moderate","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-633","question":"An investor buys 30% of an associate for ₹9,00,000. At that date an item of plant in the associate had a fair value ₹4,00,000 above its book value (remaining life 8 years). In the year the associate earns profit of ₹6,00,000 and pays dividends of ₹2,00,000. Under the equity method, what is the carrying amount of the investment at year end?","options":["₹10,20,000","₹10,05,000","₹10,80,000","₹11,25,000"],"answer":1,"explanation":"Associate's profit is adjusted for the extra depreciation on the fair-value uplift (400,000/8 = 50,000): 5,50,000. Investor's share = 1,65,000. Dividends reduce the carrying amount (30% x 2,00,000 = 60,000): 9,00,000 + 1,65,000 - 60,000 = 1,005,000.","difficulty":"very-hard","source":"CFA Level I · Big 4"},
  {"id":"mgmt-accounting-634","question":"Land is carried at cost of ₹50 lakh under the revaluation model. It is revalued to ₹80 lakh in year 1, ₹60 lakh in year 2 and ₹35 lakh in year 3. What is charged to profit or loss in year 3 (assuming the surplus reserve is not transferred out earlier)?","options":["₹15 lakh","₹25 lakh","₹10 lakh","₹45 lakh"],"answer":0,"explanation":"The 30 lakh surplus is in OCI. Year 2's fall of 20 lakh reduces it to 10 lakh. Year 3's fall of 25 lakh uses the remaining 10 lakh of reserve and the other 15 lakh (the fall below original cost 50 - 35) goes to profit or loss.","difficulty":"moderate","source":"Big 4 · CA Intermediate"},
  {"id":"mgmt-accounting-635","question":"A qualifying asset is built over 8 months. A specific loan of ₹10 crore at 9% p.a. funds it, and unused funds earned ₹0.2 crore of temporary investment income. In addition ₹4 crore of general borrowings (weighted average rate 10%) were used for 6 months. What borrowing cost is capitalised?","options":["₹0.6 crore","₹0.8 crore","₹0.4 crore","₹1.0 crore"],"answer":0,"explanation":"Specific loan: 10 x 9% x 8/12 = 0.6, less 0.2 investment income = 0.4. General pool on the 4 crore used: 4 x 10% x 6/12 = 0.2. Total capitalised = 0.6 crore; income on specific borrowings is deducted, not added.","difficulty":"very-hard","source":"Big 4 · CA Intermediate"},
  {"id":"mgmt-accounting-636","question":"A company issues 3-year bonds of ₹10,00,000 face value with an 8% annual coupon, at a price of ₹9,50,263, giving an effective interest rate of 10%. What is the carrying amount of the liability at the end of year 2, under the effective interest (amortised cost) method?","options":["₹9,81,818","₹9,83,421","₹9,65,289","₹9,90,000"],"answer":0,"explanation":"Year 1: 950,263 x 1.10 - 80,000 = 965,289. Year 2: 965,289 x 1.10 - 80,000 = 981,818. Straight-line amortisation of the discount would wrongly give 983,421.","difficulty":"very-hard","source":"CFA Level I · Big 4"},
  {"id":"mgmt-accounting-637","question":"A company has net profit of ₹5,00,000 and 1,00,000 equity shares. It also has ₹10,00,000 of 10% convertible debentures, convertible into 20,000 equity shares; the tax rate is 25%. What is the diluted EPS?","options":["₹4.79","₹4.17","₹5.00","₹5.75"],"answer":0,"explanation":"On assumed conversion the after-tax interest (1,00,000 x 75% = 75,000) is added back and the 20,000 new shares are included: 5,75,000/1,20,000 = 4.79. Adding back pre-tax interest gives 5.00, and ignoring the added shares gives 5.75.","difficulty":"very-hard","source":"CFA Level I · CA Intermediate"},
  {"id":"mgmt-accounting-638","question":"Division A makes a component at a variable cost of ₹30 and sells all it can (at full capacity) to outside buyers at ₹50. A sale to Division B would save ₹4 per unit of selling and packing cost. Division B can buy the same component externally for ₹45. What is the minimum transfer price at which A should be willing to supply B?","options":["₹30","₹50","₹45","₹46"],"answer":3,"explanation":"At full capacity the opportunity cost of an internal sale is the lost external contribution: minimum transfer price = outside price less savings = 50 - 4 = 46 (variable cost 30 plus the 16 contribution forgone). Note that 46 exceeds B's external price of 45, so no transfer should happen.","difficulty":"hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-639","question":"The first batch of a product takes 100 labour hours. The process follows a 90% cumulative-average learning curve (each doubling of cumulative output cuts the cumulative average time per batch to 90% of its previous value). How many total hours do the first four batches take?","options":["360 hours","291.6 hours","370 hours","324 hours"],"answer":3,"explanation":"Cumulative average for 2 batches = 90; for 4 batches = 90 x 0.9 = 81; total = 4 x 81 = 324 hours. Applying 90% to every batch (360) or treating each later batch as 90 hours (370) misreads the curve.","difficulty":"hard","source":"CMA · MBA placement"},
  {"id":"mgmt-accounting-640","question":"A division invests ₹50 lakh and earns ₹8 lakh; the group's cost of capital is 12%. A new project needs ₹10 lakh and will earn ₹1.4 lakh a year. Which statement is correct if the manager is judged on each measure?","options":["ROI falls (16% to about 15.7%) but residual income rises (₹2.0 lakh to ₹2.2 lakh)","ROI rises and residual income rises","ROI falls and residual income falls","ROI rises but residual income falls"],"answer":0,"explanation":"Before: ROI 16.0%, RI = 8 - 6 = 2.0. After: ROI = 9.4/60 = 15.67%, RI = 9.4 - 7.2 = 2.2. The project beats the 12% hurdle but is below the divisional average, so an ROI-judged manager may reject it while RI would accept it.","difficulty":"very-hard","source":"CFA Level I · MBA placement"},
  {"id":"mgmt-accounting-641","question":"A machine costing ₹8,00,000 was bought on 1 October 2021 and is depreciated at 20% a year on the written-down value, pro rata by months, with a year end of 31 March. It is sold on 1 January 2024 for ₹4,60,000. What is the profit or loss on sale?","options":["Loss of ₹1,16,000","Loss of ₹29,600","Loss of ₹800","Loss of ₹87,200"],"answer":1,"explanation":"WDV: year 1 (6 months) 80,000 gives 7,20,000; year 2 gives 5,76,000; year 3 (9 months to 1 Jan) 86,400 gives 489,600. Sale 4,60,000 means a loss of 29,600. Charging no depreciation in the year of sale gives 1,16,000.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-642","question":"A firm's draft profit is ₹3,00,000. Later it is found that: (i) furniture bought for ₹20,000 was debited to purchases (furniture depreciates at 10% a year, charged for a full year); (ii) closing stock is overvalued by ₹15,000; (iii) rent of ₹8,000 for the year was never recorded; (iv) the proprietor's drawings of ₹10,000 were debited to salaries. What is the corrected profit?","options":["₹3,05,000","₹3,07,000","₹2,85,000","₹2,65,000"],"answer":0,"explanation":"Furniture was wrongly expensed: +20,000, less depreciation 2,000. Overvalued stock: -15,000. Unrecorded rent: -8,000. Drawings wrongly expensed: +10,000. Net = 305,000. Forgetting the depreciation on furniture gives 3,07,000.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-643","question":"An entity incurs ₹4,00,000 on research and, after meeting all Ind AS 38 recognition criteria for a development project, a further ₹6,00,000, of which ₹80,000 was staff training and ₹50,000 was general administrative overhead not directly attributable to the project. What is capitalised as an intangible asset?","options":["₹5,20,000","₹5,50,000","₹10,00,000","₹4,70,000"],"answer":3,"explanation":"Research costs are always expensed. After the criteria are met, only directly attributable development costs are capitalised: 6,00,000 - 80,000 (training) - 50,000 (admin overhead) = 4,70,000.","difficulty":"hard","source":"Big 4 · CA Intermediate"},
  {"id":"mgmt-accounting-644","question":"A machine bought for ₹5,00,000 is depreciated at 20% a year on the written-down value, with depreciation charged for part years. It is sold for ₹2,70,000 exactly 2½ years after purchase. What is the profit or loss on sale?","options":["Loss of ₹50,000","Loss of ₹18,000","Profit of ₹14,000","Profit of ₹20,000"],"answer":1,"explanation":"WDV after 2 years = 5,00,000 × 0.8² = 3,20,000; half-year depreciation = 32,000, so book value = 2,88,000 and loss = 18,000. Skipping the half-year charge gives a ₹50,000 loss; charging a full year gives a ₹14,000 profit.","difficulty":"hard","source":"CA Intermediate · bank SO"},
  {"id":"mgmt-accounting-645","question":"A company changes its depreciation method for plant from straight-line to written-down value because the pattern of benefits has changed. Under Ind AS 8 (and AS 10), how is the change treated?","options":["As a change in accounting policy, applied retrospectively with restated comparatives","As a prior-period error, corrected in opening retained earnings","As a change in accounting estimate, applied prospectively","As an extraordinary item shown separately in profit or loss"],"answer":2,"explanation":"The depreciation method reflects the expected pattern of consuming benefits, so changing it is a change in accounting estimate, applied from the period of change onwards. Comparatives are not restated, and it is not an error.","difficulty":"very-hard","source":"CA Intermediate · Big 4 audit"},
  {"id":"mgmt-accounting-646","question":"The cash book shows a debit balance of ₹25,000. Cheques issued but not presented total ₹8,000; cheques deposited but not yet credited ₹5,000; bank charges of ₹300 and interest credited of ₹700 are not in the cash book; and a customer paid ₹2,000 directly into the bank. What is the balance as per the passbook?","options":["₹30,400","₹19,600","₹29,600","₹26,400"],"answer":0,"explanation":"Start with 25,000: add unpresented cheques 8,000, deduct uncredited deposits 5,000, deduct charges 300, add interest 700 and the direct deposit 2,000: ₹30,400. Reversing the signs of the cheque items gives ₹19,600.","difficulty":"hard","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-647","question":"A trial balance fails to agree and the difference is put in a suspense account. The only errors are: (i) the sales book is overcast by ₹1,000; (ii) a ₹5,000 credit purchase is posted to the supplier's account as ₹500; (iii) discount allowed of ₹200 is posted to the credit of the discount account. What was the suspense account balance?","options":["₹3,100 debit","₹3,300 credit","₹3,100 credit","₹4,500 credit"],"answer":2,"explanation":"Credit side: +1,000 (sales overcast), −4,500 (supplier short), +200 wrongly credited to discount; debit side −200 (discount not debited). Net credits are short by 4,500 − 1,000 − 400 = 3,100, so suspense shows ₹3,100 credit. Counting the discount error only once gives ₹3,300.","difficulty":"very-hard","source":"CA Intermediate · bank SO"},
  {"id":"mgmt-accounting-648","question":"Opening stock is 100 units at ₹10; purchases are 200 units at ₹12, then 100 units at ₹15. 250 units are sold during the period. Under FIFO (periodic), what is the cost of goods sold?","options":["₹3,062.50","₹2,800","₹3,300","₹2,100"],"answer":1,"explanation":"FIFO issues the oldest first: 100 × 10 + 150 × 12 = ₹2,800, leaving 50 × 12 + 100 × 15 = ₹2,100 in closing stock. Weighted average gives ₹3,062.50 and periodic LIFO ₹3,300.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-649","question":"Closing inventory cost ₹50,000. It can be sold for ₹55,000, but completing and selling it will cost ₹8,000. At what value is it shown in the balance sheet?","options":["₹50,000","₹55,000","₹42,000","₹47,000"],"answer":3,"explanation":"Inventory is valued at the lower of cost and net realisable value. NRV = 55,000 − 8,000 = ₹47,000, which is below cost, so it is written down to ₹47,000.","difficulty":"moderate","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-650","question":"A and B share profits equally with capitals of ₹60,000 and ₹40,000. C is admitted for a 1/4 share and brings ₹50,000 as capital, but nothing separately for goodwill. What is the firm's hidden goodwill?","options":["₹50,000","₹1,00,000","₹2,00,000","₹37,500"],"answer":0,"explanation":"C's capital implies a total capital of 50,000 × 4 = ₹2,00,000; actual combined capital = 60,000 + 40,000 + 50,000 = 1,50,000; hidden goodwill = ₹50,000. ₹2,00,000 is the implied total capital, not the goodwill.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-651","question":"A, B and C share profits 5:3:2. C retires and A and B take over his share in the ratio 3:2. What is the new profit-sharing ratio of A and B?","options":["5:3","3:2","31:19","29:21"],"answer":2,"explanation":"A gets 5/10 + 2/10 × 3/5 = 0.62 and B gets 3/10 + 2/10 × 2/5 = 0.38, i.e. 31:19. 3:2 is the gaining ratio, and 5:3 would apply only if they took C's share in their old ratio.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-652","question":"A partnership deed allows interest on capital: ₹24,000 to A and ₹16,000 to B. Profit for the year before such interest is only ₹30,000. How is the profit distributed?","options":["A ₹15,000, B ₹15,000","A ₹24,000, B ₹6,000","A ₹18,000, B ₹12,000","A ₹24,000, B ₹16,000, with a ₹10,000 loss shared equally"],"answer":2,"explanation":"Interest on capital is an appropriation of profit, so when profit is insufficient it is limited to the profit and divided in the ratio of the interest amounts, 24:16 = 3:2: A ₹18,000 and B ₹12,000.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-653","question":"100 shares of ₹10 each, ₹8 called up, are forfeited after the holder paid only ₹5 a share. They are reissued as fully paid for ₹7 a share. How much is transferred to capital reserve?","options":["₹500","₹300","₹0","₹200"],"answer":3,"explanation":"Forfeited shares account is credited with the amount received, ₹500. Reissue at ₹7 for a ₹10 share is a ₹300 discount, written off against it, leaving ₹200 for capital reserve. ₹500 ignores the reissue discount.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-654","question":"Application money is ₹3 and allotment money ₹4 a share. Under pro-rata allotment, an applicant who applied for 300 shares is allotted 200, and the excess application money is adjusted against allotment. How much must he pay on allotment?","options":["₹500","₹800","₹200","₹300"],"answer":0,"explanation":"Excess application money = 100 × ₹3 = ₹300. Allotment due = 200 × ₹4 = ₹800; he pays 800 − 300 = ₹500. ₹800 forgets the adjustment.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-655","question":"A company issues 1,000 debentures of ₹100 each at ₹95, redeemable at ₹105. How much loss on issue of debentures is recorded at the time of issue?","options":["₹5,000","₹10,000","₹15,000","₹0"],"answer":1,"explanation":"Loss on issue = discount on issue (₹5) + premium payable on redemption (₹5) = ₹10 × 1,000 = ₹10,000. The premium is a liability created at issue, so it is part of the loss; ₹5,000 counts only the discount.","difficulty":"moderate","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-656","question":"Net profit is ₹1,00,000. Depreciation is ₹20,000; debtors increased by ₹15,000; inventory decreased by ₹10,000; creditors increased by ₹5,000; and the profit includes ₹8,000 gain on selling machinery. What is cash from operating activities (indirect method)?","options":["₹1,28,000","₹1,12,000","₹92,000","₹98,000"],"answer":1,"explanation":"1,00,000 + 20,000 − 8,000 (gain is investing) − 15,000 + 10,000 + 5,000 = ₹1,12,000. Adding the gain instead of deducting it gives ₹1,28,000; reversing the inventory sign gives ₹92,000.","difficulty":"very-hard","source":"CA Intermediate · bank SO"},
  {"id":"mgmt-accounting-657","question":"For a manufacturing company under AS 3 / Ind AS 7, which of these is a cash flow from INVESTING activities?","options":["Cash paid to suppliers for raw materials","Proceeds from issue of debentures","Purchase of another company's shares held as an investment","Repayment of a long-term bank loan"],"answer":2,"explanation":"Investing activities cover buying and selling long-term assets and investments not held for trading. Supplier payments are operating; debenture issue and loan repayment are financing.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-658","question":"A firm's current ratio is 2.5 and its quick ratio 1.5. Current liabilities are ₹80,000 and there are no prepaid expenses. What is its inventory?","options":["₹1,20,000","₹2,00,000","₹40,000","₹80,000"],"answer":3,"explanation":"Current assets = 2.5 × 80,000 = 2,00,000; quick assets = 1.5 × 80,000 = 1,20,000; inventory = the difference = ₹80,000. ₹1,20,000 is the quick assets.","difficulty":"hard","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-659","question":"A company's current ratio is 0.8:1. It pays a trade creditor in cash. What happens to the current ratio?","options":["It falls","It rises","It stays unchanged","It rises only if the payment exceeds working capital"],"answer":0,"explanation":"Equal reductions in both numerator and denominator push a ratio away from 1. With CA 80 and CL 100, paying 20 gives 60/80 = 0.75, a fall. If the ratio were above 1 it would rise instead.","difficulty":"very-hard","source":"Bank SO · CA Intermediate"},
  {"id":"mgmt-accounting-660","question":"Sales are ₹6,00,000 and the gross profit is 25% on COST. Opening inventory is ₹50,000 and closing ₹70,000. What is the inventory turnover ratio?","options":["7.5 times","10 times","8 times","6.86 times"],"answer":2,"explanation":"COGS = 6,00,000 × 100/125 = 4,80,000; average inventory = 60,000; turnover = 8 times. Treating 25% as a margin on sales gives COGS of 4,50,000 and 7.5 times.","difficulty":"hard","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-661","question":"A company's ROE is 18%, its net profit margin 6% and its total asset turnover 1.5. What is its total liabilities-to-equity ratio?","options":["2.0","1.0","0.5","3.0"],"answer":1,"explanation":"ROE = margin × turnover × equity multiplier, so EM = 18/(6 × 1.5) = 2.0 = assets/equity. Liabilities/equity = EM − 1 = 1.0. Reporting the equity multiplier itself (2.0) is the trap.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-662","question":"Sales are ₹10,00,000, variable costs ₹6,00,000 and fixed costs ₹3,00,000. What sales are needed to earn a profit of ₹2,00,000?","options":["₹12,50,000","₹7,50,000","₹8,33,333","₹15,00,000"],"answer":0,"explanation":"P/V ratio = 4,00,000/10,00,000 = 40%; required sales = (FC + target profit)/P/V = 5,00,000/0.4 = ₹12,50,000. ₹7,50,000 is break-even sales.","difficulty":"hard","source":"CA Intermediate · bank SO"},
  {"id":"mgmt-accounting-663","question":"A product sells 15,000 units at ₹50 with variable cost ₹30 and fixed costs ₹2,00,000. If the price is cut by 10%, how many units must be sold to keep profit unchanged?","options":["16,667","18,000","13,333","20,000"],"answer":3,"explanation":"Present profit = 15,000 × 20 − 2,00,000 = 1,00,000. New contribution = 45 − 30 = ₹15, so units = (2,00,000 + 1,00,000)/15 = 20,000. 13,333 is only the new break-even volume.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-664","question":"Standard: 1,000 kg of material at ₹20 per kg for the actual output. Actual: 1,100 kg bought and used at ₹19 per kg. What is the material usage variance?","options":["₹1,100 favourable","₹2,000 adverse","₹900 adverse","₹1,900 adverse"],"answer":1,"explanation":"Usage variance = SP × (SQ − AQ) = 20 × (1,000 − 1,100) = ₹2,000 adverse. The price variance is 1,100 × (20 − 19) = ₹1,100 favourable, and the total cost variance ₹900 adverse.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-665","question":"Workers are paid for 2,200 hours at ₹50 an hour (standard rate ₹48), of which 200 hours were idle owing to a power failure. Standard hours for actual output are 1,900. What is the labour efficiency variance?","options":["₹4,800 adverse","₹14,400 adverse","₹4,800 favourable","₹9,600 adverse"],"answer":0,"explanation":"Efficiency variance uses hours actually worked: 48 × (1,900 − 2,000) = ₹4,800 adverse. Idle time is a separate variance (200 × 48 = ₹9,600 adverse); lumping it in gives ₹14,400.","difficulty":"very-hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-666","question":"Budgeted overheads are ₹5,00,000 for 25,000 machine hours. Actual overheads are ₹5,40,000 and actual machine hours 28,000. What is the under- or over-absorption?","options":["₹40,000 under-absorbed","₹60,000 over-absorbed","₹20,000 under-absorbed","₹20,000 over-absorbed"],"answer":3,"explanation":"Rate = ₹20 per hour; absorbed = 28,000 × 20 = 5,60,000 against actual 5,40,000, so ₹20,000 is over-absorbed. Comparing actual with budget (₹40,000) ignores the higher activity.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-667","question":"1,000 units costing ₹50,000 enter a process, with conversion costs of ₹10,000. Normal loss is 10% of input and can be sold as scrap for ₹5 a unit. Output is exactly 900 units. What is the cost per good unit?","options":["₹66.67","₹66.11","₹65.56","₹60.00"],"answer":1,"explanation":"Cost per unit = (60,000 − 100 × 5)/(1,000 − 100) = 59,500/900 = ₹66.11. Ignoring the scrap value gives ₹66.67; normal loss is absorbed by good units, so dividing by 1,000 (₹60) is wrong.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-668","question":"Rent paid during the year was ₹13,000. This includes ₹1,000 paid in advance for next year and ₹2,000 that was outstanding from last year. Rent of ₹1,500 for this year is still unpaid. What rent expense goes to this year's profit and loss account?","options":["₹13,500","₹11,500","₹12,500","₹10,500"],"answer":1,"explanation":"Expense = 13,000 − 1,000 (prepaid) − 2,000 (last year's) + 1,500 (outstanding) = ₹11,500. Forgetting to remove last year's arrears gives ₹13,500.","difficulty":"moderate","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-669","question":"Debtors are ₹1,00,000 before writing off further bad debts of ₹4,000. A provision for doubtful debts of 5% is required; the existing provision is ₹3,000. What is the total charge to profit and loss for bad and doubtful debts?","options":["₹6,000","₹1,800","₹8,800","₹5,800"],"answer":3,"explanation":"Charge = further bad debts 4,000 + new provision 5% × 96,000 = 4,800 − old provision 3,000 = ₹5,800. Computing 5% on debtors before the write-off gives ₹6,000.","difficulty":"hard","source":"Bank SO · CA Foundation"},
  {"id":"mgmt-accounting-670","question":"Which of these is capital expenditure?","options":["Repainting the factory building every three years","Wages paid to workers who installed a new machine","Replacing worn-out tyres on a delivery van","Annual maintenance contract for existing machines"],"answer":1,"explanation":"Costs needed to bring a new asset to working condition, such as installation wages, are capitalised as part of its cost. Repainting, tyre replacement and maintenance only keep existing assets working and are revenue expenses.","difficulty":"moderate","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-671","question":"Under Ind AS 116 a lessee pays ₹1,00,000 at the END of each year for 5 years; the incremental borrowing rate is 10%. It also incurs initial direct costs of ₹10,000. At what amount is the right-of-use asset first recognised?","options":["₹3,79,079","₹4,16,987","₹3,89,079","₹5,10,000"],"answer":2,"explanation":"Lease liability = PV of payments = 1,00,000 × PVIFA(10%,5) = ₹3,79,079; the ROU asset adds initial direct costs: ₹3,89,079. ₹4,16,987 treats the payments as made in advance.","difficulty":"very-hard","source":"Big 4 audit · CA Intermediate"},
  {"id":"mgmt-accounting-672","question":"A retailer sells a phone bundled with a one-year service plan for ₹24,000. Stand-alone prices are ₹20,000 for the phone and ₹10,000 for the plan. Under Ind AS 115, how much revenue is recognised on the day of sale?","options":["₹16,000","₹20,000","₹24,000","₹14,000"],"answer":0,"explanation":"The price is allocated in proportion to stand-alone prices: phone = 24,000 × 20/30 = ₹16,000, recognised on delivery; ₹8,000 for the plan is recognised over the year. ₹20,000 uses the phone's stand-alone price.","difficulty":"hard","source":"Big 4 audit · CA Intermediate"},
  {"id":"mgmt-accounting-673","question":"A company is defending a lawsuit. Its lawyers consider an outflow possible but not probable, and the amount can be estimated. How is it treated under AS 29 / Ind AS 37?","options":["A provision is recognised at the estimated amount","A contingent liability is disclosed in the notes","It is ignored until judgment is delivered","A reserve is created out of retained earnings"],"answer":1,"explanation":"A provision needs a probable outflow. When it is only possible (and not remote), the obligation is a contingent liability, disclosed in the notes but not recognised.","difficulty":"moderate","source":"Big 4 audit · CA Intermediate"},
  {"id":"mgmt-accounting-674","question":"The year ends on 31 March and the accounts are approved on 20 May. Which events are ADJUSTING events? (1) On 15 April a major customer is declared insolvent; its financial trouble existed at 31 March. (2) On 10 April a fire destroys a warehouse. (3) On 5 May a court settles a case that was pending at 31 March.","options":["(1) and (3) only","(1) and (2) only","(2) and (3) only","(1), (2) and (3)"],"answer":0,"explanation":"Adjusting events give evidence of conditions existing at the reporting date: the customer's insolvency and the settlement of a case pending at year end. The fire arises after the year end, so it is non-adjusting (disclosed if material).","difficulty":"very-hard","source":"Big 4 audit · CA Intermediate"},
  {"id":"mgmt-accounting-675","question":"P pays ₹1,000 crore for 80% of S, whose identifiable net assets have a fair value of ₹1,000 crore. Non-controlling interest is measured at its proportionate share of net assets. What goodwill arises?","options":["₹0","₹240 crore","₹360 crore","₹200 crore"],"answer":3,"explanation":"Goodwill = consideration + NCI − net assets = 1,000 + 200 − 1,000 = ₹200 crore (equivalently 1,000 − 80% × 1,000). ₹240 crore would arise only if NCI were measured at a higher fair value of ₹240 crore.","difficulty":"hard","source":"Big 4 audit · CA Intermediate"},
  {"id":"mgmt-accounting-676","question":"A parent sells goods costing ₹80,000 to its 80%-owned subsidiary at cost plus 25%. At year end, 40% of these goods are still in the subsidiary's inventory. How much unrealised profit is eliminated on consolidation?","options":["₹10,000","₹6,400","₹8,000","₹20,000"],"answer":2,"explanation":"Sale price = 1,00,000, profit = 20,000; 40% unsold = ₹8,000, eliminated in full in consolidated accounts (the seller is the parent). Applying 25% to the selling price gives ₹10,000, and taking only 80% gives ₹6,400.","difficulty":"very-hard","source":"Big 4 audit · CA Intermediate"},
  {"id":"mgmt-accounting-677","question":"A transferee company issues 2 equity shares of ₹10 each at ₹15 for every 3 shares of the transferor and also pays ₹2 in cash per transferor share. The transferor has 30,000 shares. What is the purchase consideration?","options":["₹2,60,000","₹3,00,000","₹3,60,000","₹4,50,000"],"answer":2,"explanation":"Shares issued = 30,000 × 2/3 = 20,000 at ₹15 = 3,00,000; cash = 30,000 × ₹2 = 60,000; total ₹3,60,000. Valuing the shares at face value gives ₹2,60,000.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-678","question":"A company issues fully paid bonus shares out of its general reserve. What is the effect on total shareholders' funds and on the number of shares?","options":["Total funds rise; shares rise","Total funds unchanged; shares rise","Total funds fall; shares unchanged","Total funds unchanged; shares unchanged"],"answer":1,"explanation":"A bonus issue only transfers reserves to share capital, so total shareholders' funds are unchanged while the number of shares rises; book value per share falls accordingly.","difficulty":"moderate","source":"CA Foundation · bank SO"},
  {"id":"mgmt-accounting-679","question":"A company buys back 10,000 of its ₹10 equity shares at ₹30 each, wholly out of free reserves. How much must it transfer to the capital redemption reserve?","options":["₹3,00,000","₹2,00,000","₹1,00,000","₹0"],"answer":2,"explanation":"When shares are bought back out of free reserves, a sum equal to the nominal value of the shares bought back (10,000 × ₹10 = ₹1,00,000) is transferred to the CRR. The premium of ₹20 a share is met from reserves but is not part of the CRR.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-680","question":"A company redeems ₹5,00,000 of preference shares at a 10% premium. To help finance it, it makes a fresh issue of equity shares of ₹2,00,000 at par. How much must be transferred to the capital redemption reserve?","options":["₹5,00,000","₹3,50,000","₹2,00,000","₹3,00,000"],"answer":3,"explanation":"CRR = nominal value redeemed − proceeds of a fresh issue made for the purpose = 5,00,000 − 2,00,000 = ₹3,00,000. The ₹50,000 premium comes from securities premium or profits and does not go to the CRR.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-681","question":"The purchase of office furniture for ₹20,000 is debited to the purchases account. What type of error is this, and does it affect the trial balance?","options":["Error of commission; it disturbs the trial balance","Error of principle; the trial balance still agrees","Error of omission; the trial balance still agrees","Compensating error; it disturbs the trial balance"],"answer":1,"explanation":"Treating a capital item as revenue breaks an accounting principle; the debit is still the correct amount on the correct side, so the trial balance agrees. It overstates purchases and understates fixed assets.","difficulty":"moderate","source":"Bank SO · CA Foundation"},
  {"id":"mgmt-accounting-682","question":"A trader keeps incomplete records. His capital was ₹1,20,000 at the start of the year and ₹1,50,000 at the end. During the year he withdrew ₹30,000 and brought in ₹20,000 of fresh capital. What is his profit?","options":["₹60,000","₹80,000","₹20,000","₹40,000"],"answer":3,"explanation":"Profit = closing capital − opening capital + drawings − additional capital = 1,50,000 − 1,20,000 + 30,000 − 20,000 = ₹40,000. Treating fresh capital as income gives ₹60,000.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-683","question":"1,000 units costing ₹100 each are sent on consignment. The consignor pays ₹5,000 freight and the consignee pays ₹2,000 unloading charges; 800 units are sold. At what value is the unsold stock carried?","options":["₹21,400","₹20,000","₹21,000","₹22,800"],"answer":0,"explanation":"Unsold stock carries its share of all non-recurring costs incurred to bring goods to the consignee's place: 200 × (100 + 5 + 2) = ₹21,400. Leaving out the consignee's unloading cost gives ₹21,000.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-684","question":"Set-up costs of ₹1,20,000 are pooled for 60 set-ups. Product A needs 15 set-ups for a production run of 1,000 units. Under activity-based costing, what set-up cost is charged per unit of A?","options":["₹120","₹30","₹12","₹20"],"answer":1,"explanation":"Rate per set-up = 1,20,000/60 = ₹2,000; A's set-ups cost 15 × 2,000 = ₹30,000 for 1,000 units = ₹30 a unit. Charging by units across all products would hide that small runs drive more set-ups.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-685","question":"At 80% capacity the budget shows fixed costs ₹2,00,000, variable costs ₹4,00,000 and semi-variable costs ₹1,00,000 (60% fixed). What is the total budgeted cost at 100% capacity?","options":["₹8,75,000","₹8,00,000","₹8,10,000","₹7,85,000"],"answer":2,"explanation":"Variable: 4,00,000 × 100/80 = 5,00,000; semi-variable: 60,000 fixed + 40,000 × 1.25 = 1,10,000; plus fixed 2,00,000 = ₹8,10,000. Scaling every cost by 1.25 gives ₹8,75,000.","difficulty":"very-hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-686","question":"Product X earns a contribution of ₹40 per unit using 4 machine hours; Y earns ₹30 using 2 hours. Demand is 1,000 units of each, and only 4,000 machine hours are available. What is the maximum total contribution?","options":["₹40,000","₹50,000","₹45,000","₹60,000"],"answer":1,"explanation":"Rank by contribution per key-factor hour: Y ₹15, X ₹10. Make 1,000 Y (2,000 hours, ₹30,000), then 500 X with the remaining 2,000 hours (₹20,000): ₹50,000. Making X first gives ₹40,000.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-687","question":"A component costs ₹40 a unit in variable cost to make plus ₹20 of unavoidable fixed overhead; it can be bought for ₹50. The firm needs 2,000 units, and the freed capacity could be rented out for ₹30,000 a year. What should it do?","options":["Make, saving ₹10,000","Make, saving ₹20,000","Buy, saving ₹30,000","Buy, saving ₹10,000"],"answer":3,"explanation":"Relevant cost of making = variable 80,000 + forgone rent 30,000 = 1,10,000 against buying for 1,00,000, so buying saves ₹10,000. The unavoidable fixed overhead is irrelevant; without the rent option, making would save ₹20,000.","difficulty":"hard","source":"CA Intermediate · MBA placement"},
  {"id":"mgmt-accounting-688","question":"Which cost is relevant for a decision but never recorded in the books of account?","options":["Opportunity cost","Sunk cost","Committed fixed cost","Historical cost"],"answer":0,"explanation":"Opportunity cost, the benefit forgone from the best alternative, guides decisions but involves no transaction, so it is not recorded. Sunk and committed costs are recorded but irrelevant to future choices.","difficulty":"moderate","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-689","question":"Budget: 1,000 units at ₹50 each with a standard profit of ₹10 a unit. Actual: 1,100 units sold at ₹48. What is the sales volume variance in profit terms?","options":["₹5,000 favourable","₹2,200 adverse","₹1,000 favourable","₹3,000 favourable"],"answer":2,"explanation":"Sales volume (profit) variance = (actual − budgeted units) × standard profit = 100 × 10 = ₹1,000 favourable. ₹5,000 values the extra units at selling price, and ₹2,200 adverse is the price variance (1,100 × ₹2).","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-690","question":"Profit in the cost books is ₹50,000. Overheads were over-absorbed in the cost books by ₹4,000; dividend of ₹2,000 was received (financial books only); notional rent of ₹6,000 was charged only in the cost books. What is the profit in the financial books?","options":["₹54,000","₹62,000","₹46,000","₹58,000"],"answer":1,"explanation":"Over-absorption means cost books charged more than actual: +4,000. Dividend appears only in financial books: +2,000. Notional rent is charged only in cost books: +6,000. Financial profit = ₹62,000.","difficulty":"very-hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-691","question":"Under Ind AS 103 and Ind AS 36, how is goodwill acquired in a business combination treated after initial recognition?","options":["Amortised over its useful life, not exceeding 10 years","Amortised over 5 years and tested for impairment","Written off immediately against reserves","Not amortised; tested for impairment at least annually"],"answer":3,"explanation":"Under Ind AS, goodwill is not amortised; it is tested for impairment every year (and when there is an indication), and an impairment loss on goodwill is never reversed. Amortisation applies under the older AS framework.","difficulty":"hard","source":"Big 4 audit · CA Intermediate"},
  {"id":"mgmt-accounting-692","question":"A machine costs ₹6,00,000, has a residual value of ₹60,000 and an estimated working life of 1,80,000 machine hours. It runs 30,000 hours in year 1. What is year-1 depreciation under the units-of-production method?","options":["₹90,000","₹1,00,000","₹1,08,000","₹1,20,000"],"answer":0,"explanation":"Rate = (6,00,000 − 60,000)/1,80,000 = ₹3 per hour; 30,000 × 3 = ₹90,000. Ignoring the residual value gives ₹1,00,000.","difficulty":"moderate","source":"Bank SO · CA Foundation"},
  {"id":"mgmt-accounting-693","question":"A and B share profits 3:2. On C's admission the building is revalued upward by ₹40,000, stock is reduced by ₹10,000, the provision for doubtful debts is raised by ₹6,000 and an unrecorded liability of ₹4,000 is brought in. What is A's share of the revaluation result?","options":["Gain of ₹14,400","Gain of ₹10,000","Gain of ₹18,000","Gain of ₹12,000"],"answer":3,"explanation":"Net gain = 40,000 − 10,000 − 6,000 − 4,000 = ₹20,000, shared by the OLD partners 3:2, so A gets ₹12,000. Missing the unrecorded liability gives ₹14,400; splitting equally gives ₹10,000.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-694","question":"A firm's average profit is ₹1,20,000 and its capital employed ₹8,00,000; the normal rate of return is 10%. What is goodwill by capitalising super profits?","options":["₹1,20,000","₹12,00,000","₹4,00,000","₹3,60,000"],"answer":2,"explanation":"Super profit = 1,20,000 − 10% × 8,00,000 = 40,000; capitalised at 10%: 40,000/0.10 = ₹4,00,000. ₹12,00,000 capitalises the whole average profit, which values the business, not the goodwill.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-695","question":"A partner with a 1/4 share dies exactly 3 months into the financial year. The deed gives a deceased partner his share of profit up to death based on last year's profit, which was ₹1,20,000. How much is credited to his capital?","options":["₹7,500","₹30,000","₹10,000","₹2,500"],"answer":0,"explanation":"Profit for 3 months = 1,20,000 × 3/12 = 30,000; his 1/4 share = ₹7,500. ₹30,000 is his full-year share, and ₹10,000 wrongly applies a 1/3 share.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-696","question":"On dissolution, assets other than cash with a book value of ₹2,00,000 realise ₹1,70,000; liabilities of ₹80,000 are settled for ₹78,000; and realisation expenses are ₹3,000. What is the loss on realisation?","options":["₹33,000","₹31,000","₹27,000","₹30,000"],"answer":1,"explanation":"Loss = (2,00,000 − 1,70,000) − (80,000 − 78,000) + 3,000 = 30,000 − 2,000 + 3,000 = ₹31,000. Treating the saving on liabilities as a further loss gives ₹33,000.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-697","question":"Under Section 52 of the Companies Act, 2013, for which purpose may a company NOT use its securities premium account?","options":["Issuing fully paid bonus shares","Writing off preliminary expenses","Paying a dividend to equity shareholders","Providing the premium payable on redemption of debentures"],"answer":2,"explanation":"Securities premium is capital in nature; Section 52 permits bonus shares, writing off preliminary expenses and issue costs, premium on redemption, and buy-back. It cannot be distributed as dividend.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-698","question":"An issue of 1,00,000 shares is underwritten 60% by X and 40% by Y. Applications for 80,000 shares are received: 30,000 marked X, 20,000 marked Y and 30,000 unmarked. Unmarked applications are shared in the gross-liability ratio. What is X's net liability?","options":["30,000 shares","20,000 shares","15,000 shares","12,000 shares"],"answer":3,"explanation":"Gross: X 60,000, Y 40,000. Less marked: X 30,000, Y 20,000. Less unmarked in 60:40: X 18,000, Y 12,000. Net: X 12,000, Y 8,000 (total 20,000 unsubscribed). Ignoring unmarked applications gives 30,000.","difficulty":"very-hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-699","question":"A partner withdraws ₹2,000 at the BEGINNING of every month of the year. Interest on drawings is 10% a year. How much interest is charged?","options":["₹1,100","₹1,300","₹1,200","₹2,400"],"answer":1,"explanation":"Drawings made at the start of each month are outstanding for 6.5 months on average: 24,000 × 10% × 6.5/12 = ₹1,300. End-of-month drawings would give 5.5 months (₹1,100), and mid-month 6 months (₹1,200).","difficulty":"moderate","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-accounting-700","question":"A fire destroys stock. From the books: opening stock ₹40,000, purchases ₹1,60,000, sales ₹2,00,000 up to the fire; the gross profit is 25% of sales. Salvaged goods are worth ₹5,000. What is the stock lost in the fire?","options":["₹45,000","₹50,000","₹35,000","₹55,000"],"answer":0,"explanation":"Cost of sales = 75% × 2,00,000 = 1,50,000; stock at the fire = 40,000 + 1,60,000 − 1,50,000 = 50,000; loss = 50,000 − 5,000 = ₹45,000. Treating 25% as a markup on cost gives a cost of sales of 1,60,000 and ₹35,000.","difficulty":"hard","source":"CA Intermediate · bank SO"},
  {"id":"mgmt-accounting-701","question":"Credit sales are ₹7,30,000. Opening trade debtors were ₹50,000; at year end debtors are ₹90,000 and bills receivable ₹20,000 (opening bills nil). Using average receivables, what is the average collection period (365-day year)?","options":["35 days","45 days","30 days","40 days"],"answer":3,"explanation":"Trade receivables include bills receivable: average = (50,000 + 1,10,000)/2 = 80,000; daily sales = 2,000; period = 40 days. Leaving out bills receivable gives 35 days.","difficulty":"very-hard","source":"Bank SO · CA Intermediate"},
  {"id":"mgmt-accounting-702","question":"EBIT from operations is ₹3,00,000. Equity is ₹10,00,000 and long-term debt ₹5,00,000, of which ₹3,00,000 is invested in non-trade investments (whose income is excluded from EBIT). What is the return on capital employed?","options":["20%","25%","30%","15%"],"answer":1,"explanation":"Capital employed should exclude non-trade investments: 15,00,000 − 3,00,000 = 12,00,000; ROCE = 3,00,000/12,00,000 = 25%. Using the full ₹15 lakh gives 20%.","difficulty":"hard","source":"Bank SO · CA Intermediate"},
  {"id":"mgmt-accounting-703","question":"A company's profit after tax is ₹6,00,000, its tax rate is 25% and its interest expense is ₹2,00,000. What is its interest coverage ratio?","options":["4 times","3 times","5 times","6 times"],"answer":2,"explanation":"PBT = 6,00,000/0.75 = 8,00,000; EBIT = 8,00,000 + 2,00,000 = 10,00,000; coverage = 10,00,000/2,00,000 = 5 times. Using PBT gives 4 times and PAT 3 times.","difficulty":"hard","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-704","question":"A company with 10 lakh equity shares on 1 April issues 4 lakh more at full market price on 1 October. Profit for the year to 31 March is ₹50 lakh. What is basic EPS?","options":["₹3.57","₹4.55","₹5.00","₹4.17"],"answer":3,"explanation":"Weighted shares = 10 + 4 × 6/12 = 12 lakh; EPS = 50/12 = ₹4.17. Using year-end shares (14 lakh) gives ₹3.57. A bonus issue would be treated as outstanding from the start, but a full-price issue is time-weighted.","difficulty":"very-hard","source":"CA Intermediate · Big 4 audit"},
  {"id":"mgmt-accounting-705","question":"Profit after tax is ₹100 lakh on 20 lakh equity shares. There are ₹50 lakh of 10% debentures convertible into 5 lakh shares; the tax rate is 25%. What is diluted EPS?","options":["₹4.00","₹4.15","₹4.20","₹5.00"],"answer":1,"explanation":"Add back after-tax interest saved: 5 × 0.75 = 3.75, so earnings = 103.75 over 25 lakh shares = ₹4.15. Adding back pre-tax interest gives ₹4.20; adding nothing gives ₹4.00.","difficulty":"very-hard","source":"CA Intermediate · Big 4 audit"},
  {"id":"mgmt-accounting-706","question":"Direct materials are ₹50,000, direct labour ₹30,000, direct expenses ₹5,000 and factory overheads ₹20,000. What is the prime cost?","options":["₹80,000","₹85,000","₹1,05,000","₹1,00,000"],"answer":1,"explanation":"Prime cost = direct materials + direct labour + direct expenses = ₹85,000. Adding factory overheads gives works cost (₹1,05,000 before WIP adjustment).","difficulty":"moderate","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-707","question":"Prime cost is ₹85,000 and factory overheads ₹20,000. Opening work-in-progress is ₹10,000 and closing work-in-progress ₹15,000. What is the factory (works) cost of production?","options":["₹1,10,000","₹1,05,000","₹1,00,000","₹95,000"],"answer":2,"explanation":"Works cost = 85,000 + 20,000 + opening WIP 10,000 − closing WIP 15,000 = ₹1,00,000. Reversing the WIP adjustment gives ₹1,10,000.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-708","question":"Opening WIP is 2,000 units (60% converted), 10,000 units are started, 9,000 units are completed and closing WIP is 3,000 units (40% converted). Under FIFO, what are the equivalent units for conversion?","options":["10,200","7,800","9,000","8,200"],"answer":2,"explanation":"FIFO: finish opening WIP 2,000 × 40% = 800, started and completed 7,000, closing 3,000 × 40% = 1,200: total 9,000. Weighted average would give 9,000 + 1,200 = 10,200.","difficulty":"very-hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-709","question":"A company's break-even sales are ₹6,00,000 and its margin of safety is 25% of actual sales. The P/V ratio is 30%. What is its profit?","options":["₹45,000","₹60,000","₹2,40,000","₹1,80,000"],"answer":1,"explanation":"BES is 75% of sales, so sales = 8,00,000 and MOS = 2,00,000; profit = MOS × P/V = 60,000. Taking MOS as 25% of break-even sales (1,50,000) gives ₹45,000.","difficulty":"hard","source":"CA Intermediate · bank SO"},
  {"id":"mgmt-accounting-710","question":"When sales are ₹2,00,000 the profit is ₹20,000; when sales are ₹3,00,000 the profit is ₹50,000. What is the break-even sales figure?","options":["₹1,33,333","₹1,00,000","₹66,667","₹1,50,000"],"answer":0,"explanation":"P/V = Δprofit/Δsales = 30,000/1,00,000 = 30%; fixed cost = 2,00,000 × 30% − 20,000 = 40,000; BES = 40,000/0.30 = ₹1,33,333.","difficulty":"very-hard","source":"CA Intermediate · bank SO"},
  {"id":"mgmt-accounting-711","question":"Budgeted fixed overhead is ₹1,00,000 for 10,000 units. Actual fixed overhead is ₹1,05,000 and actual output 9,000 units. What is the fixed overhead volume variance?","options":["₹5,000 adverse","₹15,000 adverse","₹10,000 adverse","₹10,000 favourable"],"answer":2,"explanation":"Volume variance = standard rate × (actual − budgeted output) = ₹10 × (9,000 − 10,000) = ₹10,000 adverse. Expenditure variance is ₹5,000 adverse, and the total ₹15,000 adverse.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-712","question":"The standard mix is 60% material A at ₹10/kg and 40% material B at ₹20/kg. Actual input is 1,000 kg: 500 kg of A and 500 kg of B. What is the material mix variance?","options":["₹1,000 adverse","₹1,000 favourable","₹3,000 adverse","₹2,000 adverse"],"answer":0,"explanation":"Revised standard quantities: A 600, B 400. Mix variance = SP × (RSQ − AQ): A 10 × 100 = 1,000 F; B 20 × (−100) = 2,000 A; net ₹1,000 adverse, because more of the dearer material was used.","difficulty":"very-hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-713","question":"Who is usually held responsible for an adverse material price variance?","options":["The production manager","The purchase manager","The sales manager","The quality-control manager"],"answer":1,"explanation":"The price variance arises at purchase, so it is the purchasing department's responsibility; usage variance is normally the production manager's.","difficulty":"moderate","source":"Bank SO · UGC NET Commerce"},
  {"id":"mgmt-accounting-714","question":"Purchases are ₹50,000 in January, ₹60,000 in February and ₹70,000 in March. 20% are paid in cash and the rest one month later. How much is paid to suppliers in March?","options":["₹70,000","₹68,000","₹56,000","₹62,000"],"answer":3,"explanation":"March cash purchases 20% × 70,000 = 14,000 plus 80% of February's 60,000 = 48,000: ₹62,000. Applying the percentages the other way round gives ₹68,000.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-accounting-715","question":"Division A makes a part with variable cost ₹60 and sells all it can make outside at ₹100. Division B wants to buy the part internally. Under the general rule (variable cost + opportunity cost), what is the minimum transfer price A should accept?","options":["₹100","₹60","₹80","₹40"],"answer":0,"explanation":"With no spare capacity, every internal unit displaces an external sale that earns ₹40 contribution: minimum = 60 + 40 = ₹100. With idle capacity it would be ₹60.","difficulty":"very-hard","source":"CA Intermediate · MBA placement"},
];

